async function routeApp(path, btn) {
  if (!path || path === '/') {
    showLanding();
    document.body.style.background = "var(--bg)";
    document.body.classList.remove('spatial-theme');
    document.body.classList.remove('spatial-theme-tutor');
    document.title = 'MandarinCourse — Learn Chinese Online with AI Tutor & HSK Lessons';
    var md = document.querySelector('meta[name="description"]');
    if (md) md.content = 'Master Chinese with MandarinCourse: AI tutor, HSK 1-9 lessons, grammar, character writing quizzes, SRS flashcards, document AI, translation. 10,000+ words, real-time speaking practice.';
    var ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle) ogTitle.content = document.title;
    syncSidebar('/');
    return;
  }
  
  // Guard app routes: require registration/sign-in
  if (path.startsWith('/app') || path === '/pinyin-chart') {
    if (supabaseClient) {
      const { data: { session } } = await supabaseClient.auth.getSession();
      if (!session) {
        console.log("No session found, redirecting to landing...");
        history.replaceState(null, '', '/');
        showLanding();
        toast(t("Please sign up or sign in to access this feature."), "var(--gold)", 4500);
        openAuthModal();
        return;
      }
    }
  }
  
  if (!APP_ROUTES[path]) path = '/app/tutor';
  var sectionId = APP_ROUTES[path];
  console.log("ROUTE_APP PATH:", path, "SECTION_ID:", sectionId);
  if (sectionId === 'tutor') {
    document.body.style.background = "var(--bg)";
    document.body.classList.add('spatial-theme');
    document.body.classList.add('spatial-theme-tutor');
    if (!tutLesson && typeof laoshiWelcome === 'function') {
      setTimeout(laoshiWelcome, 200);
    }
  } else if (sectionId) {
    document.body.style.background = "var(--bg)";
    document.body.classList.add('spatial-theme');
    document.body.classList.remove('spatial-theme-tutor');
  } else {
    document.body.style.background = "var(--bg)";
    document.body.classList.remove('spatial-theme');
    document.body.classList.remove('spatial-theme-tutor');
  }
  hideLanding();
  var s = getRouteSections();
  for (var i = 0; i < s.length; i++) s[i].style.display = s[i].id === sectionId ? '' : 'none';
  window.scrollTo(0, 0);
  var meta = ROUTE_META[path];
  if (meta) {
    document.title = meta.title;
    var md = document.querySelector('meta[name="description"]');
    if (md) md.content = meta.desc;
  }
  var ogTitle = document.querySelector('meta[property="og:title"]');
  if (ogTitle) ogTitle.content = document.title;
  document.querySelectorAll('.mnb').forEach(function(b) { b.classList.remove('act'); });
  document.querySelectorAll('.mnb-sm').forEach(function(b) { b.classList.remove('act'); });
  if (btn) btn.classList.add('act');
  syncSidebar(path);
  var toolsDD = document.getElementById('toolsDropdown');
  if (toolsDD) toolsDD.style.display = 'none';
  revealFu();
  if (typeof observeFu === 'function') setTimeout(observeFu, 60);
}
function navTo(selector, btn) {
  unlockIOSAudio();
  if (typeof selector === 'string' && selector.charAt(0) === '/') {
    history.pushState(null, '', selector);
    routeApp(selector, btn);
    return false;
  }
  var path = routeSectionMap[selector.replace('#', '')];
  if (path) {
    history.pushState(null, '', path);
    routeApp(path, btn);
    return false;
  }
  scrollToSection(selector);
  document.querySelectorAll('.mnb').forEach(function(b) { b.classList.remove('act'); });
  document.querySelectorAll('.mnb-sm').forEach(function(b) { b.classList.remove('act'); });
  if (btn) btn.classList.add('act');
  var toolsDD = document.getElementById('toolsDropdown');
  if (toolsDD) toolsDD.style.display = 'none';
}
