function getChineseVoice(){
  if (_cachedChineseVoice) return _cachedChineseVoice;
  const voices = speechSynthesis.getVoices().filter(v => v.lang.startsWith('zh'));
  if (voices.length === 0) return null;
  var preferredNames = ['xiaoxiao','huihui','yunxi','yunyang','yaoyao','kangkang','tingting','meijia','mei-jia','zhizhi','najia','zhimo','xiaochen','xiaohan','xiaomeng','xiaomo','xiaoshuang','xiaoyan','xiaoyou','xiaozhen','yunfeng','yunhao','yunxia','yunye','yunjian'];
  for (var i = 0; i < preferredNames.length; i++) {
    var found = voices.find(function(v) { return v.name.toLowerCase().includes(preferredNames[i]); });
    if (found) { _cachedChineseVoice = found; return found; }
  }
  var female = voices.find(function(v) { return /female|xiaoxiao|huihui|yaoyao|tingting|meijia/i.test(v.name); });
  if (female) { _cachedChineseVoice = female; return female; }
  var neural = voices.find(function(v) { return /neural|natural|premium|online/i.test(v.name); });
  if (neural) { _cachedChineseVoice = neural; return neural; }
  _cachedChineseVoice = voices[0];
  return _cachedChineseVoice;
}

// TTS audio cache
const ttsCache = {};
let _apiTtsActive = false;
let _apiTtsPending = false;
let _apiTtsAudio = null;
let _apiTtsSource = null; // active BufferSource from the boosted WebAudio TTS path
function isTtsPlaying() {
  try { if (window.speechSynthesis && window.speechSynthesis.speaking) return true; } catch(e) {}
  if (_apiTtsPending || _apiTtsActive) return true;
  // A created-but-not-yet-playing API audio must also block the mic: there is a
  // brief gap between new Audio(...) and its onplay firing where _apiTtsActive is
  // still false, but the speaker may already be ringing out. Treat any live audio
  // element as playing to avoid opening the mic into the tail of the greeting.
  if (_apiTtsAudio) return true;
  return false;
}
function stopApiTts() {
  _apiTtsPending = false;
  _apiTtsActive = false;
  try { if (window.speechSynthesis) window.speechSynthesis.cancel(); } catch(e) {}
  if (_apiTtsAudio) {
    try { _apiTtsAudio.pause(); _apiTtsAudio.currentTime = 0; } catch(e) {}
    _apiTtsAudio = null;
  }
  if (_apiTtsSource) {
    try { _apiTtsSource.disconnect(); } catch(e) {}
    try { _apiTtsSource.stop(); } catch(e) {}
    _apiTtsSource = null;
  }
  stopSpeakingAnimation();
}



function startSpeakingAnimation() {
  var el = document.getElementById('spatial-tutor-avatar');
  if (el) el.classList.add('speaking');
  var tc = document.querySelector('.tone-curve-wrap');
  if (tc) tc.classList.add('active');
  // Draw the tutor's tone curve from available pinyin
  var py = getCurrentPinyin();
  drawTutorToneCurve(py);
}

function getCurrentPinyin() {
  var wp = document.getElementById('tutWp');
  if (wp) {
    var p = wp.textContent.trim();
    if (p && p !== '--') return p;
  }
  if (tutLesson && tutLesson.dialogue && tutStep !== undefined && tutLesson.dialogue[tutStep]) {
    var line = tutLesson.dialogue[tutStep];
    var cn = line.cn || '';
    var parts = [];
    if (tutLesson.words) {
      tutLesson.words.forEach(function(w) {
        if (w.cn && cn.indexOf(w.cn) !== -1) {
          parts.push({ cn: w.cn, py: w.py || '', idx: cn.indexOf(w.cn) });
        }
      });
      parts.sort(function(a, b) { return a.idx - b.idx; });
    }
    if (parts.length > 0) {
      return parts.map(function(p) { return p.py; }).join(' ');
    }
  }
  return '';
}
function stopSpeakingAnimation() {
  var el = document.getElementById('spatial-tutor-avatar');
  if (el) el.classList.remove('speaking');
  var tc = document.querySelector('.tone-curve-wrap');
  if (tc) tc.classList.remove('active');
}

function blobToDataUrl(blob) {
  return new Promise((resolve, reject) => {
    const fr = new FileReader();
    fr.onload = () => resolve(fr.result);
    fr.onerror = () => reject(fr.error);
    fr.readAsDataURL(blob);
  });
}

function dataUrlToArrayBuffer(dataUrl) {
  try {
    const i = dataUrl.indexOf(',');
    const b64 = dataUrl.slice(i + 1);
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let k = 0; k < len; k++) bytes[k] = bin.charCodeAt(k);
    return bytes.buffer;
  } catch (e) { return null; }
}

// TTS from the Google translate endpoint is quite quiet (low-bitrate mono MP3),
// so we route playback through a Web Audio GainNode to boost it. iOS Safari only
// lets an <audio> element / AudioContext play after a real user gesture, so we
// create+resume the shared context AND bless a persistent <audio> element inside
// the first gesture (primeTtsAudioGesture). Desktop plays a fresh element.
const TTS_VOLUME_BOOST = 2.8;
let _ttsPersistAudio = null;
let _ttsCtx = null;
let _ttsGain = null;
function getTtsContext() {
  if (!_ttsCtx) {
    const AC = (window && (window.AudioContext || window.webkitAudioContext)) || (typeof AudioContext !== 'undefined' ? AudioContext : null);
    if (!AC) return null;
    try {
      _ttsCtx = new AC();
      _ttsGain = _ttsCtx.createGain();
      _ttsGain.gain.setTargetAtTime(TTS_VOLUME_BOOST, _ttsCtx.currentTime, 0.02);
      _ttsGain.connect(_ttsCtx.destination);
    } catch (e) { _ttsCtx = null; _ttsGain = null; }
  }
  if (_ttsCtx && _ttsCtx.state === 'suspended') {
    try { _ttsCtx.resume().catch ? _ttsCtx.resume().catch(() => {}) : _ttsCtx.resume(); } catch (e) {}
  }
  return _ttsCtx;
}

function primeTtsAudioGesture() {
  // Bless a persistent <audio> element on mobile (iOS needs a gesture-played element)
  if (isMobileDevice && !_ttsPersistAudio && window.Audio) {
    try {
      _ttsPersistAudio = new Audio();
      _ttsPersistAudio.src = 'data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEARKwAAIhYAQACABAAAABkYXRhAgAAAAAA';
      _ttsPersistAudio.load();
      _ttsPersistAudio.play().catch(() => {});
    } catch (e) {}
  }
  // Create + resume the shared gain-boosted AudioContext inside the gesture (iOS unlock)
  getTtsContext();
}

// Try to play through the boosted WebAudio GainNode. Returns true on success,
// false if unavailable/undecodable (caller then falls back to the <audio> element).
function tryPlayBoosted(src, rate) {
  let ctx;
  try { ctx = getTtsContext(); } catch (e) { ctx = null; }
  if (!ctx || !_ttsGain) return false;
  const buf = dataUrlToArrayBuffer(src);
  if (!buf) return false;
  try {
    const decoded = ctx.decodeAudioData(buf);
    // Block the mic/auto-listen the moment boosted playback is committed: the
    // decode+schedule below is async, and if _apiTtsActive stayed false through
    // that window, isTtsPlaying() would return false and the auto-listen would
    // open the mic into the tutor's just-starting speech -> self-echo (v70).
    _apiTtsPending = true;
    _apiTtsActive = true;
    // resolved promise => schedule the boosted playback
    decoded.then(function (aud) {
      try {
        const s = ctx.createBufferSource();
        s.buffer = aud;
        s.playbackRate = rate || 1.0;
        _apiTtsSource = s;
        _apiTtsActive = true;
        startSpeakingAnimation();
        s.onended = () => { _apiTtsActive = false; _apiTtsPending = false; _apiTtsSource = null; stopSpeakingAnimation(); };
        s.connect(_ttsGain);
        try { if (ctx.state === 'suspended') ctx.resume(); } catch (e2) {}
        s.start();
      } catch (e) {
        _apiTtsActive = false; _apiTtsPending = false; _apiTtsSource = null; _ttsCtx = null; _ttsGain = null; stopSpeakingAnimation();
      }
    }).catch(function () {
      // decode failed — fall back to the <audio> element path
      _apiTtsPending = false;
    });
    return true;
  } catch (e) { return false; }
}

function speakViaAPI(text, lang = 'zh-CN', rate = 1.0) {
  const cacheKey = lang + '|' + text;
  stopApiTts();
  const playFrom = (src) => {
    // Preferred: boosted WebAudio path (fixes the very quiet Google TTS).
    // Fallback: <audio> element (persistent on iOS so it's gesture-blessed).
    if (tryPlayBoosted(src, rate)) return;
    const audio = (isMobileDevice && _ttsPersistAudio) ? _ttsPersistAudio : new Audio();
    _apiTtsAudio = audio;
    try { audio.src = src; } catch (e) {}
    audio.playbackRate = rate;
    audio.onplay = () => { _apiTtsPending = false; _apiTtsActive = true; startSpeakingAnimation(); };
    audio.onended = () => { _apiTtsActive = false; _apiTtsAudio = null; stopSpeakingAnimation(); };
    audio.onerror = () => { _apiTtsActive = false; _apiTtsAudio = null; stopSpeakingAnimation(); };
    audio.play().catch(() => { _apiTtsActive = false; _apiTtsAudio = null; stopSpeakingAnimation(); });
  };
  // Prefer a cached data: URL. Unlike a revocable blob: URL, a data: URL never
  // becomes invalid, so replaying the same text (lesson lines, replay buttons)
  // cannot hit the "net::ERR_FILE_NOT_FOUND / revoked blob" failure.
  if (ttsCache[cacheKey]) { playFrom(ttsCache[cacheKey]); return; }
  _apiTtsPending = true;
  const engine = localStorage.getItem('tts_mode') === 'fish' ? '&engine=fish' : '';
  fetch('/api/tts?text=' + encodeURIComponent(text) + '&lang=' + encodeURIComponent(lang) + engine)
    .then(r => r.blob())
    .then(blob => blobToDataUrl(blob))
    .then(dataUrl => {
      ttsCache[cacheKey] = dataUrl;
      playFrom(dataUrl);
    })
    .catch(() => {
      _apiTtsPending = false;
      // Absolute fallback: try browser TTS
      tryFallbackTTS(text, lang, rate);
    });
}

function tryFallbackTTS(text, lang, rate) {
  if (!window.speechSynthesis) return;
  try {
    const u = new SpeechSynthesisUtterance(text);
    u.lang = lang;
    u.rate = rate || 1.0;
    u.onstart = () => startSpeakingAnimation();
    u.onend = () => stopSpeakingAnimation();
    u.onerror = () => stopSpeakingAnimation();
    const voices = speechSynthesis.getVoices().filter(v => v.lang.startsWith(lang.split('-')[0]));
    if (voices.length > 0) u.voice = voices[voices.length - 1];
    speechSynthesis.speak(u);
  } catch(e) {}
}

function getEffectiveSpeechRate() {
  const stored = localStorage.getItem('speech_rate');
  if (stored && stored !== '') return parseFloat(stored);
  const lvl = getChineseLevel();
  if (lvl === 'never') return 0.75;
  if (lvl === 'beginner') return 0.85;
  return 1.0;
}

function speak(t, rate){
  try {
    if (recognition) { try { recognition.onend = null; recognition.onerror = null; recognition.abort(); } catch(e) {} }
    srOn = false;
    updateMicUI('idle');
    stopApiTts();
    const hasGoodVoice = window.speechSynthesis && getChineseVoice() !== null;
    if (!hasGoodVoice || localStorage.getItem('tts_mode') !== 'auto') { speakViaAPI(t, 'zh-CN', rate || getEffectiveSpeechRate()); return; }
    if (!window.speechSynthesis) { speakViaAPI(t, 'zh-CN', rate || getEffectiveSpeechRate()); return; }
    const u = new SpeechSynthesisUtterance(t); u.lang = 'zh-CN'; u.rate = rate || getEffectiveSpeechRate();
    u.onstart = () => startSpeakingAnimation();
    u.onend = () => stopSpeakingAnimation();
    u.onerror = () => stopSpeakingAnimation();
    const voice = getChineseVoice(); if (voice) u.voice = voice;
    if (isMobileDevice) { try { speechSynthesis.speak(u); } catch(err) { speakViaAPI(t, 'zh-CN', rate || getEffectiveSpeechRate()); } }
    else {
      let isSpeaking = false; try { isSpeaking = speechSynthesis.speaking; } catch(e) {}
      if (isSpeaking) { try { if (!isMobileDevice) speechSynthesis.cancel(); } catch(e) {} setTimeout(() => { try { speechSynthesis.speak(u); } catch(err) {} }, 50); }
      else { try { speechSynthesis.speak(u); } catch(err) {} }
    }
  } catch(e) { console.error("speak error:", e); }
}

function sim(a,b){
  const cleanA = a.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()？。，！、\s]/g,"").toLowerCase();
  const cleanB = b.replace(/[.,\/#!$%\^&\*;:{}=\-_`~()？。，！、\s]/g,"").toLowerCase();
  
  if (cleanA === cleanB) return 1;
  if (!cleanA || !cleanB) return 0;
  
  // Calculate Levenshtein Distance
  const track = Array(cleanB.length + 1).fill(null).map(() => 
    Array(cleanA.length + 1).fill(null)
  );
  
  for (let i = 0; i <= cleanB.length; i += 1) track[i][0] = i;
  for (let j = 0; j <= cleanA.length; j += 1) track[0][j] = j;
  
  for (let i = 1; i <= cleanB.length; i += 1) {
    for (let j = 1; j <= cleanA.length; j += 1) {
      const indicator = cleanB[i - 1] === cleanA[j - 1] ? 0 : 1;
      track[i][j] = Math.min(
        track[i - 1][j] + 1, // deletion
        track[i][j - 1] + 1, // insertion
        track[i - 1][j - 1] + indicator // substitution
      );
    }
  }
  
  const distance = track[cleanB.length][cleanA.length];
  const maxLength = Math.max(cleanA.length, cleanB.length);
  return 1 - (distance / maxLength);
}


// ===== TUTOR =====
function startTutor(idx){
  const isPremium = hasPremiumAccess();
  const lesson = TL[idx];
  if (lesson && lesson.level && lesson.level.startsWith('HSK') && !isPremium) {
    const levelNum = parseInt(lesson.level.replace('HSK ', ''));
    if (levelNum >= 2) {
      showPremiumPaywall(lesson.level);
      return;
    }
  }
  window._renderedStep = -1;
  if (window._tutTO) clearTimeout(window._tutTO);
  tutLesson=TL[idx];tutStep=0;tutScores=[];
  resetTutorTotal();
  document.getElementById('tutChat').innerHTML='';
    addTutMsg('sys','<i class="fas fa-graduation-cap mr-1"></i> <b>'+t(tutLesson.title)+'</b> — '+tutLesson.level);
  if (isLiveAIActive) {
    addTutMsg('sys', '<i class="fas fa-robot mr-1"></i> <b>'+t('Live AI Tutor')+'</b> — '+t('Chat freely with the AI tutor'));
  }
  let vh='<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(120px,1fr));gap:6px;margin-top:8px">';
    tutLesson.words.forEach(w=>{vh+='<div style="background:var(--card2);padding:8px 10px;border-radius:10px;text-align:center"><div class="fc font-bold" style="font-size:18px">'+w.cn+'</div><div style="font-size:12px;color:var(--muted)">'+w.py+'</div><div style="font-size:12px;color:var(--fg2)">'+t(w.en)+'</div></div>'});
  vh+='</div>';
  addTutMsg('sys',vh);
  window._tutTO = setTimeout(()=>advanceTutor(),600);
  document.getElementById('tutStatus').textContent=t('Teaching...');
  setBtns(true);
}

function advanceTutor(){
  // Render each step exactly once, but NEVER drop a new step
  if (window._renderedStep === tutStep) return;
  window._renderedStep = tutStep;
  if(!tutLesson||tutStep>=tutLesson.dialogue.length){finishTutor();return}
  const line=tutLesson.dialogue[tutStep];
  const w=tutLesson.words.find(w=>line.cn.includes(w.cn));
  document.getElementById('tutWd').textContent=line.cn;
  document.getElementById('tutWp').textContent=w?w.py:'';
  document.getElementById('tutWm').textContent=t(line.en);
  document.getElementById('tutTip').style.display=w?'block':'none';
  if(w)document.getElementById('tutTip').textContent=t(w.tip);
  const tutWmEl = document.getElementById('tutWm');
  const tutTipEl = document.getElementById('tutTip');
  if (t(line.en) === line.en) ensureTutorTranslation(line.en, [tutWmEl]);
  if (w && t(w.tip) === w.tip) ensureTutorTranslation(w.tip, [tutTipEl]);
  var scoreWrapEl=document.getElementById('scoreWrap');if(scoreWrapEl)scoreWrapEl.style.display='none';
  if(line.who==='bot'){
    document.getElementById('tutHint').textContent=t('Type your response in the box below');
    document.getElementById('tutHint').style.color='var(--accent)';
    document.getElementById('tutStatus').textContent=t('Your turn')+' — '+t('type below');
    const msgEnId = 'tutMsgEn-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
    addTutMsg('bot','<div class="fc font-bold" style="font-size:20px;margin-bottom:4px">'+formatChineseTextWithRuby(line.cn)+'</div><div id="'+msgEnId+'" style="font-size:14px;color:var(--muted);margin-bottom:6px">'+t(line.en)+'</div><span style="font-size:11px;color:var(--blue);cursor:pointer" onclick="speak(\''+line.cn+'\')"><i class="fas fa-volume-high"></i> '+t('replay')+'</span>');
    if (t(line.en) === line.en) ensureTutorTranslation(line.en, [document.getElementById(msgEnId)]);
    setTimeout(()=>tutListen(line.cn),500);
  } else {
    document.getElementById('tutHint').textContent=t('Type Chinese below or press mic');
    document.getElementById('tutHint').style.color='var(--accent)';
    document.getElementById('tutStatus').textContent=t('Your turn')+' — '+t('type below');
  }
}

function tutListen(text){
  const isLive = localStorage.getItem('tutor_mode') === 'live';
  if(isLive) {
    if(currentLiveTarget) speak(currentLiveTarget);
  } else {
    const cn = text || (tutLesson && tutStep < tutLesson.dialogue.length ? tutLesson.dialogue[tutStep].cn : '');
    if(!cn) return;
    speak(cn);
  }
  const hWave = document.getElementById('hWave'); if(hWave) hWave.classList.remove('off');
  setTimeout(()=> { const hWave = document.getElementById('hWave'); if(hWave) hWave.classList.add('off'); }, 2000);
}

let _recAudioMode = false;

function startAudioRecording(btn, ic) {
  if (_recAudioMode) {
    console.log("Stopping audio recording...");
    clearTimeout(window._recAutoStopTimer);
    _recAudioMode = false;
    stopTutorPitchTrack();
    if (mediaRecorder && mediaRecorder.state !== 'inactive') {
      mediaRecorder.onstop = () => {
        console.log("MediaRecorder onstop fired, chunks:", audioChunks.length);
  if (window._recLevelIv) { clearInterval(window._recLevelIv); window._recLevelIv = null; }
  window._recAnalyser = null;
  window._recAudioCtxSampleRate = null;
        const peak = window._recPeak || 0;
        const ctxState = window._recAudioContextState || 'suspended';
        console.log("Recording peak level:", peak, "AudioContext state:", ctxState);
        const totalBytes = audioChunks.reduce((a, c) => a + (c ? c.size : 0), 0);
        console.log("Recording total bytes:", totalBytes);
        // Web-Audio analyser is the reliable signal: if the peak stays near
        // Only trigger silence warning if mic delivered near-zero amplitude AND audio bytes are negligible
        if (peak < 0.02 && ctxState === 'running' && totalBytes < 1000) {
          console.warn("Mic appears silent (peak " + peak.toFixed(3) + ", bytes " + totalBytes + "), skipping transcription");
          document.getElementById('tutHint').innerHTML = '<span style="color:var(--accent)"><i class="fas fa-exclamation-triangle"></i> ' + t('No sound detected from your microphone.') + '</span>';
          toast(t('Mic seems silent — check device and speak again.'), 'var(--gold)', 2500);
          setTimeout(() => {
            autoDetectMic().then(found => {
              if (found) { toast(t('Microphone switched to: ') + found + '. ' + t('Tap mic and speak again.'), 'var(--green)', 4500); }
              else { toast(t('No working mic found. Check Windows: Settings > Privacy & security > Microphone > allow desktop apps.'), 'var(--accent)', 7000); }
            });
          }, 400);
          return;
        }
        if (activeMicStream) {
          try { activeMicStream.getTracks().forEach(t => t.stop()); } catch(e) {}
          activeMicStream = null;
        }
        const chunks = audioChunks;
        audioChunks = [];
        if (chunks.length === 0) {
          console.warn("No audio chunks recorded");
          document.getElementById('tutHint').textContent = t('No audio recorded. Try again.');
          return;
        }
        console.log("Audio chunks:", chunks.length, "total size:", chunks.reduce((a,c) => a + c.size, 0));
        const mime = window._audioMime || 'audio/mp4';
        const blob = new Blob(chunks, { type: mime });
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64 = reader.result.split(',')[1];
          console.log("Audio base64 length:", base64.length, "mime:", mime);
          sendAudioToGemini(base64, 3, mime);
        };
        reader.readAsDataURL(blob);
      };
      mediaRecorder.stop();
    }
    srOn = false;
    updateMicUI('idle');
    return;
  }
  console.log("Starting audio recording...");
  _recAudioMode = true;
  window._recStartedAt = Date.now();
  window._recLastSound = Date.now();
  srOn = true;
  updateMicUI('recording');
  // Stop any TTS playback immediately to prevent feedback loop.
  // Both the browser SpeechSynthesis AND the API-based TTS audio element must
  // be stopped — the Google/Fish audio engine plays through an <audio> element
  // that speechSynthesis.cancel() does NOT touch, so without stopApiTts() the
  // mic opens while playback is still ringing out -> audible echo/feedback.
  if (!isMobileDevice) { try { speechSynthesis.cancel(); } catch(e) {} }
  stopApiTts();
  document.getElementById('tutHint').textContent = t('Recording... speak now (auto-stops when you pause)');
  const wave = document.getElementById('tutVoiceWave');
  if (wave) wave.style.display = 'inline-flex';
  document.getElementById('tutHint').style.color = 'var(--green)';
  currentTurnId = 'voice-' + Date.now();
  if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
    navigator.mediaDevices.getUserMedia(getMicAudioConstraints()).then(stream => {
      console.log("getUserMedia succeeded for recording fallback");
      // Record the RAW stream directly. Do NOT route it through a Web Audio
      // graph — a suspended/failed AudioContext can silently output silence even
      // when the microphone itself works fine.
      const recordStream = stream;
      activeMicStream = stream;
      window._recPeak = 0;
      window._recSoundMs = 0;
      window._recAudioContextState = 'suspended';
      try {
        const ctx2 = new (window.AudioContext || window.webkitAudioContext)();
        window._recAudioContextState = ctx2.state;
        if (ctx2.state === 'suspended') {
          ctx2.resume().then(() => {
            window._recAudioContextState = ctx2.state;
          }).catch(() => {});
        } else {
          window._recAudioContextState = ctx2.state;
        }
        const src2 = ctx2.createMediaStreamSource(stream);
        const an2 = ctx2.createAnalyser();
        an2.fftSize = 1024;
        src2.connect(an2);
        // Expose the working level-meter analyser so the tutor tone curve can reuse
        // the SAME AudioContext/AnalyserNode instead of creating a second one. On
        // Windows a duplicate AudioContext from the same mic stream can stay
        // suspended/silent, which kills pitch detection (autoCorrelate sees
        // silence) even though the level meter keeps working.
        window._recAnalyser = an2;
        window._recAudioCtxSampleRate = ctx2.sampleRate || 44100;
        try { startVoiceWaveAnimation(an2); } catch(e) {}
        const rdata = new Uint8Array(an2.fftSize);
        window._recLevelIv = setInterval(() => {
          an2.getByteTimeDomainData(rdata);
          let p = 0;
          for (let i = 0; i < rdata.length; i++) { const v = Math.abs(rdata[i] - 128) / 128; if (v > p) p = v; }
          if (p > window._recPeak) window._recPeak = p;
          const now = Date.now();
          const soundThreshold = 0.025;
          if (p >= soundThreshold) {
            window._recLastSound = now;
            window._recSoundMs = (window._recSoundMs || 0) + 120;
          } else if (_recAudioMode && window._recLastSound && window._recStartedAt && (now - window._recLastSound) > 1700 && (now - window._recStartedAt) > 2000) {
            console.log("Silence detected (1.7s), auto-stopping recording");
            window._recLastSound = 0;
            clearTimeout(window._recAutoStopTimer);
            const b = document.getElementById('tutMic'), i = document.getElementById('tutMicIc');
            if (_recAudioMode) startAudioRecording(b, i);
          }
        }, 120);
      } catch(e) { console.warn("Level meter unavailable:", e.message); }
      startTutorPitchTrack(stream);
      audioChunks = [];
      let mime = 'audio/mp4';
      if (typeof MediaRecorder.isTypeSupported === 'function') {
        if (!MediaRecorder.isTypeSupported(mime)) mime = 'audio/webm';
        if (!MediaRecorder.isTypeSupported(mime)) mime = 'audio/ogg;codecs=opus';
        if (!MediaRecorder.isTypeSupported(mime)) mime = '';
      }
      if (!mime) { console.error("No supported audio mime type"); return; }
      window._audioMime = mime;
      console.log("Using mime type:", mime);
      try {
        mediaRecorder = new MediaRecorder(recordStream, { mimeType: mime });
      } catch(e) {
        console.warn("Failed with", mime, "trying without mimeType");
        mediaRecorder = new MediaRecorder(recordStream);
        mime = mediaRecorder.mimeType || '';
        window._audioMime = mime;
      }
      mediaRecorder.ondataavailable = e => {
        if (e.data.size > 0) audioChunks.push(e.data);
      };
      try {
        mediaRecorder.start();
      } catch(e) {
        console.error("MediaRecorder start failed:", e);
        _recAudioMode = false;
        srOn = false;
        btn.classList.remove('on');
        ic.className = 'fas fa-microphone text-xl';
        ic.style.color = 'var(--accent)';
        document.getElementById('tutHint').textContent = t('Recording not supported on this device');
        return;
      }
      // Auto-stop after 10s so the user never has to tap again
      clearTimeout(window._recAutoStopTimer);
      window._recAutoStopTimer = setTimeout(() => {
        if (_recAudioMode) {
          const b = document.getElementById('tutMic'), i = document.getElementById('tutMicIc');
          startAudioRecording(b, i);
        }
      }, 10000);
    }).catch(err => {
      console.error("Audio recording fallback failed:", err);
      _recAudioMode = false;
      srOn = false;
      btn.classList.remove('on');
      ic.className = 'fas fa-microphone text-xl';
      ic.style.color = 'var(--accent)';
      document.getElementById('tutHint').textContent = t('Mic access denied. Use text box.');
    });
  } else {
    console.error("No getUserMedia available");
  }
}

function sendAudioToGemini(base64Audio, retries, mimeType) {
  if (retries === undefined) retries = 3;
  if (!mimeType) mimeType = window._audioMime || 'audio/mp4';
  console.log("Sending audio to Gemini, length:", base64Audio.length, "mime:", mimeType, "retries left:", retries);
  const payload = {
    contents: [{ role: "user", parts: [{ inlineData: { mimeType: mimeType, data: base64Audio } }] }],
    systemInstruction: "Transcribe the speech in this audio accurately. If the speaker is speaking Mandarin Chinese, return the Chinese characters. If they are speaking English or another language, return their words in that language. Return ONLY the transcription, nothing else.",
    sourceLang: getSpeechSrcLang()
  };
  document.getElementById('tutStatus').textContent = t('Transcribing...');
  const loaderId = 'loader-' + Date.now();
  const _tl = addTutMsg('bot', '<div id="' + loaderId + '" class="animate-pulse">'+t('Transcribing audio...')+'</div>');
  if (_tl) _tl.style.animation = 'none';
  fetch('/api/chat', {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  }).then(res => {
    console.log("Gemini response status:", res.status);
    if (res.status === 429 && retries > 0) {
      const wait = (4 - retries) * 3000;
      document.getElementById('tutHint').textContent = t('Rate limited, retrying in ') + (wait/1000) + t('s...');
      return new Promise(r => setTimeout(r, wait)).then(() => sendAudioToGemini(base64Audio, retries - 1));
    }
    if (!res.ok) return res.json().then(errData => { throw new Error(errData.error?.error?.message || errData.error?.message || errData.error || "HTTP " + res.status); });
    return res.json();
  }).then(data => {
    if (!data) return;
    console.log("Gemini response:", JSON.stringify(data).substring(0, 200));
    const reply = data.candidates?.[0]?.content?.parts?.[0]?.text || '(No response)';
    console.log("Gemini reply text:", reply.substring(0, 100));
    let transcript = reply.replace(/^TRANSCRIPTION:\s*/i, '').trim();
    // Reject obvious Whisper prompt echoes or known silence hallucinations
    const looksGarbage = /^(t he|mbc|subtitles|amara|transcribe|thank you for watching)$/i.test(transcript) || /^transcribe/i.test(transcript);
    if (looksGarbage) {
      console.warn("Rejected low-quality hallucination:", transcript);
      transcript = '';
    }
    if (transcript && transcript !== '(No response)' && !/no audio|no speech|没有音频|unable to transcribe|therefore no|no transcription/i.test(transcript)) {
      console.log("Transcription result:", transcript);
      document.getElementById('tutStatus').textContent = t('Heard: ') + transcript;
      // Live AI mode: send the transcript straight to the AI — no extra taps needed
      if (localStorage.getItem('tutor_mode') === 'live') {
        addLiveUserMsg(transcript);
        setTimeout(() => sendToGemini(transcript), 300);
      } else {
        // Show confirmation before sending to AI (study mode), then auto-send
        // after ~2s so the tutor always responds even if the user doesn't tap ✓.
        const confirmId = 'confirm-' + Date.now();
        const safeTr = transcript.replace(/'/g, "\\'");
        addTutMsg('user', '<div class="fc font-bold" style="font-size:18px;margin-bottom:4px;letter-spacing:1px">' + transcript + '</div><div style="font-size:13px;color:var(--muted)">(voice input)</div><div id="' + confirmId + '" style="margin-top:6px;display:flex;gap:8px;"><button onclick="confirmTranscript(\'' + safeTr + '\',\'' + loaderId + '\',\'' + confirmId + '\')" style="background:var(--green);color:#fff;border:none;padding:6px 16px;border-radius:4px;cursor:pointer;font-size:13px">✓ '+t('Use')+'</button><button onclick="rejectTranscript(\'' + confirmId + '\',\'' + loaderId + '\')" style="background:var(--accent);color:#fff;border:none;padding:6px 16px;border-radius:4px;cursor:pointer;font-size:13px">✕ '+t('Cancel')+'</button></div>');
        setTimeout(function() {
          const el = document.getElementById(confirmId);
          if (el && el.dataset.done !== '1') confirmTranscript(transcript, loaderId, confirmId);
        }, 2000);
      }
    } else {
      console.warn("Empty or no-speech transcription");
      document.getElementById('tutHint').innerHTML='<span style="color:var(--accent)"><i class="fas fa-exclamation-triangle"></i> '+t('No speech heard — check that your microphone is the correct input device and not muted in Windows settings, then tap mic and speak clearly.')+'</span>';
      document.getElementById('tutStatus').textContent = t('No speech detected');
      if ((typeof voiceModeActive !== 'undefined' && voiceModeActive) || localStorage.getItem('tutor_mode') === 'live') {
        setTimeout(() => { if (!srOn && !isTtsPlaying()) tutSpeak(); }, 1500);
      }
    }
    if (loaderId) { const el = document.getElementById(loaderId); if (el) el.remove(); }
  }).catch(err => {
    console.error("Audio transcription failed:", err);
    document.getElementById('tutHint').textContent = t('Transcription error: ') + err.message;
    document.getElementById('tutStatus').textContent = t('Error:') + ' ' + err.message;
    if (loaderId) { const el = document.getElementById(loaderId); if (el) el.remove(); }
  });
}

function confirmTranscript(transcript, loaderId, confirmId) {
  if (confirmId) { const el = document.getElementById(confirmId); if (el) el.dataset.done = '1'; }
  if (loaderId) { const el = document.getElementById(loaderId); if (el) el.remove(); }
  var tMode = localStorage.getItem('tutor_mode');
  if (tMode !== 'live' && tutLesson && tutStep < tutLesson.dialogue.length) {
    var target = tutLesson.dialogue[tutStep].cn;
    var score = Math.round(sim(transcript, target) * 100);
    processScore(transcript, score, target, 'voice-' + Date.now());
  } else {
    sendToGemini(transcript);
  }
}

function rejectTranscript(confirmId, loaderId) {
  if (confirmId) { const el = document.getElementById(confirmId); if (el) el.dataset.done = '1'; }
  if (loaderId) { const el = document.getElementById(loaderId); if (el) el.remove(); }
  const el = document.getElementById(confirmId);
  if (el) el.innerHTML = '<span style="color:var(--muted);font-size:11px">'+t('Cancelled — tap mic to try again')+'</span>';
  document.getElementById('tutHint').textContent = t('Cancelled. Tap mic to speak again.');
}

function tutSpeak(){
  const isLive = localStorage.getItem('tutor_mode') === 'live';
  if(!isLive) {
    if(!tutLesson||tutStep>=tutLesson.dialogue.length)return;
  }
  if(!micAvailable){
    const hasAPI = ('webkitSpeechRecognition' in window || 'SpeechRecognition' in window);
    const hasFallback = !!(window.MediaRecorder && navigator.mediaDevices && navigator.mediaDevices.getUserMedia);
    if (!hasAPI && !hasFallback) {
      toast(t('Your browser does not support microphone input. Use the text box instead.'),'var(--gold)');
      return;
    }
    micAvailable = true;
  }
  
  // iOS Audio Unlock: Only initialize if not on iOS Safari (where recording is bypassed)
  if (!isMobileDevice) {
    userAudioEl = new Audio();
    try {
      userAudioEl.src = 'data:audio/wav;base64,UklGRigAAABXQVZFZm10IBIAAAABAAEARKwAAIhYAQACABAAAABkYXRhAgAAAAAA';
      userAudioEl.load();
      userAudioEl.play().catch(e=>{});
    } catch(e) {}
  }
  
  // Cancel any active SpeechSynthesis before starting microphone
  if (!isMobileDevice) { speechSynthesis.cancel(); }
  stopApiTts();
  
  unlockIOSAudio();
  const target=localStorage.getItem('tutor_mode') === 'live' ? currentLiveTarget : tutLesson.dialogue[tutStep].cn;
  const btn=document.getElementById('tutMic'),ic=document.getElementById('tutMicIc');
  
  // On mobile, if mic permission has not been explicitly prompted/granted, trigger it via getUserMedia first
  if (isMobileDevice && !localStorage.getItem('mic_prompted')) {
    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
      document.getElementById('tutHint').textContent = t("Allow microphone access when prompted...");
      navigator.mediaDevices.getUserMedia(getMicAudioConstraints())
        .then(stream => {
          stream.getTracks().forEach(t => t.stop());
          localStorage.setItem('mic_prompted', 'true');
          console.log("Mobile microphone permission verified.");
          document.getElementById('tutHint').textContent = t('Listening...');
          // Auto-continue straight into listening — no need to tap again
          setTimeout(() => tutSpeak(), 300);
        })
        .catch(err => {
          console.error("Microphone permission denied:", err);
          document.getElementById('tutHint').innerHTML = '<span style="color:var(--accent2);font-size:11px;font-weight:700;"><i class="fas fa-exclamation-triangle"></i> '+t('Mic Denied: Tap aA (or settings icon) in Safari address bar → Website Settings → Set Microphone to Allow → Reload page.')+'</span>';
        });
      return;
    }
  }
  
  // If SpeechRecognition previously failed with no-speech on this machine,
  // skip it on subsequent taps — it only wastes ~6-8s before erroring anyway.
  // The recording fallback (raw stream → Gemini) is what actually works there.
  if (window._useAudioFallback || localStorage.getItem('_useAudioFallback') === 'true') {
    console.log("Direct to audio recording (SpeechRecognition not reliable on this device)");
    return startAudioRecording(btn, ic);
  }

  if(srOn){
    stopMediaRecorder();
    if (recognition) {
      try {
        recognition.stop();
      } catch(e) {}
    }
    srOn=false;
    updateMicUI('idle');
    return;
  }
  
  // On non-secure HTTP, SpeechRecognition requires HTTPS — skip straight to recording fallback
  if (window.location.protocol !== 'https:' && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') {
    window._useAudioFallback = true;
    localStorage.setItem('_useAudioFallback', 'true');
    return startAudioRecording(btn, ic);
  }
  // Auto-detect is only supported via Whisper server-side fallback
  if (getSpeechLang() === 'auto') {
    return startAudioRecording(btn, ic);
  }
  const SR=window.SpeechRecognition||window.webkitSpeechRecognition;
  if (!SR) {
    window._useAudioFallback = true;
    localStorage.setItem('_useAudioFallback', 'true');
    return startAudioRecording(btn, ic);
  }
  try {
    recognition=new SR();
    recognition.lang=getSpeechLang();
    recognition.interimResults=false;
    recognition.maxAlternatives=3;
    
    recognition.onstart=()=>{
      srOn=true;
      updateMicUI('recording');
      document.getElementById('tutHint').textContent=t('Listening...');
      const wave = document.getElementById('tutVoiceWave');
      if (wave) wave.style.display = 'inline-flex';
      document.getElementById('tutHint').style.color='var(--green)';
      currentTurnId = 'voice-' + Date.now();
      // On mobile (esp. Android) SpeechRecognition already owns the mic — requesting a second
      // audio stream via getUserMedia here can kill the recognition. Only run the pitch track
      // visualizer on desktop.
      if (!isMobileDevice && navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
        navigator.mediaDevices.getUserMedia(getMicAudioConstraints())
          .then(stream => {
            activeMicStream = stream;
            let trackStream = stream;
            try {
              const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
              const source = audioCtx.createMediaStreamSource(stream);
              const gain = audioCtx.createGain();
              gain.gain.value = 2.5;
              const dest = audioCtx.createMediaStreamDestination();
              source.connect(gain).connect(dest);
              trackStream = dest.stream;
            } catch(e) {}
            startTutorPitchTrack(trackStream);
          })
          .catch(e => { console.warn("Pitch track stream failed in SpeechRecognition:", e); });
      }
    };
    
    recognition.onresult=e=>{
      try {
        const isLive = localStorage.getItem('tutor_mode') === 'live';
        let best = (e.results && e.results[0] && e.results[0][0] && e.results[0][0].transcript || '').trim();
        stopMediaRecorder();
        if (!best) {
          srOn=false;
          updateMicUI('idle');
          document.getElementById('tutHint').innerHTML='<span style="color:var(--accent)"><i class="fas fa-exclamation-triangle"></i> '+t('No speech heard — check that your microphone is the correct input device and not muted in Windows settings, then tap mic and speak clearly.')+'</span>';
          return;
        }
        let bs = 0;
        if (isLive) {
          if (suggestedUserTarget) {
            bs = sim(best, suggestedUserTarget);
            for(let i=1;i<e.results[0].length;i++){
              const s = sim(e.results[0][i].transcript, suggestedUserTarget);
              if(s>bs){bs=s; best=e.results[0][i].transcript.trim();}
            }
          } else {
            bs = Math.min(0.85, best.length / 20);
          }
        } else if (target) {
          bs = sim(best, target);
          for(let i=1;i<e.results[0].length;i++){
            const s = sim(e.results[0][i].transcript, target);
            if(s>bs){bs=s; best=e.results[0][i].transcript.trim();}
          }
        }
        // Live AI mode: bypass scoring, direct AI conversation
        if (isLive) {
          addLiveUserMsg(best);
          setTimeout(() => sendToGemini(best), 300);
        } else {
          const percentageScore = Math.round(bs * 100);
          processScore(best, percentageScore, target, currentTurnId);
        }
      } catch(err) {
        console.error("tutSpeak result error:", err);
      }
      srOn=false;
      updateMicUI('idle');
    };
    
    recognition.onerror=(e)=>{
      console.error("Speak Mic Error:", e.error);
      stopMediaRecorder();
      srOn=false;
      updateMicUI('idle');
      if (e.error === 'no-speech' || e.error === 'network') {
        console.warn(e.error + " detected: switching to audio recording fallback");
        window._useAudioFallback = true;
        localStorage.setItem('_useAudioFallback', 'true');
        document.getElementById('tutHint').innerHTML='<span style="color:var(--gold)"><i class="fas fa-info-circle"></i> '+t('Auto-switching to recording... speak now!')+'</span>';
        clearTimeout(window._srFailTimer);
        // Go STRAIGHT to recording — no device sweep delay. The sweep uses Web
        // Audio levels which can misreport on some machines; the raw recording
        // itself works. If the recording turns out genuinely silent, the
        // byte-size check in onstop will run autoDetectMic.
        setTimeout(() => {
          console.log("Starting audio recording fallback now");
          startAudioRecording(btn, ic);
        }, 300);
      } else {
        document.getElementById('tutHint').innerHTML='<span style="color:var(--accent)"><i class="fas fa-exclamation-triangle"></i> '+t('Mic Error')+' ('+e.error+') — '+t('Try text box')+'</span>';
        
        // Safety guard: Disable voice mode on hardware/permission blocks to prevent loop freezes
        if (['not-allowed', 'audio-capture', 'service-not-allowed'].includes(e.error)) {
          console.warn("Disabling Voice Mode due to mic permission/hardware error:", e.error);
          if (typeof voiceModeActive !== 'undefined' && voiceModeActive) {
            voiceModeActive = false;
            localStorage.setItem('voice_mode_active', 'false');
            const vBtn = document.getElementById('tutVoiceModeBtn');
            if (vBtn) {
              vBtn.style.background = 'var(--card2)';
              vBtn.style.color = 'var(--muted)';
            }
            toast(t('Voice Mode disabled: Microphone access required'), 'var(--accent)');
          }
        }
        
        // Auto-retry listening in roleplay mode ONLY if voiceModeActive is still true
        if (isLiveAIActive && typeof voiceModeActive !== 'undefined' && voiceModeActive) {
          setTimeout(() => { if (voiceModeActive && !srOn) tutSpeak(); }, 2000);
        }
      }
    };
    
    recognition.onend=()=>{
      if (_recAudioMode) return;
      stopMediaRecorder();
      srOn=false;
      updateMicUI('idle');
    };
    
    recognition.start();
  } catch(e) {
    console.error("Failed to start SpeechRecognition:", e);
    window._useAudioFallback = true;
    localStorage.setItem('_useAudioFallback', 'true');
    startAudioRecording(btn, ic);
  }
}


function tutTypeSubmit(){
  const input=document.getElementById('tutTypeInput');const text=input.value.trim();
  if(!text){toast(t('Type Chinese characters first'),'var(--gold');return}
  
  // Conversational guided commands when lesson is not active
  const lowText = text.toLowerCase();
  if (!tutLesson) {
    if (['start', 'yes', 'ok', 'begin', 'go', 'play', 'y', 'sure', 'hello', 'hi', 'start lesson', '你好'].includes(lowText)) {
      input.value = '';
      startTutor(0);
      return;
    }
    if (['next', 'continue', 'forward', 'n', 'c', 'next lesson', '继续'].includes(lowText) && window._nextTutorIdx !== undefined && window._nextTutorIdx !== null) {
      input.value = '';
      startTutor(window._nextTutorIdx);
      return;
    }
  }
  
  // Live AI mode: bypass scoring, direct AI conversation
  if (localStorage.getItem('tutor_mode') === 'live') {
    input.value = '';
    addLiveUserMsg(text);
    setTimeout(() => sendToGemini(text), 300);
    return;
  }
  
  if (localStorage.getItem('tutor_mode') !== 'live') {
    if(!tutLesson||tutStep>=tutLesson.dialogue.length)return;
  }
  const target=localStorage.getItem('tutor_mode') === 'live' ? currentLiveTarget : tutLesson.dialogue[tutStep].cn;
  const sc=Math.round(sim(text,target)*100);
  processScore(text,sc);input.value='';
}

function processScore(text,sc,target,turnId){
  tutScores.push(sc);
  const avg=Math.round(tutScores.reduce((a,b)=>a+b,0)/tutScores.length);
  var totalEl=document.getElementById('tutTotal');
  if(totalEl){totalEl.textContent=avg;totalEl.classList.remove('ph-loading');totalEl.style.background='none';}
  const ring=document.getElementById('scoreRing');if(ring){ring.setAttribute('stroke-dashoffset',264-(264*sc/100));ring.setAttribute('stroke',sc>=80?'var(--green)':sc>=50?'var(--gold)':'var(--accent)');}
  const tutScEl=document.getElementById('tutSc');if(tutScEl){tutScEl.textContent=sc;tutScEl.style.color=sc>=80?'var(--green2)':sc>=50?'var(--gold)':'var(--accent2)';}
  const scoreWrapEl=document.getElementById('scoreWrap');if(scoreWrapEl)scoreWrapEl.style.display='block';
  let fb=sc>=80?'<span style="color:var(--green2)"><i class="fas fa-check-circle"></i> '+t('Great!')+'</span>':sc>=50?'<span style="color:var(--gold)"><i class="fas fa-star-half-stroke"></i> '+t('Getting there')+'</span>':'<span style="color:var(--accent2)"><i class="fas fa-rotate-left"></i> '+t('Keep practicing')+'</span>';
  document.getElementById('tutHint').innerHTML=fb;
  addTutMsg('user','<div class="fc font-bold" style="font-size:20px;margin-bottom:4px;letter-spacing:1px">'+colorCodePronunciation(target, text)+'</div><div style="font-size:13px;color:var(--muted)">'+t('Matched transcript:')+' "'+text+'" • '+t('Score:')+' '+sc+t('/100')+'</div><div id="'+turnId+'" style="margin-top:6px;"></div>');
  // Gamification: XP per spoken line
  addXP(2, 'Phrase spoken'); trackDaily('spoken');
  if (sc === 100) {
    localStorage.setItem('perfect_score_achieved', 'true');
    toast('💯 ' + t('Perfect score!'), 'var(--gold)', 3000);
    addXP(5, 'Perfect score');
    checkBadges();
  }
  
  const tMode = localStorage.getItem('tutor_mode');
  console.log('processScore tutor_mode:', tMode);
  if (tMode === 'live') {
    setTimeout(() => {
        sendToGemini(text);
    }, 1200);
  } else {
    if (sc < 80) {
      // Pronunciation coaching: replay, teach, and let the student retry
      setTimeout(() => {
        coachPronunciation(target);
      }, 1600);
    } else {
      setTimeout(()=>{tutStep++;advanceTutor()},1200);
    }
  }
}

// Replay the sentence, teach correct pronunciation, and let the student retry
function coachPronunciation(target) {
  if (!target) return;
  // Replay the sentence for the student
  speak(target);
  // Build a pronunciation teaching message
  var py = getCurrentPinyin();
  var meaning = '';
  var tip = '';
  if (tutLesson) {
    if (tutLesson.dialogue && tutLesson.dialogue[tutStep]) {
      meaning = tutLesson.dialogue[tutStep].en || '';
    }
    if (tutLesson.words) {
      var w = tutLesson.words.find(function(ww) { return ww.cn && target.indexOf(ww.cn) !== -1 && ww.tip; });
      if (w) tip = w.tip;
    }
  }
  var html = '<div style="padding:6px 0">'
    + '<div style="font-size:13px;color:var(--gold);font-weight:700;margin-bottom:6px"><i class="fas fa-ear-listen"></i> ' + t('Listen again, then repeat:') + '</div>'
    + '<div style="font-size:20px;font-weight:700;letter-spacing:1px;margin-bottom:4px">' + formatChineseTextWithRuby(target) + '</div>'
    + (py ? '<div style="font-size:14px;color:var(--neon-cyan);margin-bottom:4px;letter-spacing:1px">' + py + '</div>' : '')
    + (meaning ? '<div style="font-size:12px;color:var(--muted)">' + t('Meaning:') + ' <span id="coachMeaning-' + Date.now() + '">' + t(meaning) + '</span></div>' : '')
    + (tip ? '<div style="font-size:12px;color:var(--fg2);margin-top:4px"><i class="fas fa-lightbulb"></i> ' + t('Tip:') + ' <span id="coachTip-' + Date.now() + '">' + t(tip) + '</span></div>' : '')
    + '</div>';
  addTutMsg('bot', html);
  if (meaning) {
    const me = document.querySelector('[id^="coachMeaning-"]');
    if (me && t(meaning) === meaning) ensureTutorTranslation(meaning, [me]);
  }
  if (tip) {
    const te = document.querySelector('[id^="coachTip-"]');
    if (te && t(tip) === tip) ensureTutorTranslation(tip, [te]);
  }
  document.getElementById('tutHint').innerHTML = '<span style="color:var(--gold);font-weight:700"><i class="fas fa-microphone"></i> ' + t('Try again — press the mic and repeat the sentence') + '</span>';
  document.getElementById('tutStatus').textContent = t('Practice');
}

