function closeTutorMenu(){const m=document.getElementById('tutMenuDropdown');if(m)m.style.display='none'}
document.addEventListener('click',function(e){const m=document.getElementById('tutMenuDropdown'),b=document.getElementById('tutMenuBtn');if(m&&m.style.display==='block'&&b&&!b.contains(e.target)&&!m.contains(e.target))m.style.display='none'});
function addTutMsg(type,html){const d=document.createElement('div');d.className='cb '+(type==='bot'?'cai':type==='user'?'cus':type==='warn'?'cwarn':'csys');d.innerHTML=html;document.getElementById('tutChat').appendChild(d);requestAnimationFrame(()=>{document.getElementById('tutChat').scrollTop=9999});return d}
function setBtns(on){['tutPlayBtn','tutMic','tutSkipBtn','tutTypeInput','tutSubmitBtn','tutInputMic'].forEach(id=>document.getElementById(id).disabled=!on)}
function updateMicUI(state){
  const ic=document.getElementById('tutMicIc'),lb=document.getElementById('tutMicLabel'),btn=document.getElementById('tutMic');
  if(!ic||!lb||!btn)return;
  var tc = document.querySelector('.tone-curve-wrap');
  if(state==='recording'||state==='stop'){
    ic.className='fas fa-stop'; ic.style.color='var(--green)'; ic.style.fontSize='24px';
    btn.classList.add('on');
    lb.textContent='Stop';
    if (tc) tc.classList.add('active');
  } else {
    ic.className='fas fa-microphone'; ic.style.color='var(--accent)'; ic.style.fontSize='24px';
    btn.classList.remove('on');
    lb.textContent='Speak';
    if (tc) tc.classList.remove('active');
  }
}

// ===== MICROPHONE DEVICE SELECTION =====
let selectedMicId = localStorage.getItem('mic_device_id') || '';

function getMicAudioConstraints() {
  const opts = { echoCancellation: true, noiseSuppression: true, autoGainControl: true };
  if (selectedMicId) opts.deviceId = { exact: selectedMicId };
  return { audio: opts };
}

function loadMicDevices() {
  const sel = document.getElementById('micDeviceSelect');
  if (!sel || !navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return;
  navigator.mediaDevices.enumerateDevices().then(devices => {
    const mics = devices.filter(d => d.kind === 'audioinput');
    if (!mics.length) return;
    sel.innerHTML = '<option value="">' + t('Default microphone') + '</option>';
    mics.forEach(d => {
      const o = document.createElement('option');
      o.value = d.deviceId;
      o.textContent = d.label || (t('Microphone') + ' ' + sel.options.length);
      sel.appendChild(o);
    });
    sel.value = selectedMicId;
  }).catch(() => {});
}

function selectMicDevice(id) {
  selectedMicId = id || '';
  if (id) localStorage.setItem('mic_device_id', id);
  else localStorage.removeItem('mic_device_id');
  // User explicitly picked a mic — reset the "SpeechRecognition unreliable"
  // flag so we give it a fresh chance with the new device.
  window._useAudioFallback = false;
  localStorage.removeItem('_useAudioFallback');
  toast(selectedMicId ? t('Microphone selected') : t('Using default microphone'), 'var(--green)');
}

let _micTestCtx = null, _micTestStream = null, _micTestRaf = null;

function toggleMicTest() {
  const btn = document.getElementById('micTestBtn');
  const bar = document.getElementById('micTestLevel');
  const st = document.getElementById('micTestStatus');
  if (_micTestStream) { stopMicTest(); return; }
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    if (st) st.textContent = t('Microphone not supported in this browser.');
    return;
  }
  navigator.mediaDevices.getUserMedia(getMicAudioConstraints()).then(stream => {
    _micTestStream = stream;
    _micTestCtx = new (window.AudioContext || window.webkitAudioContext)();
    if (_micTestCtx.state === 'suspended') _micTestCtx.resume().catch(() => {});
    const src = _micTestCtx.createMediaStreamSource(stream);
    const an = _micTestCtx.createAnalyser();
    an.fftSize = 1024;
    src.connect(an);
    const data = new Uint8Array(an.fftSize);
    let silentTicks = 0;
    const draw = () => {
      an.getByteTimeDomainData(data);
      let peak = 0;
      for (let i = 0; i < data.length; i++) {
        const v = Math.abs(data[i] - 128) / 128;
        if (v > peak) peak = v;
      }
      bar.style.width = Math.min(100, Math.round(peak * 200)) + '%';
      if (peak > 0.08) {
        bar.style.background = 'var(--green)';
        silentTicks = 0;
        if (st) st.textContent = t('Mic is working — the browser hears you.');
      } else {
        bar.style.background = 'var(--red)';
        silentTicks++;
        if (silentTicks > 50 && st) st.textContent = t('No signal. Try another device above, or check Windows: Settings > Privacy & security > Microphone > allow desktop apps.');
      }
      _micTestRaf = requestAnimationFrame(draw);
    };
    draw();
    if (btn) { btn.textContent = t('Stop test'); btn.style.background = 'var(--red)'; }
    if (st) st.textContent = t('Speak now — the bar should fill...');
    clearTimeout(window._micTestTimer);
    window._micTestTimer = setTimeout(() => { if (_micTestStream) stopMicTest(); }, 8000);
  }).catch(e => {
    if (st) st.textContent = t('Mic access failed: ') + (e.name || e.message);
  });
}

function stopMicTest() {
  if (_micTestStream) { try { _micTestStream.getTracks().forEach(tr => tr.stop()); } catch (e) {} }
  if (_micTestRaf) cancelAnimationFrame(_micTestRaf);
  if (_micTestCtx) { try { _micTestCtx.close(); } catch (e) {} }
  _micTestStream = null; _micTestCtx = null; _micTestRaf = null;
  clearTimeout(window._micTestTimer);
  const btn = document.getElementById('micTestBtn');
  const bar = document.getElementById('micTestLevel');
  if (btn) { btn.textContent = t('Test microphone'); btn.style.background = 'var(--accent)'; }
  if (bar) { bar.style.width = '0%'; bar.style.background = 'var(--green)'; }
  loadMicDevices();
}

// Sweep every available mic and auto-select the first one that produces real
// audio LEVELS. Uses the Web Audio analyser — compressed byte size can't tell
// silence apart, but wave peaks can.
// Returns a Promise resolving to the device label (and auto-selects it) or null.
function autoDetectMic() {
  return new Promise(function(resolve) {
    let done = false;
    const finish = function(r) { if (!done) { done = true; resolve(r); } };
    if (!navigator.mediaDevices || !navigator.mediaDevices.enumerateDevices) return finish(null);
    navigator.mediaDevices.enumerateDevices().then(function(devices) {
      const mics = devices.filter(function(d) { return d.kind === 'audioinput'; });
      if (!mics.length) return finish(null);
      let idx = 0;
      const testOne = function() {
        if (done) return;
        if (idx >= mics.length) return finish(null);
        const d = mics[idx];
        const o = { audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true, deviceId: { exact: d.deviceId } } };
        navigator.mediaDevices.getUserMedia(o).then(function(stream) {
          let ctx;
          try { ctx = new (window.AudioContext || window.webkitAudioContext)(); }
          catch(e) { stream.getTracks().forEach(function(t){t.stop();}); idx++; testOne(); return; }
          if (ctx.state === 'suspended') ctx.resume().catch(function(){});
          const src = ctx.createMediaStreamSource(stream);
          const an = ctx.createAnalyser();
          an.fftSize = 1024;
          src.connect(an);
          const data = new Uint8Array(an.fftSize);
          let peak = 0, samples = 0;
          const iv = setInterval(function() {
            an.getByteTimeDomainData(data);
            let p = 0;
            for (let i = 0; i < data.length; i++) { const v = Math.abs(data[i] - 128) / 128; if (v > p) p = v; }
            if (p > peak) peak = p;
            samples++;
            if (samples >= 10) {
              clearInterval(iv);
              stream.getTracks().forEach(function(t){t.stop();});
              try { ctx.close(); } catch(e) {}
              if (peak > 0.02) {
                selectedMicId = d.deviceId;
                localStorage.setItem('mic_device_id', d.deviceId);
                if (typeof loadMicDevices === 'function') loadMicDevices();
                finish(d.label || (t('Microphone') + ' ' + (idx + 1)));
              } else {
                idx++; testOne();
              }
            }
          }, 120);
        }).catch(function() { idx++; testOne(); });
      };
      testOne();
    }).catch(function() { finish(null); });
  });
}

// ===== DOCUMENT UPLOAD =====
function handleDocUpload(input) {
  const file = input.files ? input.files[0] : input;
  if (!file) return;
  document.getElementById('docUploadPlaceholder').style.display = 'none';
  const info = document.getElementById('docUploadFileInfo');
  info.style.display = 'flex';
  info.onclick = function(e) { e.stopPropagation(); };
  document.getElementById('docFileName').textContent = file.name + ' (' + (file.size / 1024).toFixed(1) + ' KB)';
  document.getElementById('docResultArea').style.display = 'none';
  document.getElementById('docResultArea').innerHTML = '';
  toast(t('File loaded: ') + file.name, 'var(--gold)', 2000);
}

function initDocUpload() {
  let zone = document.getElementById('docDropZone');
  // Inject the upload section if missing (Railway may serve stale app.html)
  if (!zone) {
    const lessons = document.getElementById('lessons');
    if (lessons) {
      const sec = document.createElement('section');
      sec.id = 'docUpload'; sec.className = 'py-12 px-5'; sec.style.background = 'var(--bg2)';
      sec.innerHTML = '<div class="max-w-4xl mx-auto"><div class="text-center mb-6 fu"><div class="sl"><i class="fas fa-file-upload mr-1"></i> <span data-tr="Document AI">Document AI</span></div><h2 class="fc font-bold text-xl md:text-2xl mb-2" data-tr="Upload & Process Documents with AI">Upload & Process Documents with AI</h2><p class="text-sm" style="color:var(--fg2)" data-tr="Upload PDF, Word, text files, or handwritten images. The AI tutor will summarize, fix errors, or translate them.">Upload PDF, Word, text files, or handwritten images. The AI tutor will summarize, fix errors, or translate them.</p><div class="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold mt-2" style="background:rgba(212,166,79,.12);color:var(--gold)" data-tr="Premium Feature">Premium Feature</div></div><div class="cd p-6 md:p-8 text-center" style="border:2px dashed var(--border);border-radius:16px;cursor:pointer" id="docDropZone" onclick="document.getElementById(\'docFileInput\').click()"><input type="file" id="docFileInput" accept=".pdf,.docx,.txt,.jpg,.jpeg,.png,.webp,.bmp,.heic,.heif" style="display:none" onchange="handleDocUpload(this)"><div id="docUploadPlaceholder"><div class="w-16 h-16 rounded-full mx-auto mb-4 flex items-center justify-center" style="background:rgba(212,166,79,.1)"><i class="fas fa-cloud-upload-alt text-2xl" style="color:var(--gold)"></i></div><p class="font-bold text-sm mb-1" data-tr="Click to upload or drag & drop">Click to upload or drag & drop</p><p class="text-xs" style="color:var(--muted)" data-tr="PDF, DOCX, TXT, JPG, PNG — Max 20MB">PDF, DOCX, TXT, JPG, PNG — Max 20MB</p></div><div id="docUploadFileInfo" style="display:none" class="flex flex-col items-center gap-3"><div class="flex items-center gap-2 text-sm font-medium" style="color:var(--gold)" id="docFileName"></div><div class="flex flex-wrap justify-center gap-2" id="docActions"><button onclick="processDocument(\'summarize\')" class="bp text-xs py-2 px-4" data-tr="Summarize"><i class="fas fa-align-left mr-1"></i> Summarize</button><button onclick="processDocument(\'fix-errors\')" class="bp text-xs py-2 px-4" data-tr="Fix Errors"><i class="fas fa-pen-fancy mr-1"></i> Fix Errors</button><button onclick="processDocument(\'translate-zh2en\')" class="bp text-xs py-2 px-4" data-tr="Chinese→English"><i class="fas fa-language mr-1"></i> Chinese\u2192English</button><button onclick="processDocument(\'translate-en2zh\')" class="bp text-xs py-2 px-4" data-tr="English→Chinese"><i class="fas fa-language mr-1"></i> English\u2192Chinese</button><button onclick="processDocument(\'business-translate\')" class="bp text-xs py-2 px-4" data-tr="Business Translate"><i class="fas fa-briefcase mr-1"></i> Business Translate</button><button onclick="clearDocUpload()" class="bq text-xs py-2 px-4" style="color:var(--accent)" data-tr="Clear"><i class="fas fa-times mr-1"></i> Clear</button></div><div id="docResultArea" class="w-full text-left cd p-4 text-sm leading-relaxed" style="display:none;background:var(--card2);border-radius:12px;max-height:400px;overflow-y:auto"></div></div></div></div>';
      lessons.parentNode.insertBefore(sec, lessons);
      zone = document.getElementById('docDropZone');
      // Also add Doc nav button if not present
      if (!document.querySelector('.mnb[onclick*="docUpload"]')) {
        const progressBtn = document.querySelector('.mnb[onclick*="progress"]');
        if (progressBtn) {
          const docBtn = document.createElement('button');
          docBtn.className = 'mnb'; docBtn.setAttribute('data-tr', 'Doc');
          docBtn.innerHTML = '<i class="fas fa-file-upload"></i>Doc';
          docBtn.onclick = function() { navTo('#docUpload', this); };
          progressBtn.parentNode.insertBefore(docBtn, progressBtn);
        }
      }
    }
  }
  if (!zone) return;
  zone.addEventListener('dragover', function(e) { e.preventDefault(); this.style.borderColor = 'var(--gold)'; this.style.background = 'rgba(212,166,79,0.05)'; });
  zone.addEventListener('dragleave', function(e) { e.preventDefault(); this.style.borderColor = 'var(--border)'; this.style.background = 'transparent'; });
  zone.addEventListener('drop', function(e) {
    e.preventDefault();
    this.style.borderColor = 'var(--border)';
    this.style.background = 'transparent';
    const files = e.dataTransfer.files;
    if (files.length > 0) {
      const input = document.getElementById('docFileInput');
      const dt = new DataTransfer();
      dt.items.add(files[0]);
      input.files = dt.files;
      handleDocUpload(files[0]);
    }
  });
}

function clearDocUpload() {
  document.getElementById('docFileInput').value = '';
  document.getElementById('docUploadPlaceholder').style.display = 'block';
  document.getElementById('docUploadFileInfo').style.display = 'none';
  document.getElementById('docFileName').textContent = '';
  document.getElementById('docResultArea').style.display = 'none';
  document.getElementById('docResultArea').innerHTML = '';
}

function showDocActions() {
  const el = document.getElementById('docActions');
  if (el) el.style.display = 'flex';
}

function processDocument(action) {
  const fileInput = document.getElementById('docFileInput');
  let file = fileInput.files[0];
  if (!file) return toast(t('Please select a file first'), 'var(--accent)');
  const isPremium = hasPremiumAccess();
  if (!isPremium) {
    showPremiumPaywall('Document Upload');
    return;
  }
  const resultArea = document.getElementById('docResultArea');
  resultArea.style.display = 'block';
  resultArea.innerHTML = '<div class="text-center py-4"><i class="fas fa-spinner fa-spin text-lg" style="color:var(--gold)"></i><div class="mt-1" style="color:var(--muted)">Processing document...</div></div>';
  document.getElementById('docActions').style.display = 'none';
  
  // Images go to client-side OCR — use moderate compression for readability
  const imgExts = ['.jpg', '.jpeg', '.png', '.webp', '.bmp', '.heic', '.heif'];
  const isImg = file.type.startsWith('image/') || imgExts.some(e => file.name.toLowerCase().endsWith(e));
  if (isImg) {
    const img = new Image();
    img.onload = function() {
      const canvas = document.createElement('canvas');
      let w = img.width, h = img.height;
      const maxDim = 1200;
      if (w > h && w > maxDim) { h = h * maxDim / w; w = maxDim; }
      else if (h > maxDim) { w = w * maxDim / h; h = maxDim; }
      canvas.width = w; canvas.height = h;
      canvas.getContext('2d').drawImage(img, 0, 0, w, h);
      canvas.toBlob(function(blob) {
        if (!blob) { sendDoc(file, action, resultArea); return; }
        console.log('Compressed', file.name, 'to', (blob.size/1024).toFixed(1)+'KB', w+'x'+h);
        sendDoc(new File([blob], file.name, { type: 'image/jpeg' }), action, resultArea);
      }, 'image/jpeg', 0.6);
    };
    img.onerror = function() { sendDoc(file, action, resultArea); };
    img.src = URL.createObjectURL(file);
  } else {
    sendDoc(file, action, resultArea);
  }
}

function sendDoc(file, action, resultArea) {
  // Images: run OCR client-side, then process text via AI
  if (file.type.startsWith('image/') || ['.jpg','.jpeg','.png','.webp','.bmp'].some(e => file.name.toLowerCase().endsWith(e))) {
    resultArea.innerHTML = '<div class="text-center py-4"><i class="fas fa-spinner fa-spin text-lg" style="color:var(--gold)"></i><div class="mt-1" style="color:var(--muted)">Running OCR...</div></div>';
    const reader = new FileReader();
    reader.onload = async function() {
      try {
        if (typeof Tesseract === 'undefined') {
          await new Promise((resolve, reject) => {
            const s = document.createElement('script');
            s.src = 'https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';
            s.onload = resolve; s.onerror = reject;
            document.head.appendChild(s);
          });
        }
        const img = new Image();
        img.onload = async function() {
          try {
            const r = await Tesseract.recognize(img, 'chi_sim+eng');
            const text = r.data.text.trim();
            if (!text) { resultArea.innerHTML = '<div style="color:var(--accent)" class="py-2"><b>No text detected</b>. Try a clearer photo.</div>'; showDocActions(); return; }
            resultArea.innerHTML = '<div class="text-center py-4"><i class="fas fa-spinner fa-spin text-lg" style="color:var(--gold)"></i><div class="mt-1" style="color:var(--muted)">Analyzing with AI...</div></div>';
            const resp = await fetch('/api/chat', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                contents: [{ parts: [{ text }] }],
                systemInstruction: 'summarize|fix-errors|translate-zh2en|translate-en2zh|business-translate'.split('|').includes(action)
                  ? ({'summarize':'You are a Chinese tutor. Summarize the document in Chinese and English.','fix-errors':'You are a Chinese tutor. Fix all errors and explain each correction.','translate-zh2en':'Translate Chinese to English preserving meaning and tone.','translate-en2zh':'Translate English to Chinese (Simplified) preserving meaning and tone.','business-translate':'You are a professional business translator. Translate and provide business context analysis.'})[action]
                  : 'You are a Chinese tutor. Summarize the document in Chinese and English.'
              })
            });
            const d = await resp.json();
            const t = d.candidates?.[0]?.content?.parts?.[0]?.text || 'No response';
            resultArea.innerHTML = '<div class="font-bold mb-1" style="color:var(--gold)">' + actionLabels[action] + '</div><div style="color:var(--fg);white-space:pre-wrap">' + escapeHtml(t) + '</div>';
            showDocActions();
          } catch (e) {
            resultArea.innerHTML = '<div style="color:var(--accent)" class="py-2"><b>Analysis failed:</b> ' + escapeHtml(e.message) + '</div>';
            showDocActions();
          }
        };
        img.src = reader.result;
      } catch (e) {
        resultArea.innerHTML = '<div style="color:var(--accent)" class="py-2"><b>OCR load failed:</b> ' + escapeHtml(e.message) + '</div>';
        showDocActions();
      }
    };
    reader.readAsDataURL(file);
    return;
  }
  // Non-image files: use server endpoint
  const formData = new FormData();
  formData.append('document', file);
  formData.append('action', action);
  fetch('/api/upload-document', { method: 'POST', body: formData })
    .then(r => r.json())
    .then(data => {
      if (data.error) {
        const msg = typeof data.error === 'object' ? (data.error.error || JSON.stringify(data.error)) : data.error;
        resultArea.innerHTML = '<div style="color:var(--accent)" class="py-2"><b>Error:</b> ' + escapeHtml(msg.slice(0, 500)) + '</div>';
        showDocActions();
        return;
      }
      resultArea.innerHTML = '<div class="font-bold mb-1" style="color:var(--gold)">' + actionLabels[action] + '</div>'
        + '<div style="color:var(--fg);white-space:pre-wrap">' + escapeHtml(data.response) + '</div>';
      showDocActions();
    })
    .catch(err => {
      resultArea.innerHTML = '<div style="color:var(--accent)" class="py-2"><b>Upload failed:</b> ' + escapeHtml(err.message) + '</div>';
      showDocActions();
    });
}

window.actionLabels = window.actionLabels || {
  'summarize': 'Summary',
  'fix-errors': 'Error Corrections',
  'translate-zh2en': 'Chinese → English Translation',
  'translate-en2zh': 'English → Chinese Translation',
  'business-translate': 'Business Translation'
};

function escapeHtml(text) {
  const d = document.createElement('div');
  d.textContent = text;
  return d.innerHTML;
}

function buildTutorTabs(){
  const c=document.getElementById('tutLvTabs');
  const g=document.getElementById('tutTopicBtns');
  if(!c||!g)return;
  c.innerHTML='';g.innerHTML='';
  const levels=[...new Set(TL.map(l=>l.level).filter(Boolean))];
  const lvOrder=['HSK 1','HSK 2','HSK 3','HSK 4','HSK 5','HSK 6','HSK 7','HSK 8','HSK 9'];
  levels.sort((a,b)=>lvOrder.indexOf(a)-lvOrder.indexOf(b));
  const sel=document.createElement('select');
  sel.className='tb-select';
  levels.forEach((lv,i)=>{
    const opt=document.createElement('option');
    opt.value=i;opt.textContent=t(lv);sel.appendChild(opt);
  });
  sel.onchange=()=>{
    const idx=parseInt(sel.value),lv=levels[idx];
    g.innerHTML='';
    const ts=document.createElement('select');ts.className='tb-select';
    const lessons=TL.filter(l=>l.level===lv);
    lessons.forEach((lesson,i)=>{
      const o=document.createElement('option');
      o.value=i;o.textContent=t(lesson.title);ts.appendChild(o);
    });
    ts.onchange=()=>{const ls=lessons[parseInt(ts.value)];if(ls)openTutorTopic(ls.title,idx);};
    g.appendChild(ts);
    if(lessons.length)ts.dispatchEvent(new Event('change'));
  };
  c.appendChild(sel);
  sel.dispatchEvent(new Event('change'));
}

