function playPy(el,py){document.querySelectorAll('.pyc.pl').forEach(e=>e.classList.remove('pl'));if(el&&el.classList)el.classList.add('pl');speak(py);setTimeout(()=>{if(el&&el.classList)el.classList.remove('pl')},600)}

// ===== GRAMMAR =====
let grammarLevel = 1;
let grPage = 0;
var perPage = 3;

function buildGrLvTabs() {
  const c = document.getElementById('grLvTabs');
  if (!c) return;
  c.innerHTML = '';
  const levels = ['HSK 1','HSK 2','HSK 3','HSK 4','HSK 5','HSK 6','HSK 7','HSK 8','HSK 9'];
  levels.forEach((l,i) => {
    const idx = i + 1;
    const b = document.createElement('button');
    b.textContent = l;
    b.className = 'px-4 py-2 rounded-full text-xs font-bold border-none cursor-pointer transition' + (idx === grammarLevel ? ' on' : '');
    b.style.cssText = (idx === grammarLevel) ? 'background:var(--accent);color:#fff' : 'background:var(--card2);color:var(--fg)';
    b.onclick = () => { grammarLevel = idx; grPage = 0; buildGrLvTabs(); buildGr(); };
    c.appendChild(b);
  });
}

function addSpeakToSentences(html) {
  return html.replace(/<span class="fc font-bold text-lg">([^<]+)<\/span>/g, (m, cn) => {
    const esc = cn.replace(/'/g, "\\'");
    return '<span class="fc font-bold text-lg">'+cn+'</span><button onclick="event.stopPropagation(); speak(\''+esc+'\', 0.7)" class="w-7 h-7 rounded-full inline-flex items-center justify-center text-[var(--blue)] bg-[rgba(72,152,213,.08)] hover:bg-[rgba(72,152,213,.15)] transition border-none cursor-pointer align-middle ml-1.5 flex-shrink-0" title="Listen" style="outline:none;vertical-align:middle;"><i class="fas fa-volume-high text-[10px]"></i></button>';
  });
}

function buildGr(){
  const g = document.getElementById('grGrid');
  if (!g) return;
  g.innerHTML = '';
  
  const filtered = GR.filter(gr => {
    const lvNum = parseInt(gr.lv.replace('HSK ',''));
    return lvNum === grammarLevel;
  });
  
  var totalPages = Math.max(1, Math.ceil(filtered.length / perPage));
  if (grPage >= totalPages) grPage = 0;
  var start = grPage * perPage;
  var pageItems = filtered.slice(start, start + perPage);
  
  pageItems.forEach(gr => {
    const d = document.createElement('div');
    d.className = 'flip';
    d.style.height = '260px';
    d.onclick = () => d.classList.toggle('on');
    
    d.innerHTML = `
      <div class="fi">
        <!-- Card Front -->
        <div class="ff">
          <div class="flex items-center justify-between mb-3">
            <span class="text-xs font-bold px-2 py-0.5 rounded-full" style="background:rgba(212,166,79,.1);color:var(--gold)">${gr.lv}</span>
            <i class="fas fa-rotate text-xs" style="color:var(--muted)"></i>
          </div>
          <h3 class="font-bold text-sm mb-2">${t(gr.t)}</h3>
          
          <div class="flex items-center justify-between gap-2 mb-1">
            <div class="fc text-lg font-bold text-white">${gr.cn}</div>
            <button onclick="event.stopPropagation(); speak('${gr.cn.replace(/'/g, "\'")}', 0.7)" class="w-7 h-7 rounded-full flex items-center justify-center text-[var(--blue)] bg-[rgba(72,152,213,.08)] hover:bg-[rgba(72,152,213,.15)] transition border-none cursor-pointer" title="${t('Listen')}">
              <i class="fas fa-volume-high text-[10px]"></i>
            </button>
          </div>
          
          <div class="text-xs font-semibold" style="color:var(--gold)">${gr.py}</div>
          <div class="text-xs mb-3 italic" style="color:var(--fg2); opacity:.85; margin-top:2px;">"${t(gr.en)}"</div>
          <p class="text-xs font-bold uppercase tracking-wider text-muted mt-2">${t(gr.f)}</p>
          <!-- Practice Button -->
          <button onclick="event.stopPropagation(); startGrammarPractice('${(gr.t||'').replace(/'/g, "\\'")}', '${(gr.cn||'').replace(/'/g, "\\'")}', '${(gr.en||'').replace(/'/g, "\\'")}')" class="absolute bottom-4 right-4 px-2 py-1 rounded text-[9px] font-bold border border-[var(--border)] cursor-pointer" style="background:var(--card2); color:var(--gold); outline:none;">
            <i class="fas fa-gamepad mr-1"></i>${t('Practice')}
          </button>
        </div>
        
        <!-- Card Back -->
        <div class="fb" style="overflow-y:auto">
          <div class="flex items-center justify-between mb-3">
            <span class="text-xs font-bold px-2 py-0.5 rounded-full" style="background:rgba(212,166,79,.1);color:var(--gold)">${gr.lv}</span>
            <i class="fas fa-rotate text-xs" style="color:var(--muted)"></i>
          </div>
          <h3 class="font-bold text-sm mb-3">${t(gr.t)}</h3>
          <button onclick="event.stopPropagation(); speak('${gr.cn.replace(/'/g, "\\'")}', 0.7)" class="w-7 h-7 rounded-full flex items-center justify-center text-[var(--blue)] bg-[rgba(72,152,213,.08)] hover:bg-[rgba(72,152,213,.15)] transition border-none cursor-pointer mx-auto mb-3" title="${t('Listen')}">
            <i class="fas fa-volume-high text-[10px]"></i>
          </button>
          <div class="text-[12.5px] leading-relaxed" style="color:var(--fg2)">${addSpeakToSentences(gr.b)}</div>
        </div>
      </div>
    `;
    g.appendChild(d);
  });
  
  // Page counter and arrows
  var navDiv = document.createElement('div');
  navDiv.className = 'flex items-center justify-center gap-4 mt-6';
  navDiv.style.gridColumn = '1 / -1';
  navDiv.innerHTML = '<button onclick="grNav(-1)" class="w-9 h-9 rounded-full flex items-center justify-center border-none cursor-pointer" style="background:var(--card2);color:var(--fg);outline:none"><i class="fas fa-chevron-left text-sm"></i></button>'
    + '<span class="text-xs font-semibold" style="color:var(--muted)">' + (grPage + 1) + ' / ' + totalPages + '</span>'
    + '<button onclick="grNav(1)" class="w-9 h-9 rounded-full flex items-center justify-center border-none cursor-pointer" style="background:var(--card2);color:var(--fg);outline:none"><i class="fas fa-chevron-right text-sm"></i></button>';
  g.appendChild(navDiv);
}

function grNav(dir) {
  var filtered = GR.filter(function(gr) {
    return parseInt(gr.lv.replace('HSK ','')) === grammarLevel;
  });
  var totalPages = Math.max(1, Math.ceil(filtered.length / perPage));
  grPage = (grPage + dir + totalPages) % totalPages;
  buildGr();
}

// ===== QUIZ =====

// ===== QUIZ SPEECH =====
function speakQuizWord() {
  if (typeof filteredQZ !== 'undefined' && typeof qIdx !== 'undefined') {
    const q = filteredQZ[qIdx];
    if (q && q.c) {
      speak(q.c, 0.7);
    }
  }
}


// ===== iOS SAFARI AUDIO UNLOCK =====
let iosAudioUnlocked = false;
function unlockIOSAudio() {
  if (iosAudioUnlocked) return;
  primeTtsAudioGesture();
  if (window.speechSynthesis) {
    try {
      const u = new SpeechSynthesisUtterance('');
      u.volume = 0;
      window.speechSynthesis.speak(u);
      iosAudioUnlocked = true;
      console.log("iOS Safari SpeechSynthesis unlocked via user gesture.");
    } catch(err) {
      console.error("Failed to unlock iOS SpeechSynthesis:", err);
    }
  }
}

function buildQzLvTabs() {
  const c = document.getElementById('qzLvTabs');
  if (!c) return;
  c.innerHTML = '';
  const levels = ['All','HSK 1','HSK 2','HSK 3','HSK 4','HSK 5','HSK 6','HSK 7','HSK 8','HSK 9'];
  levels.forEach((l,i) => {
    const b = document.createElement('button');
    b.textContent = l;
    b.className = 'px-4 py-2 rounded-full text-xs font-bold border-none cursor-pointer transition';
    b.style.cssText = (i === quizLevel) ? 'background:var(--accent);color:#fff' : 'background:var(--card2);color:var(--fg)';
    b.onclick = () => { quizLevel = i; buildQzLvTabs(); resetQuiz(); };
    c.appendChild(b);
  });
}
function resetQuiz() {
  const pool = quizLevel === 0 ? QZ : QZ.filter(q => q.l === quizLevel);
  filteredQZ = [...pool].sort(() => Math.random() - 0.5).slice(0, Math.min(10, pool.length));
  document.getElementById('qSt').style.display = 'block';
  document.getElementById('qAc').style.display = 'none';
  document.getElementById('qRe').style.display = 'none';
}
function startQ(){qIdx=0;qScore=0;qStartT=Date.now();document.getElementById('qSt').style.display='none';document.getElementById('qAc').style.display='block';document.getElementById('qRe').style.display='none';showQ()}
function showQ(){const q=filteredQZ[qIdx];document.getElementById('qN').textContent=qIdx+1;document.getElementById('qSc').textContent=qScore+' '+t('pts');document.getElementById('qBr').style.width=((qIdx+1)/filteredQZ.length*100)+'%';document.getElementById('qC').textContent=q.c;document.getElementById('qP').textContent=q.p;const o=document.getElementById('qOp');o.innerHTML='';q.o.forEach((opt,i)=>{const b=document.createElement('button');b.className='bq';b.textContent=opt;b.onclick=()=>ansQ(i,b);o.appendChild(b)});document.getElementById('qNW').style.display='none';speakQuizWord();}
function ansQ(i,btn){document.querySelectorAll('.bq').forEach(b=>b.disabled=true);if(i===filteredQZ[qIdx].a){btn.classList.add('ok');qScore+=10}else{btn.classList.add('no');document.querySelectorAll('.bq')[filteredQZ[qIdx].a].classList.add('ok');wrongAnswers.push({q:filteredQZ[qIdx],selected:i})}document.getElementById('qNW').style.display='block';document.getElementById('qNB').innerHTML=qIdx<filteredQZ.length-1?t('Next')+' <i class="fas fa-arrow-right ml-1.5"></i>':t('See Results')+' <i class="fas fa-trophy ml-1.5"></i>'}
function nxtQ(){if(qIdx<filteredQZ.length-1){qIdx++;showQ()}else showRes()}
function showRes(){
  const mins=Math.round((Date.now()-qStartT)/60000);
  let lv='HSK 1',de=t('Perfect starting point!'),ic='<i class="fas fa-seedling text-3xl" style="color:var(--green)"></i>',vo='150';
  recommendedLvIdx = 0;
  
  if(qScore>=70){
    lv='HSK 3';de=t('Solid HSK 3 foundation!');ic='<i class="fas fa-bolt text-3xl" style="color:var(--accent)"></i>';vo='600';
    recommendedLvIdx = 2;
  }else if(qScore>=40){
    lv='HSK 2';de=t('Ready for HSK 2!');ic='<i class="fas fa-book text-3xl" style="color:var(--blue)"></i>';vo='300';
    recommendedLvIdx = 1;
  }
document.getElementById('qAc').style.display='none';document.getElementById('qRe').style.display='block';document.getElementById('rIc').innerHTML=ic;document.getElementById('rTi').innerHTML=t('Your Level:')+' '+lv;document.getElementById('rDe').textContent=de;document.getElementById('rLv').textContent=lv;document.getElementById('rCo').textContent=qScore/10+t('/10');document.getElementById('rVo').textContent=vo;document.getElementById('rTm').textContent=mins+'m';
  document.getElementById('rRevBtn').style.display = wrongAnswers.length > 0 ? 'inline-flex' : 'none';
  // Save weak words
  if (wrongAnswers.length > 0) {
    let weak = JSON.parse(localStorage.getItem('weak_words') || '[]');
    wrongAnswers.forEach(w => {
      if (!weak.find(x => x.q.c === w.q.c)) weak.push(w.q);
    });
    localStorage.setItem('weak_words', JSON.stringify(weak));
  }
  // Gamification: XP for completing test
  addXP(Math.round(qScore / 2), 'Level test');
  if (qScore >= 80) addXP(10, 'Excellent test score');
  checkBadges();
}
function rstQ(){document.getElementById('qRe').style.display='none';document.getElementById('qSt').style.display='block';wrongAnswers=[]}

// ===== REVIEW MISTAKES =====
function showReviewMistakes() {
  const modal = document.getElementById('reviewModal');
  if (!modal || wrongAnswers.length === 0) return;
  const list = document.getElementById('reviewList');
  list.innerHTML = wrongAnswers.map(w => {
    const q = w.q;
    return '<div style="padding:12px;margin-bottom:10px;border-radius:12px;background:var(--card2);border:1px solid var(--border)">'
      + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">'
      + '<span style="font-size:20px;font-weight:bold;color:var(--fg)">' + q.c + '</span>'
      + '<span style="color:var(--fg2);font-size:13px">' + q.p + '</span>'
      + '<button onclick="speak(\''+q.c+'\',0.7)" style="width:28px;height:28px;border-radius:50%;border:none;background:var(--card);color:var(--blue);cursor:pointer;outline:none"><i class="fas fa-volume-high text-xs"></i></button>'
      + '</div>'
      + '<div style="font-size:12px;margin-bottom:4px"><span style="color:var(--muted)">' + t('Your answer:') + '</span> <span style="color:var(--accent);font-weight:600">' + q.o[w.selected] + '</span></div>'
      + '<div style="font-size:12px"><span style="color:var(--muted)">' + t('Correct:') + '</span> <span style="color:var(--green);font-weight:600">' + q.o[q.a] + '</span></div>'
      + '</div>';
  }).join('');
  modal.style.display = 'flex';
}

// ===== LISTENING QUIZ =====
function startListeningQuiz() {
  listenMode = true;
  const pool = quizLevel === 0 ? QZ : QZ.filter(q => q.l === quizLevel);
  if (pool.length === 0) { toast(t('No questions for this level'), 'var(--accent)', 2000); return; }
  listenQPool = [...pool].sort(() => Math.random() - 0.5).slice(0, Math.min(5, pool.length));
  listenQIdx = 0;
  listenQScore = 0;
  document.getElementById('listenQuizOverlay').style.display = 'flex';
  showListenQuestion();
}

let listenQPool = [], listenQIdx = 0, listenQScore = 0;

function showListenQuestion() {
  if (listenQIdx >= listenQPool.length) { showListenResult(); return; }
  const q = listenQPool[listenQIdx];
  const content = document.getElementById('listenQuizContent');
  content.innerHTML = '<div style="margin-bottom:16px"><div style="font-size:12px;color:var(--muted);margin-bottom:8px">' + t('Listen and choose the correct translation:') + '</div>'
    + '<button onclick="playListenAudio()" style="width:64px;height:64px;border-radius:50%;border:none;background:var(--accent);color:#fff;cursor:pointer;margin:0 auto 16px;display:flex;align-items:center;justify-content:center;outline:none;box-shadow:0 4px 20px rgba(200,53,37,0.4)" id="listenPlayBtn"><i class="fas fa-volume-high text-xl"></i></button>'
    + '<div style="font-size:11px;color:var(--muted)">' + t('Question') + ' ' + (listenQIdx+1) + '/' + listenQPool.length + '</div></div>'
    + '<div class="grid gap-2" id="listenOptions"></div>'
    + '<div id="listenFeedback" class="text-sm mt-4" style="min-height:24px"></div>';
  
  const optsDiv = document.getElementById('listenOptions');
  const ro = randomizeOptions(q.o, q.a);
  q.o = ro.shuffled;
  q.a = ro.a;
  q.o.forEach((opt, i) => {
    const b = document.createElement('button');
    b.className = 'bq';
    b.textContent = opt;
    b.onclick = () => answerListenQ(i, b);
    optsDiv.appendChild(b);
  });
  
  setTimeout(playListenAudio, 500);
}

function playListenAudio() {
  const q = listenQPool[listenQIdx];
  if (q && q.c) speak(q.c, 0.7);
}

function answerListenQ(i, btn) {
  document.querySelectorAll('#listenOptions .bq').forEach(b => b.disabled = true);
  const q = listenQPool[listenQIdx];
  const fb = document.getElementById('listenFeedback');
  if (i === q.a) {
    btn.classList.add('ok');
    listenQScore += 10;
    fb.innerHTML = '<span style="color:var(--green);font-weight:600">✓ ' + t('Correct!') + '</span>';
  } else {
    btn.classList.add('no');
    document.querySelectorAll('#listenOptions .bq')[q.a].classList.add('ok');
    fb.innerHTML = '<span style="color:var(--accent);font-weight:600">✗ ' + t('Correct:') + ' ' + q.o[q.a] + '</span> <span style="color:var(--muted)">(' + q.c + ')</span>';
  }
  setTimeout(() => { listenQIdx++; showListenQuestion(); }, 1500);
}

function showListenResult() {
  const content = document.getElementById('listenQuizContent');
  const pct = Math.round((listenQScore / (listenQPool.length * 10)) * 100);
  content.innerHTML = '<div style="font-size:40px;margin-bottom:12px">' + (pct >= 80 ? '🎉' : pct >= 50 ? '👍' : '💪') + '</div>'
    + '<h3 style="margin:0 0 6px;font-size:18px;color:var(--fg)">' + t('Listening Quiz Complete') + '</h3>'
    + '<p style="margin:0 0 20px;font-size:14px;color:var(--muted)">' + listenQScore + '/' + (listenQPool.length * 10) + ' ' + t('points') + '</p>'
    + '<button onclick="closeListenQuiz()" class="bp px-8 py-2.5 text-xs font-bold">' + t('Done') + '</button>';
  addXP(Math.round(listenQScore / 2), 'Listening quiz');
  checkBadges();
}

function closeListenQuiz() {
  document.getElementById('listenQuizOverlay').style.display = 'none';
  listenMode = false;
  grammarExIdx = 0;
  pronIdx = 0;
  pronScore = 0;
  examIdx = 0;
  examScore = 0;
  if (examTimer) { clearInterval(examTimer); examTimer = null; }
  storyIdx = 0;
  if (pronMediaRecorder && pronMediaRecorder.state === 'recording') {
    pronMediaRecorder.stop();
  }
}

// ===== THEME TOGGLE =====
function applyTheme(theme) {
  if (theme === 'light') {
    document.documentElement.style.setProperty('--bg', '#F5F0EB');
    document.documentElement.style.setProperty('--bg2', '#EDE8E2');
    document.documentElement.style.setProperty('--card', '#FFFFFF');
    document.documentElement.style.setProperty('--card2', '#F5F1EC');
    document.documentElement.style.setProperty('--border', '#E0D8D0');
    document.documentElement.style.setProperty('--fg', '#1A1614');
    document.documentElement.style.setProperty('--fg2', '#5A4E44');
    document.documentElement.style.setProperty('--muted', '#8A7A6A');
  } else {
    document.documentElement.style.setProperty('--bg', '#0D0A08');
    document.documentElement.style.setProperty('--bg2', '#141110');
    document.documentElement.style.setProperty('--card', '#1E1915');
    document.documentElement.style.setProperty('--card2', '#28221C');
    document.documentElement.style.setProperty('--border', '#362E25');
    document.documentElement.style.setProperty('--fg', '#F5EDE6');
    document.documentElement.style.setProperty('--fg2', '#B5A597');
    document.documentElement.style.setProperty('--muted', '#7A6B5D');
  }
  localStorage.setItem('theme', theme);
  const toggle = document.getElementById('themeToggle');
  if (toggle) toggle.checked = theme === 'light';
}

function toggleTheme(light) {
  applyTheme(light ? 'light' : 'dark');
}

function initTheme() {
  const saved = localStorage.getItem('theme') || 'dark';
  applyTheme(saved);
}

// ===== SHARE PROGRESS =====
function shareProgress() {
  const xp = getXP();
  const level = getLevel(xp);
  const streak = parseInt(localStorage.getItem('streak_days') || '0');
  const badges = JSON.parse(localStorage.getItem('earned_badges') || '[]');
  const text = '🇨🇳 I\'ve earned ' + xp + ' XP, Level ' + level + ', ' + streak + '-day streak, and ' + badges.length + ' badges on MandarinCourse! Learn Chinese with AI: https://mandarincourse.app';
  
  if (navigator.share) {
    navigator.share({ title: 'My MandarinCourse Progress', text: text, url: 'https://mandarincourse.app' }).catch(() => {});
  } else {
    navigator.clipboard.writeText(text).then(() => {
      toast(t('Progress copied to clipboard! Share it anywhere 🎉'), 'var(--green)', 3000);
    }).catch(() => {
      // Fallback: show in a prompt
      prompt(t('Copy this text:'), text);
    });
  }
}

// ===== DAILY CHALLENGE =====
function checkDailyChallenge() {
  const today = new Date().toDateString();
  const last = localStorage.getItem('daily_challenge_date');
  const done = localStorage.getItem('daily_challenge_done');
  dailyChallengeDone = last === today && done === 'true';
  updateDailyChallengeUI();
}

function startDailyChallenge() {
  if (dailyChallengeDone) { toast(t('Already completed today\'s challenge!'), 'var(--gold)', 2000); return; }
  // Pick one random question from any level
  const pool = QZ.length > 0 ? QZ : [{l:1,q:'Nǐ hǎo',c:'你好',o:['Hello','Goodbye','Thanks','Sorry'],a:0}];
  const q = pool[Math.floor(Math.random() * pool.length)];
  
  const content = document.getElementById('listenQuizContent');
  if (!content) return;
  document.getElementById('listenQuizOverlay').style.display = 'flex';
  
  content.innerHTML = '<div style="margin-bottom:16px"><div style="font-size:24px;margin-bottom:8px">🔥</div>'
    + '<div style="font-size:12px;color:var(--muted)">' + t('Daily Challenge') + '</div></div>'
    + '<div style="font-size:22px;font-weight:bold;color:var(--fg);margin-bottom:4px">' + q.c + '</div>'
    + '<div style="font-size:13px;color:var(--fg2);margin-bottom:16px">' + q.p + '</div>'
    + '<div class="grid gap-2" id="dailyOptions"></div>'
    + '<div id="dailyFeedback" class="text-sm mt-4" style="min-height:24px"></div>';
  
  const optsDiv = document.getElementById('dailyOptions');
  const ro = randomizeOptions(q.o, q.a);
  q.o = ro.shuffled;
  q.a = ro.a;
  q.o.forEach((opt, i) => {
    const b = document.createElement('button');
    b.className = 'bq';
    b.textContent = opt;
    b.onclick = () => {
      document.querySelectorAll('#dailyOptions .bq').forEach(x => x.disabled = true);
      const fb = document.getElementById('dailyFeedback');
      if (i === q.a) {
        b.classList.add('ok');
        fb.innerHTML = '<span style="color:var(--green);font-weight:600">✓ ' + t('Correct! +15 XP bonus') + '</span>';
        addXP(15, 'Daily challenge');
        dailyChallengeDone = true;
        localStorage.setItem('daily_challenge_date', new Date().toDateString());
        localStorage.setItem('daily_challenge_done', 'true');
        // Track daily challenge streak
        let streak = parseInt(localStorage.getItem('daily_challenge_streak') || '0');
        streak++;
        localStorage.setItem('daily_challenge_streak', streak.toString());
        toast('🔥 ' + streak + '-' + t('day daily challenge streak!'), 'var(--gold)', 2500);
      } else {
        b.classList.add('no');
        document.querySelectorAll('#dailyOptions .bq')[q.a].classList.add('ok');
        fb.innerHTML = '<span style="color:var(--accent);font-weight:600">✗ ' + t('Correct:') + ' ' + q.o[q.a] + '</span>';
      }
      updateDailyChallengeUI();
      checkBadges();
    };
    optsDiv.appendChild(b);
  });
}

function updateDailyChallengeUI() {
  const el = document.getElementById('dailyChallengeStatus');
  if (!el) return;
  if (dailyChallengeDone) {
    const streak = localStorage.getItem('daily_challenge_streak') || '0';
    el.innerHTML = '<span style="color:var(--green)">✓ ' + t('Done today') + '</span> <span style="color:var(--gold)">🔥 ' + streak + 'd</span>';
  } else {
    el.innerHTML = '<span style="color:var(--accent)">⚡ ' + t('Ready!') + '</span>';
  }
}

// ===== FEEDBACK =====
function showFeedbackModal() {
  document.getElementById('feedbackModal').style.display = 'flex';
  document.getElementById('feedbackResult').textContent = '';
  document.getElementById('feedbackText').value = '';
}

async function submitFeedback() {
  const type = document.getElementById('feedbackType').value;
  const text = document.getElementById('feedbackText').value.trim();
  if (!text) { toast(t('Please enter your feedback'), 'var(--accent)', 2000); return; }
  try {
    const r = await fetch('/api/feedback', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ type, text, user: localStorage.getItem('supabase_user_email') || 'anonymous' })
    });
    const d = await r.json();
    if (d.ok) {
      document.getElementById('feedbackResult').textContent = '✓ ' + t('Thanks for your feedback!');
      document.getElementById('feedbackText').value = '';
      setTimeout(() => document.getElementById('feedbackModal').style.display = 'none', 1500);
    }
  } catch {
    document.getElementById('feedbackResult').textContent = '✗ ' + t('Failed to send');
  }
}

// ===== WEAK WORDS FLASHCARD REVIEW =====
function reviewWeakWords() {
  let weak = JSON.parse(localStorage.getItem('weak_words') || '[]');
  if (weak.length === 0) { toast(t('No weak words yet! Take a quiz first.'), 'var(--gold)', 2000); return; }
  // Show review modal
  showReviewMistakesFromArray(weak);
}

function showReviewMistakesFromArray(words) {
  const modal = document.getElementById('reviewModal');
  if (!modal || words.length === 0) return;
  const list = document.getElementById('reviewList');
  list.innerHTML = words.map(q => {
    return '<div style="padding:12px;margin-bottom:10px;border-radius:12px;background:var(--card2);border:1px solid var(--border)">'
      + '<div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">'
      + '<span style="font-size:20px;font-weight:bold;color:var(--fg)">' + q.c + '</span>'
      + '<span style="color:var(--fg2);font-size:13px">' + q.p + '</span>'
      + '<button onclick="speak(\''+q.c+'\',0.7)" style="width:28px;height:28px;border-radius:50%;border:none;background:var(--card);color:var(--blue);cursor:pointer;outline:none"><i class="fas fa-volume-high text-xs"></i></button>'
      + '</div>'
      + '<div style="font-size:12px;color:var(--muted)">' + q.o[q.a] + '</div>'
      + '<button onclick="removeWeakWord(\''+q.c+'\')" style="margin-top:6px;padding:4px 12px;border-radius:8px;border:1px solid var(--border);background:transparent;color:var(--muted);font-size:11px;cursor:pointer;outline:none">' + t('Remove') + '</button>'
      + '</div>';
  }).join('');
  modal.style.display = 'flex';
}

function updateWeakCount() {
  const el = document.getElementById('weakCount');
  if (el) {
    const weak = JSON.parse(localStorage.getItem('weak_words') || '[]');
    el.textContent = weak.length;
  }
}

function removeWeakWord(cn) {
  let weak = JSON.parse(localStorage.getItem('weak_words') || '[]');
  weak = weak.filter(w => w.c !== cn);
  localStorage.setItem('weak_words', JSON.stringify(weak));
  showReviewMistakesFromArray(weak);
}

// ===== HSK =====
function buildHSK(){
  const c = document.getElementById('hskL');
  if (!c) return;
  c.innerHTML = '';
  
  LV.forEach((l, i) => {
    const isPremium = hasPremiumAccess();
    let cls = 'background:var(--card2);color:var(--muted)';
    if (isPremium) {
      cls = (i === curLv) ? 'background:var(--accent);color:#fff;box-shadow:0 4px 14px rgba(var(--st),.3)' : 'background:var(--green);color:#fff';
    } else {
      cls = i < 1 ? 'background:var(--green);color:#fff' : i === 1 ? 'background:var(--accent);color:#fff;box-shadow:0 4px 14px rgba(var(--st),.3)' : 'background:var(--card2);color:var(--muted)';
    }
    
    // Container wrapper for card + collapsible words list
    const wrapper = document.createElement('div');
    wrapper.className = 'flex flex-col mb-3';
    
    // Level Card
    const d = document.createElement('div');
    d.className = 'cd p-4 flex items-center gap-4 cursor-pointer';
    d.innerHTML = '<div class="ldd" style="'+cls+'">'+(i+1)+'</div><div class="flex-1 min-w-0"><div class="flex items-center gap-2 mb-0.5"><h4 class="font-bold text-sm">'+t(l.n)+'</h4>'+(i===2?'<span class="text-xs px-2 py-0.5 rounded-full" style="background:rgba(var(--st),.1);color:var(--accent)">'+t('Current')+'</span>':'')+'</div><p class="text-xs mb-2" style="color:var(--muted)">'+t(l.d)+' ('+t('Click to view vocabulary')+')</p><div style="height:3px;background:var(--card2);border-radius:2px;overflow:hidden"><div class="pf" style="width:'+l.pc+'%;background:'+(l.dn?'var(--green)':'linear-gradient(90deg,var(--accent),var(--gold))')+'"></div></div></div><div class="text-right flex-shrink-0"><div class="text-sm font-bold" style="color:'+(l.dn?'var(--green)':'var(--gold)')+'">'+l.pc+'%</div><div class="text-xs" style="color:var(--muted)">'+t(l.ls)+'</div></div>';
    
    // Collapsible Words list
    const wordsDiv = document.createElement('div');
    wordsDiv.id = 'hskWords-' + i;
    wordsDiv.className = 'p-4 border-t border-[var(--border)] rounded-b-xl';
    wordsDiv.style.background = 'var(--card)';
    wordsDiv.style.display = 'none';
    
    // Gather vocabulary words for this HSK level from our TL database
    const levelName = l.n;
    const words = [];
    getLessonsForLevel(i).forEach(lesson => {
      lesson.words.forEach(w => {
        if (!words.some(item => item.cn === w.cn)) {
          words.push(w);
        }
      });
    });
    
    let wordsHTML = '<div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-2.5 mt-2">';
    words.forEach(w => {
      wordsHTML += `
        <div class="flex items-center justify-between p-2.5 rounded-xl border border-[var(--border)]" style="background:var(--card2)">
          <div class="min-w-0 pr-2">
            <div class="flex items-baseline gap-1.5 flex-wrap">
              <span class="fc font-black text-sm text-white">${w.cn}</span>
              <span class="text-xs font-semibold" style="color:var(--gold)">${w.py}</span>
            </div>
            <div class="text-[10px] mt-0.5 text-muted truncate" data-tr="${w.en.replace(/"/g, '&quot;')}">${t(w.en)}</div>
          </div>
          <button onclick="event.stopPropagation(); speak('${w.cn.replace(/'/g, "\'")}', 0.7)" class="w-7 h-7 rounded-full flex items-center justify-center text-[var(--blue)] bg-[rgba(72,152,213,.08)] hover:bg-[rgba(72,152,213,.15)] transition border-none cursor-pointer" title="Listen">
            <i class="fas fa-volume-high text-[10px]"></i>
          </button>
        </div>
      `;
    });
    wordsHTML += '</div>';
    
    wordsDiv.innerHTML = `
      <div class="text-xs font-semibold uppercase tracking-wider mb-2 text-muted flex justify-between items-center">
        <span>${t(levelName)} ${t('Vocab List')} (${words.length} ${t('items')})</span>
        <span class="text-[9px] lowercase font-normal italic text-muted">${t('click card again to close')}</span>
      </div>
      ${wordsHTML}
    `;
    
    d.onclick = () => {
      const isPremium = hasPremiumAccess();
      if (i >= 1 && !isPremium) {
        showPremiumPaywall(levelName);
        return;
      }
      const isClosed = (wordsDiv.style.display === 'none');
      
      // Close all other lists
      document.querySelectorAll('[id^="hskWords-"]').forEach(el => {
        el.style.display = 'none';
        // restore border-radius to card sibling if closed
        const cardSib = el.previousSibling;
        if (cardSib) cardSib.style.borderRadius = '';
      });
      
      if (isClosed) {
        wordsDiv.style.display = 'block';
        d.style.borderRadius = '12px 12px 0 0'; // Flatten bottom corners when open
        
        // Update current level selection
        curLv = i;
        document.querySelectorAll('#lvTabs .tb').forEach((b, bi) => {
          b.classList.toggle('on', bi === i);
        });
        buildTopics();
      } else {
        wordsDiv.style.display = 'none';
        d.style.borderRadius = '';
      }
    };
    
    wrapper.appendChild(d);
    wrapper.appendChild(wordsDiv);
    c.appendChild(wrapper);
  });
}

// ===== CANVAS / HANZI WRITER INTEGRATION =====
function initCv(){
  var charEl = document.getElementById('rfCh');
  var char = charEl ? charEl.textContent : '你';
  // support HSK9 sentence mode
  if (typeof HSK9_WRITING_MODE !== 'undefined' && HSK9_WRITING_MODE && typeof window._hsk9Chars !== 'undefined') {
    var hc = window._hsk9Chars;
    var idx = typeof window._hsk9Idx !== 'undefined' ? window._hsk9Idx : 0;
    if (idx < hc.length) char = hc[idx];
    if (charEl) charEl.textContent = char;
    updateSentenceHighlight();
    var si = document.getElementById('sentenceInfo');
    if (si) si.textContent = 'Character ' + (idx+1) + ' of ' + hc.length;
  }
  initHanziWriter(char);
}
function initHanziWriter(char) {
  if (typeof HanziWriter === 'undefined') {
    console.warn("HanziWriter library not loaded yet.");
    return;
  }
  const target = document.getElementById('character-target');
  if (!target) return;
  target.innerHTML = '';
  
  const toggle = document.getElementById('writeOutlineToggle');
  const showOutline = toggle ? toggle.checked : true;
  
  writer = HanziWriter.create('character-target', char, {
    width: 200,
    height: 200,
    showCharacter: false,
    showOutline: showOutline,
    padding: 5,
    strokeColor: '#000000',
    outlineColor: '#999999',
    drawingColor: '#555555',
    onCharacterDataLoadError: function(c) { console.warn('Could not load stroke data for character:', c); }
  });
  writer.quiz();
}
function animateCh() {
  if (writer) writer.animateCharacter();
}
function quizCh() {
  if (writer) writer.quiz();
}

function speakCurrentWritingChar() {
  var charEl = document.getElementById('rfCh');
  var char = charEl ? charEl.textContent : '';
  if (char && char !== '--') {
    speak(char, 0.7);
  }
}

function clrCv() {
  var charEl = document.getElementById('rfCh');
  var char = charEl ? charEl.textContent : '你';
  var lookup = typeof WRITING_CHAR_DATA !== 'undefined' ? WRITING_CHAR_DATA : {};
  var data = lookup[char] || {};
  var rfPy = document.getElementById('rfPy');
  var rfMn = document.getElementById('rfMn');
  if (typeof HSK9_WRITING_MODE !== 'undefined' && HSK9_WRITING_MODE && window._hsk9Sentence && window._hsk9Chars) {
    var idx = typeof window._hsk9Idx !== 'undefined' ? window._hsk9Idx : 0;
    var pyList = (window._hsk9Sentence.sp || '').split(/[，；。！？、\s,;]+/).filter(Boolean);
    if (rfPy) rfPy.textContent = pyList[idx] || '--';
    if (rfMn) rfMn.textContent = data.m || window._hsk9Sentence.se || '--';
  } else {
    if (rfPy) rfPy.textContent = data.py || '--';
    if (rfMn) rfMn.textContent = data.m || '--';
  }
  initHanziWriter(char);
}
function nxtCh(){
  trackDaily('chars');
  // HSK9 sentence mode
  if (typeof HSK9_WRITING_MODE !== 'undefined' && HSK9_WRITING_MODE && typeof window._hsk9Chars !== 'undefined') {
    var hc = window._hsk9Chars;
    window._hsk9Idx = (typeof window._hsk9Idx !== 'undefined' ? window._hsk9Idx : 0) + 1;
    if (window._hsk9Idx >= hc.length) window._hsk9Idx = 0;
    var ch = hc[window._hsk9Idx];
    var rfCh = document.getElementById('rfCh');
    if (rfCh && ch) rfCh.textContent = ch;
    updateSentenceHighlight();
    var si = document.getElementById('sentenceInfo');
    if (si) si.textContent = 'Character ' + (window._hsk9Idx+1) + ' of ' + hc.length;
    clrCv();
    if (ch) speak(ch, 0.7);
    return;
  }
  curWI = (curWI + 1) % WCH.length;
  var nextCh = WCH[curWI];
  var rfCh = document.getElementById('rfCh');
  if (rfCh && nextCh) rfCh.textContent = nextCh;
  clrCv();
  if (nextCh) speak(nextCh, 0.7);
}
function toggleWriteOutline() {
  const toggle = document.getElementById('writeOutlineToggle');
  if (!writer) return;
  if (toggle.checked) {
    writer.showOutline();
  } else {
    writer.hideOutline();
  }
}

// ===== FLASHCARDS SRS SCHEDULER =====
function rateFlashcard(score) {
  if (flashcardList.length === 0) return;
  const word = flashcardList[curFcIdx];
  
  const intervals = [0, 60 * 1000, 12 * 60 * 60 * 1000, 24 * 60 * 60 * 1000, 4 * 24 * 60 * 60 * 1000];
  const offset = intervals[score];
  const nextReview = Date.now() + offset;
  
  const srsState = JSON.parse(localStorage.getItem('hsk_srs_state') || '{}');
  srsState[word.cn] = {
    box: score,
    due: nextReview
  };
  localStorage.setItem('hsk_srs_state', JSON.stringify(srsState));
  
  if (score >= 3) {
    const learnedWords = JSON.parse(localStorage.getItem('learned_words') || '[]');
    if (!learnedWords.includes(word.cn)) {
      learnedWords.push(word.cn);
      localStorage.setItem('learned_words', JSON.stringify(learnedWords));
    }
  }
  
  const rates = ["", t("Again (1m)"), t("Hard (12h)"), t("Good (1d)"), t("Easy (4d)")];
  toast(t("Card rescheduled: ") + rates[score], "var(--green)");
  addXP(1, 'Flashcard review'); trackDaily('words');
  
  nextFlashcard();
}
function toggleSrsDueFilter() {
  const toggle = document.getElementById('srsDueFilter');
  srsFilterActive = toggle ? toggle.checked : false;
  buildFlashcards();
}

// ===== PINYIN TONE PITCH VISUALIZER =====
function selectTone(e, idx, py) {
  if (e) e.stopPropagation();
  
  playPy(document.getElementById('toneCard-' + idx), py);
  
  activeToneIndex = idx;
  const recordBtn = document.getElementById('toneRecordBtn');
  if (recordBtn) {
    recordBtn.disabled = false;
    const ic = document.getElementById('toneMicIc');
    if (ic) ic.style.color = 'var(--accent)';
  }
  
  const toneNames = [t("Flat (1st Tone)"), t("Rising (2nd Tone)"), t("Dipping (3rd Tone)"), t("Falling (4th Tone)")];
  document.getElementById('toneStatus').textContent = t('Practice:')+' ' + py + ' (' + toneNames[idx] + ')';
  document.getElementById('toneOverlayLabel').style.display = 'none';
  
  drawToneCanvas();
}
function toggleToneCapture() {
  if (isTrackingPitch) {
    stopToneCapture();
  } else {
    startToneCapture();
  }
}
function startToneCapture() {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    toast(t("Microphone access not supported in this browser."), "var(--accent)");
    return;
  }
  
  navigator.mediaDevices.getUserMedia(getMicAudioConstraints())
    .then(stream => {
      toneMicStream = stream;
      audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const source = audioCtx.createMediaStreamSource(stream);
      toneAnalyser = audioCtx.createAnalyser();
      toneAnalyser.fftSize = 2048;
      source.connect(toneAnalyser);
      
      isTrackingPitch = true;
      pitchHistory = [];
      const btn = document.getElementById('toneRecordBtn');
      const ic = document.getElementById('toneMicIc');
      if (btn && ic) {
        btn.style.background = 'rgba(56,169,106,.1)';
        ic.className = 'fas fa-stop text-base';
        ic.style.color = 'var(--green)';
      }
      document.getElementById('toneStatus').textContent = t('Hum/Speak now...');
      
      trackPitch();
    })
    .catch(err => {
      console.error("Failed to access microphone for tone practice:", err);
      toast(t("Microphone access denied."), "var(--accent)");
    });
}
function stopToneCapture() {
  isTrackingPitch = false;
  if (toneRafId) cancelAnimationFrame(toneRafId);
  if (toneMicStream) {
    toneMicStream.getTracks().forEach(t => t.stop());
    toneMicStream = null;
  }
  if (audioCtx) {
    audioCtx.close();
    audioCtx = null;
  }
  
  const btn = document.getElementById('toneRecordBtn');
  const ic = document.getElementById('toneMicIc');
  if (btn && ic) {
    btn.style.background = 'rgba(72,152,213,.08)';
    ic.className = 'fas fa-microphone text-base';
    ic.style.color = 'var(--accent)';
  }
  document.getElementById('toneStatus').textContent = t('Analysis complete. Choose another tone to test!');
}
function trackPitch() {
  if (!isTrackingPitch) return;
  const buffer = new Float32Array(toneAnalyser.fftSize);
  toneAnalyser.getFloatTimeDomainData(buffer);
  
  const pitch = autoCorrelate(buffer, audioCtx.sampleRate);
  if (pitch !== -1 && pitch > 60 && pitch < 400) {
    pitchHistory.push(pitch);
    if (pitchHistory.length > 80) pitchHistory.shift();
  }
  
  drawToneCanvas();
  toneRafId = requestAnimationFrame(trackPitch);
}
function autoCorrelate(buffer, sampleRate) {
  let SIZE = buffer.length;
  let rms = 0;
  for (let i = 0; i < SIZE; i++) {
    const val = buffer[i];
    rms += val * val;
  }
  rms = Math.sqrt(rms / SIZE);
  if (rms < 0.008) return -1;
  
  let r1 = 0, r2 = SIZE - 1;
  let thres = 0.15;
  for (let i = 0; i < SIZE / 2; i++) {
    if (Math.abs(buffer[i]) < thres) { r1 = i; break; }
  }
  for (let i = SIZE - 1; i >= SIZE / 2; i--) {
    if (Math.abs(buffer[i]) < thres) { r2 = i; break; }
  }
  buffer = buffer.slice(r1, r2);
  SIZE = buffer.length;
  
  let c = new Float32Array(SIZE);
  for (let i = 0; i < SIZE; i++) {
    for (let j = 0; j < SIZE - i; j++) {
      c[i] = c[i] + buffer[j] * buffer[j + i];
    }
  }
  
  let d = 0;
  while (c[d] > c[d + 1]) d++;
  let maxval = -1, maxpos = -1;
  for (let i = d; i < SIZE; i++) {
    if (c[i] > maxval) {
      maxval = c[i];
      maxpos = i;
    }
  }
  let T0 = maxpos;
  
  let x1 = c[T0 - 1], x2 = c[T0], x3 = c[T0 + 1];
  let a = (x1 + x3 - 2 * x2) / 2;
  let b = (x3 - x1) / 2;
  if (a) T0 = T0 - b / (2 * a);
  
  return sampleRate / T0;
}
function drawToneCanvas() {
  const canvas = document.getElementById('toneCanvas');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  
  const r = canvas.getBoundingClientRect();
  canvas.width = r.width;
  canvas.height = r.height;
  
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  
  ctx.strokeStyle = 'rgba(212,166,79,0.06)';
  ctx.lineWidth = 1;
  for (let y = 15; y < canvas.height; y += 15) {
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(canvas.width, y);
    ctx.stroke();
  }
  
  if (activeToneIndex !== -1) {
    ctx.strokeStyle = 'rgba(212,166,79,0.25)';
    ctx.lineWidth = 4;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    
    const w = canvas.width;
    const h = canvas.height;
    
    if (activeToneIndex === 0) {
      ctx.moveTo(15, h * 0.25);
      ctx.lineTo(w - 15, h * 0.25);
    } else if (activeToneIndex === 1) {
      ctx.moveTo(15, h * 0.75);
      ctx.lineTo(w - 15, h * 0.25);
    } else if (activeToneIndex === 2) {
      ctx.moveTo(15, h * 0.4);
      ctx.quadraticCurveTo(w / 2, h * 0.9, w - 15, h * 0.3);
    } else if (activeToneIndex === 3) {
      ctx.moveTo(15, h * 0.2);
      ctx.lineTo(w - 15, h * 0.8);
    }
    ctx.stroke();
    ctx.setLineDash([]);
  }
  
  if (pitchHistory.length > 1) {
    ctx.strokeStyle = '#4898d5';
    ctx.lineWidth = 3.5;
    ctx.lineCap = 'round';
    ctx.beginPath();
    
    const minPitch = 80;
    const maxPitch = 250;
    
    pitchHistory.forEach((p, idx) => {
      const x = (idx / 80) * (canvas.width - 30) + 15;
      let pct = (p - minPitch) / (maxPitch - minPitch);
      pct = Math.max(0, Math.min(1, pct));
      const y = canvas.height - (pct * (canvas.height - 20) + 10);
      
      if (idx === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();
  }
}

let inputSpeechRecognition = null;
let isInputListening = false;
let _inputRecAudioMode = false;

function inputAudioFallback(ic, input) {
  var tc = document.querySelector('.tone-curve-wrap');
  if (_inputRecAudioMode) {
    if (tc) tc.classList.remove('active');
    stopMediaRecorder();
    _inputRecAudioMode = false;
    isInputListening = false;
    ic.className = 'fas fa-microphone';
    input.placeholder = t('Processing audio...');
    const chunks = audioChunks;
    audioChunks = [];
    if (chunks.length === 0) {
      input.placeholder = t('Type or speak Chinese here — e.g. 你好');
      return;
    }
    const mime = window._audioMime || 'audio/mp4';
    const blob = new Blob(chunks, { type: mime });
    const reader = new FileReader();
    reader.onloadend = () => {
      const b64 = reader.result.split(',')[1];
      fetch('/api/chat', {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ role: "user", parts: [{ inlineData: { mimeType: mime, data: b64 } }] }],
          systemInstruction: "Transcribe the speech in this audio accurately. If the speaker is speaking Mandarin Chinese, return the Chinese characters. If they are speaking English or another language, return their words in that language. Return ONLY the transcription, nothing else.",
          sourceLang: getSpeechSrcLang()
        })
      }).then(r => r.json()).then(d => {
        const text = d.candidates?.[0]?.content?.parts?.[0]?.text || '';
        input.value = text;
        input.placeholder = t('Type or speak Chinese here — e.g. 你好');
      }).catch(() => {
        input.placeholder = t('Transcription failed. Try typing.');
      });
    };
    reader.readAsDataURL(blob);
    return;
  }
  _inputRecAudioMode = true;
  isInputListening = true;
  ic.className = 'fas fa-stop text-accent';
  input.placeholder = t('Recording... tap mic to stop');
  if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
    navigator.mediaDevices.getUserMedia(getMicAudioConstraints()).then(stream => {
      if (tc) tc.classList.add('active');
      activeMicStream = stream;
      audioChunks = [];
      let mime = 'audio/mp4';
      if (typeof MediaRecorder.isTypeSupported === 'function') {
        if (!MediaRecorder.isTypeSupported(mime)) mime = 'audio/ogg;codecs=opus';
        if (!MediaRecorder.isTypeSupported(mime)) mime = 'audio/webm';
      }
      window._audioMime = mime;
      mediaRecorder = new MediaRecorder(stream, { mimeType: mime, audioBitsPerSecond: 192000 });
      mediaRecorder.ondataavailable = e => { if (e.data.size > 0) audioChunks.push(e.data); };
      mediaRecorder.start(250);
    }).catch(() => {
      _inputRecAudioMode = false;
      isInputListening = false;
      ic.className = 'fas fa-microphone';
      input.placeholder = t('Mic denied. Type instead.');
    });
  }
}

function toggleInputSpeech() {
  const btn = document.getElementById('tutInputMic');
  const ic = document.getElementById('tutInputMicIc');
  const input = document.getElementById('tutTypeInput');
  
  // Use audio recording fallback if SpeechRecognition previously failed
  if (window._useAudioFallback || localStorage.getItem('_useAudioFallback')) {
    window._useAudioFallback = true;
    return inputAudioFallback(ic, input);
  }
  
  // On non-secure HTTP, skip SpeechRecognition — go straight to recording fallback
  if (window.location.protocol !== 'https:' && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') {
    window._useAudioFallback = true;
    localStorage.setItem('_useAudioFallback', 'true');
    return inputAudioFallback(ic, input);
  }
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) {
    window._useAudioFallback = true;
    localStorage.setItem('_useAudioFallback', 'true');
    return inputAudioFallback(ic, input);
  }
  
  if (isInputListening) {
    if (inputSpeechRecognition) {
      inputSpeechRecognition.stop();
    }
    return;
  }
  
  if (!isMobileDevice) { speechSynthesis.cancel(); }
  
  try {
    inputSpeechRecognition = new SpeechRecognition();
    inputSpeechRecognition.lang = getSpeechLang();
    inputSpeechRecognition.interimResults = true;
    inputSpeechRecognition.maxAlternatives = 1;
    
    var tc = document.querySelector('.tone-curve-wrap');
    inputSpeechRecognition.onstart = () => {
      isInputListening = true;
      ic.className = 'fas fa-stop text-accent';
      input.placeholder = t('Listening... Speak in Mandarin');
      if (tc) tc.classList.add('active');
    };
    
    inputSpeechRecognition.onresult = (e) => {
      const transcript = e.results[0][0].transcript;
      input.value = transcript;
    };
    
    inputSpeechRecognition.onerror = (e) => {
      console.error("Input Speech Error:", e.error);
      if (tc) tc.classList.remove('active');
      if (e.error === 'no-speech') {
        window._useAudioFallback = true;
        localStorage.setItem('_useAudioFallback', 'true');
        input.placeholder = t('Auto-switching to recording...');
        setTimeout(() => inputAudioFallback(ic, input), 300);
      } else {
        toast(t("Speech Error: ") + e.error, "var(--accent)");
      }
    };
    
    inputSpeechRecognition.onend = () => {
      isInputListening = false;
      ic.className = 'fas fa-microphone';
      input.placeholder = t('Type or speak Chinese here — e.g. 你好');
      if (tc) tc.classList.remove('active');
    };
    
    inputSpeechRecognition.start();
  } catch(err) {
    console.error("Failed to start Input SpeechRecognition:", err);
    window._useAudioFallback = true;
    localStorage.setItem('_useAudioFallback', 'true');
    inputAudioFallback(ic, input);
  }
}

// ===== GEMINI LIVE AI TUTOR INTEGRATION =====
function toggleSettingsModal() {
  const modal = document.getElementById('geminiModal');
  if (modal) {
    const showing = modal.style.display !== 'flex';
    modal.style.display = showing ? 'flex' : 'none';
    if (showing) {
      updatePushToggleUI();
      loadProfile();
      loadMicDevices();
    }
  }
}

function saveGeminiSettings() {
  const mode = document.getElementById('tutorModeSelect').value;
  if (mode === 'live' && !hasTutorAccess()) {
    showPremiumPaywall(t('Live AI Tutor'));
    toast(t('Daily free speaking limit reached. Upgrade to Premium for unlimited tutor time.'), 'var(--accent)', 6000);
    document.getElementById('tutorModeSelect').value = localStorage.getItem('tutor_mode') || 'static';
    return;
  }
  const rate = document.getElementById('speechRateSelect').value;
  
  localStorage.setItem('tutor_mode', mode);
  localStorage.setItem('speech_rate', rate);
  
  // Hands-free by default in Live AI mode
  if (mode === 'live') enableVoiceModeAuto();
  else if (voiceModeActive) toggleVoiceMode();
  
  updateSpeechRateDisplay(rate);
  toast(t("Settings Saved! Mode: ") + (mode === 'live' ? t('Live AI') : t('Simulated')), "var(--green)");
  toggleSettingsModal();
  if (tutLesson) {
    startTutor(TL.indexOf(tutLesson));
  }
}

function loadGeminiSettings() {
  let mode = localStorage.getItem('tutor_mode') || "static";
  if (mode === 'live' && !hasPremiumAccess()) {
    mode = 'static';
    localStorage.setItem('tutor_mode', 'static');
  }
  const rate = localStorage.getItem('speech_rate') || "1.0";
  
  const modeSelect = document.getElementById('tutorModeSelect');
  const rateSelect = document.getElementById('speechRateSelect');
  
  if (modeSelect) modeSelect.value = mode;
  if (rateSelect) rateSelect.value = rate;
  const ttsSelect = document.getElementById('ttsModeSelect');
  if (ttsSelect) ttsSelect.value = localStorage.getItem('tts_mode') || 'api';

  const speechLangSel = document.getElementById('speechLangSelect');
  if (speechLangSel) speechLangSel.value = getSpeechLang();
  
  const bmToggle = document.getElementById('beginnerModeToggle');
  if (bmToggle) bmToggle.checked = isBeginnerMode;
  
  const btn = document.getElementById('tutRoleplayBtn');
  if (btn) {
    if (mode === 'live') {
      btn.style.background = 'var(--neon-cyan)';
      btn.style.color = '#000';
      btn.innerHTML = '<i class="fas fa-robot mr-1"></i>Live AI';
    } else {
      btn.style.background = 'var(--card2)';
      btn.style.color = 'var(--muted)';
      btn.innerHTML = '<i class="fas fa-user-friends mr-1"></i>Study';
    }
  }
  
  updateSpeechRateDisplay(rate);
}

// Translate Chinese to the user's selected language for live AI user bubbles
let _liveTrCache = {};
async function translateToEnglish(text) {
  if (_liveTrCache[text]) return _liveTrCache[text];
  const targetLang = getTutorLangName();
  let instruction = 'You are a professional translator, 100% fluent in ' + targetLang + ' at native-speaker level. Translate the Chinese text into natural, idiomatic ' + targetLang + ' — never literal. Reply with ONLY the ' + targetLang + ' translation and nothing else.';
  if (targetLang === 'Auto-detect') {
    instruction = 'You are a professional translator. Detect the student\'s native language (e.g. English, Spanish, Vietnamese, Thai, French, etc.) from the conversation context or their last message, and translate the Chinese text into that language. Reply with ONLY the translation, no explanations, no extra text.';
  }
  const res = await fetch('/api/chat', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text }] }], systemInstruction: instruction })
  });
  const data = await res.json();
  let reply = data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  reply = reply.replace(/^["']|["']$/g, '').trim();
  if (reply) _liveTrCache[text] = reply;
  return reply;
}

// Translate a string into the user's selected language when the offline
// dictionary has no entry for it (dictionary miss → tutor content falls back
// to English). AI-translated results are cached in localStorage so each string
// is translated only once.
let _aiTrCache = null;
function loadAiTrCache() {
  if (_aiTrCache) return _aiTrCache;
  try { _aiTrCache = JSON.parse(localStorage.getItem('tutor_ai_tr_cache') || '{}') || {}; }
  catch(e) { _aiTrCache = {}; }
  return _aiTrCache;
}
function saveAiTrCache() {
  try { localStorage.setItem('tutor_ai_tr_cache', JSON.stringify(_aiTrCache)); } catch(e) {}
}
async function aiTranslate(text) {
  const targetLang = getTutorLangName();
  const res = await fetch('/api/chat', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ contents: [{ role: 'user', parts: [{ text }] }], systemInstruction: 'You are a professional translator, 100% fluent in ' + targetLang + ' at native-speaker level. Translate the following text into natural, idiomatic ' + targetLang + ' — never literal, never add explanations. Reply with ONLY the ' + targetLang + ' translation and nothing else.' })
  });
  const data = await res.json();
  let reply = data?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  reply = reply.replace(/^["']|["']$/g, '').trim();
  return reply;
}
// Fill `els` (DOM elements) with a translation of `text` into the selected
// language. Only used when t(text) found nothing in the offline dictionary.
function ensureTutorTranslation(text, els) {
  if (!text || currentAppLang === 'en' || getTutorLangName() === 'English') return;
  const cache = loadAiTrCache();
  if (cache[text]) { els.forEach(el => { if (el) el.textContent = cache[text]; }); return; }
  aiTranslate(text).then(en => {
    if (!en) return;
    cache[text] = en;
    saveAiTrCache();
    els.forEach(el => { if (el) el.textContent = en; });
  }).catch(() => {});
}

// Show the user's Chinese reply in the chat, then append its English translation
function addLiveUserMsg(text) {
  const trId = 'utr-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
  const hasCn = /[\u4e00-\u9fa5]/.test(text);
  let html = '<div class="fc font-bold" style="font-size:20px;margin-bottom:4px">' + text + '</div>';
  if (hasCn) {
    html += '<div id="' + trId + '" style="font-size:13px;color:var(--muted)"><i class="fas fa-language"></i> ' + t('Translating...') + '</div>';
  }
  addTutMsg('user', html);
  if (hasCn) {
    translateToEnglish(text).then(function(en) {
      const el = document.getElementById(trId);
      if (el) el.textContent = en || '';
    }).catch(function() {
      const el = document.getElementById(trId);
      if (el) el.textContent = '';
    });
  }
}

// ===== MIC / SPEECH LANGUAGE =====
const SPEECH_LANGS = [
  { code: 'auto', src: '', name: 'Auto-detect' },
  { code: 'zh-CN', src: 'zh', name: 'Chinese (Mandarin)' },
  { code: 'en-US', src: 'en', name: 'English' },
  { code: 'es-ES', src: 'es', name: 'Spanish' },
  { code: 'fr-FR', src: 'fr', name: 'French' },
  { code: 'ja-JP', src: 'ja', name: 'Japanese' },
  { code: 'ko-KR', src: 'ko', name: 'Korean' },
  { code: 'de-DE', src: 'de', name: 'German' },
  { code: 'pt-BR', src: 'pt', name: 'Portuguese' },
  { code: 'it-IT', src: 'it', name: 'Italian' },
  { code: 'ru-RU', src: 'ru', name: 'Russian' },
  { code: 'vi-VN', src: 'vi', name: 'Vietnamese' },
  { code: 'th-TH', src: 'th', name: 'Thai' }
];
function getSpeechLang() {
  return localStorage.getItem('speech_lang') || 'zh-CN';
}
function getSpeechSrcLang() {
  const f = SPEECH_LANGS.find(x => x.code === getSpeechLang());
  return f ? f.src : 'zh';
}
function getTutorLangName() {
  const c = getSpeechLang();
  const f = SPEECH_LANGS.find(x => x.code === c);
  if (f && c !== 'zh-CN') return f.name;
  return currentAppLang === 'es' ? 'Spanish' : currentAppLang === 'fr' ? 'French' : currentAppLang === 'ja' ? 'Japanese' : currentAppLang === 'ko' ? 'Korean' : currentAppLang === 'de' ? 'German' : currentAppLang === 'pt' ? 'Portuguese' : currentAppLang === 'it' ? 'Italian' : currentAppLang === 'ru' ? 'Russian' : currentAppLang === 'vi' ? 'Vietnamese' : currentAppLang === 'th' ? 'Thai' : currentAppLang === 'id' ? 'Indonesian' : currentAppLang === 'ar' ? 'Arabic' : currentAppLang === 'tr' ? 'Turkish' : 'English';
}
function saveSpeechLang(v) {
  localStorage.setItem('speech_lang', v);
  toast(t('Mic language set to:') + ' ' + (SPEECH_LANGS.find(x => x.code === v) || { name: v }).name, 'var(--green)');
}

function isAutoIntroText(text) {
  if (!text) return false;
  return text.indexOf('__PLACEMENT_START__') !== -1 ||
         text.indexOf('（课堂开始）') === 0 ||
         text.indexOf('（时间到！') === 0 ||
         text.indexOf('(System note:') === 0 ||
         text.indexOf('(Internal note:') === 0 ||
         text === "你好！请用中文跟我聊天。" ||
         text === "你好！请用中文跟我聊天。我是你的学生。" ||
         text.indexOf("Hello! I am a complete beginner learning Chinese") === 0;
}

function sendToGemini(userText) {
  _introTurnForSpeech = isAutoIntroText(userText);
  const statusText = document.getElementById('tutStatus');
  
  if (!navigator.onLine) {
    addTutMsg('warn', '⚠️ <b>'+t('Internet connection lost')+'</b> — '+t('Live AI Mode requires an internet connection. Please reconnect and try again.'));
    if (statusText) statusText.textContent = t('Disconnected');
    document.getElementById('tutHint').innerHTML = '<span style="color:var(--accent2);font-weight:700"><i class="fas fa-wifi-slash"></i> '+t('No internet — Live AI unavailable')+'</span>';
    return;
  }

  // Daily limit for free tier
  if (!hasPremiumAccess()) {
    const today = new Date().toISOString().split('T')[0];
    const storedDate = localStorage.getItem('tutor_usage_date');
    let count = parseInt(localStorage.getItem('tutor_messages_count') || '0');
    
    if (storedDate !== today) {
      localStorage.setItem('tutor_usage_date', today);
      localStorage.setItem('tutor_messages_count', '0');
      count = 0;
    }
    
    // Ignore placement initialization or internal notes
    const isInternal = userText.startsWith('（课堂开始）') || 
                       userText.startsWith('__PLACEMENT_START__') || 
                       userText.startsWith('(System note:') || 
                       userText.includes('__PLACEMENT_START__');

    if (!isInternal) {
      if (count >= 5) {
        showPremiumPaywall(t('Live AI Tutor'));
        toast(t('Daily free speaking limit reached. Upgrade to Premium for unlimited tutor time.'), 'var(--accent)', 6000);
        if (statusText) statusText.textContent = t('Limit Reached');
        return;
      }
      count++;
      localStorage.setItem('tutor_messages_count', count.toString());
      updateTutorUsageBadge();
    }
  }
  
  if(statusText) statusText.textContent = t("Thinking...");
  
  if (!userText.startsWith("你好！")) {
    geminiHistory.push({ role: "user", parts: [{ text: userText }] });
  }
  
  const loaderId = "loader-" + Date.now();
  window._tutLoaderEl = addTutMsg('bot', '<div id="' + loaderId + '" class="animate-pulse" style="min-height:24px">'+t('Thinking...')+'</div>');
  if (window._tutLoaderEl) window._tutLoaderEl.style.animation = 'none';
  
  const chineseLevel = getChineseLevel();
  const tutorLang = getTutorLangName();
  const langName = tutorLang === 'Auto-detect' ? "the student's native language (e.g. English, Spanish, Vietnamese, Thai, etc. - auto-detected from their messages)" : tutorLang;
  const baseRules =
    "The student's current Chinese level setting is: " + chineseLevel + ".\n" +
    "You are also a professional translator, 100% fluent in " + langName + " at native-speaker level. You fully understand English and every other language.\n" +
    "ABSOLUTE RULES (these override every other instruction below):\n" +
    "0. This is a real conversation with a real student. NEVER talk like a scripted lesson or a voice-assistant. You are a warm, natural human tutor having a normal chat.\n" +
    "0b. You can ALWAYS see the whole chat history, including how many messages have passed. The 'first-message template' below applies ONLY if this is genuinely the very first AI reply in this chat and the student has not yet spoken at all. If the student has ALREADY said anything (even 'hi'), the template is FORBIDDEN; respond conversationally to what they just said.\n" +
    "0c. Never produce empty placeholders like ** **, [...], or 'A.' alone. If you start a sentence, finish it with real words.\n" +
    "0d. NEVER dodge, refuse, or filter a question. Answer any question the student asks (personal, cultural, silly, 'do you have a boyfriend', etc.) honestly and naturally as a friendly fictional teacher character.\n" +
    "LANGUAGE RULES:\n" +
    "1. Always understand exactly what the student means in ANY language (English, Spanish, French, Japanese, Korean, German, Portuguese, Italian, Russian, Vietnamese, etc.). Never ignore or misunderstand them.\n" +
    "2. Whenever you translate into " + langName + ", produce natural, idiomatic " + langName + " exactly as a native speaker would say it — NEVER literal or word-for-word translation. Preserve tone, politeness, and cultural nuance.\n" +
    "3. If the student writes in " + langName + " or any other language, answer or acknowledge them clearly in their own language FIRST, then teach the Chinese phrase(s) they would use to say it.\n" +
    "4. If the student writes in Chinese, respond in Chinese (following the level rules) and always give a professional, fluent " + langName + " translation.\n" +
    "5. Correct the student's Chinese gently: give the correct sentence, then a one-line explanation in " + langName + ".\n" +
    "6. Never refuse or dodge a question. If you are unsure, say so honestly in " + langName + ".\n" +
    "7. Keep responses warm, patient, and encouraging. Compliment genuine effort.\n" +
    "8. NEVER repeat yourself. Never reuse a Chinese phrase, a translation, an explanation, or a question you already said earlier in this conversation — the whole chat history is visible to you. Every reply must respond to what the student ACTUALLY just said and advance the conversation to something NEW.\n" +
    "9. Vary your wording and openings. After the first exchange, drop formulaic drilling rituals and talk like a natural, friendly tutor. Do not open every reply with the same greeting or 'Now you try' line.\n" +
    "10. If the student asks to change the topic or says 'teach me something else' / '別的東西', switch topics immediately and teach something new instead of repeating.\n" +
    "11. NEVER write these drill strings: '你会说 X 吗？', '你可以说 X', 'Can you say X?', 'You can say:', 'Now you try', '你试试说'. Teach new Chinese by using it naturally inside a real sentence, not by ordering the student to repeat it.\n" +
    "12. ALWAYS end your Chinese teaching with a real, natural question that continues the conversation — never a 'repeat after me' command.\n" +
    "13. CONFUSION ESCAPE HATCH: at ANY moment, if the student says they don't understand, asks something in their own language, or clearly struggles, switch FULLY to " + langName + " immediately — explain everything in " + langName + " until they are comfortable again, then gently return to Chinese. Never leave the student stuck.\n" +
    "14. SILENT LEVEL ASSESSMENT: every turn, quietly judge the student's OWN Chinese production (never count messages they wrote in their native language): do they understand your Chinese without asking for repeats or translations, how wide is their vocabulary and grammar compared to their level band, how frequent are significant errors. ONLY when ALL of these have been clearly true across several recent exchanges — (a) they understand your Chinese unprompted, (b) they produce their own multi-word Chinese sentences with few significant errors, (c) they comfortably use words/patterns beyond their band, (d) you have not offered a level change yet in this conversation — end that reply with EXACTLY ONE marker [LEVELUP: beginner] or [LEVELUP: intermediate] or [LEVELUP: advanced] (one step above the student's current level), and warmly tell them in " + langName + " that they are ready for more challenging Chinese. Never write the word 'LEVELUP' anywhere else; never downgrade silently — if they seem over-leveled, simplify your Chinese instead; never use the marker more than once per conversation.\n";

  let systemInstruction;
  if (_interviewActive) {
    systemInstruction = buildInterviewInstruction(getInterviewLangName());
  } else if (timedClassActive && timedSystemInstruction) {
    systemInstruction = timedSystemInstruction;
  } else if (chineseLevel === 'never') {
    systemInstruction = "You are Li Laoshi, a patient Chinese tutor for a student who has NEVER studied Chinese and knows ZERO words.\n" + baseRules +
      "TEACHING STYLE (absolute beginner):\n" +
      "1. THE FIRST MESSAGE ONLY: introduce yourself very simply — one short greeting like 你好，我叫李老师。 — then one or two friendly sentences to make the student comfortable, and ONE simple yes/no question to start the conversation.\n" +
      "2. FROM THE SECOND MESSAGE ON, respond conversationally to exactly what the student said, then introduce ONE new tiny phrase (max 3-5 characters, simplest HSK 1 words like 谢谢, 再见, 我很好, 我叫...) by using it naturally inside a real sentence.\n" +
      "3. NEVER repeat a phrase, meaning, or question already used earlier in the chat — pick a NEW phrase every reply.\n" +
      "4. Always end with one very simple yes/no or follow-up question so the student knows it is their turn.\n" +
      "5. If the student writes in " + langName + ", first acknowledge in one short " + langName + " line, then teach the Chinese for their exact sentence.\n" +
      "6. Praise every attempt warmly, even if imperfect. If wrong, correct gently in one short " + langName + " line and invite them to try again.\n" +
      "7. Output format REQUIRED for every reply — Chinese first, then the translation on its own line starting with 'English:' (or your real language name):\n\n[one or two short Chinese sentences]\n\n" + langName + ": [natural translation of those Chinese sentences]\n";
  } else if (chineseLevel === 'beginner' || isBeginnerMode) {
    systemInstruction = "You are Li Laoshi, a Chinese tutor for a BEGINNER who knows a few basic words (a few weeks to months of study).\n" + baseRules +
      "TEACHING STYLE (beginner):\n" +
      "1. Use ONLY HSK 1-2 vocabulary. Keep every sentence SHORT and simple. Never use advanced grammar, idioms, or long sentences.\n" +
      "2. THE FIRST MESSAGE ONLY: greet the student simply and ask one easy question, e.g. 你好！你叫什么名字？\n" +
      "3. FROM THE SECOND MESSAGE ON, respond conversationally to what the student actually said, praise them, and teach ONE new phrase per reply by using it naturally inside a real sentence (never as a 'You can say: ...' drill).\n" +
      "4. NEVER repeat a phrase, meaning, or question already used earlier in the chat — always advance to a NEW phrase.\n" +
      "5. Build step by step: greetings and introductions (你好, 我叫..., 我很好, 谢谢, 再见), then simple daily phrases. Only advance after the student succeeds.\n" +
      "6. Always end with ONE simple follow-up question so the student always knows it is their turn.\n" +
      "7. If the student writes or says something in " + langName + ", answer in " + langName + " first in one line, then teach the Chinese for their exact sentence.\n" +
      "8. Praise effort warmly; correct gently in one short " + langName + " line and invite them to try again.\n" +
      "9. Vary your openings and wording every reply — never start every message with the same greeting or the same drill line.\n" +
      "10. Output format REQUIRED for every reply — Chinese first, then the translation on its own line starting with 'English:' (or your real language name):\n\n[one or two short Chinese sentences]\n\n" + langName + ": [natural translation of those Chinese sentences]\n";
  } else if (chineseLevel === 'advanced') {
    systemInstruction = "You are Li Laoshi, a Chinese tutor for an ADVANCED learner (3+ years of study).\n" + baseRules +
      "TEACHING STYLE (advanced):\n" +
      "1. Respond ONLY in natural Chinese with native-level vocabulary and idioms (3-5 sentences).\n" +
      "2. Do NOT add pinyin unless the student explicitly asks for it.\n" +
      "3. Do NOT translate into " + langName + " unless the student asks; if the student writes in " + langName + ", answer briefly in " + langName + " then continue in Chinese.\n" +
      "4. Correct mistakes briefly, in Chinese, and only when significant.\n" +
      "5. NEVER repeat a phrase or idea already used earlier in the chat — always respond directly to what the student just said and advance the topic.";
  } else {
    systemInstruction = "You are Li Laoshi, a Chinese tutor for an INTERMEDIATE learner (about HSK 3-4).\n" + baseRules +
      "TEACHING STYLE (intermediate):\n" +
      "1. Respond in Chinese first (2-3 moderately simple sentences), then provide the " + langName + " translation. Format exactly:\n\n[Chinese text here]\n\n" + langName + ": [" + langName + " translation here]\n\nExample:\n你觉得运动重要吗？我每周都跑步。\n\n" + langName + ": Do you think exercise is important? I run every week.\n" +
      "2. Include pinyin in parentheses only for NEW characters you introduce.\n" +
      "3. If the student writes in " + langName + ", answer their question in " + langName + " and teach the Chinese phrases they need.\n" +
      "4. Keep responses moderate: 2-3 simple Chinese sentences max, mostly HSK 3 vocabulary. Do not overwhelm the student.\n" +
      "5. NEVER repeat a phrase, translation, or question already used earlier in the chat — respond to exactly what the student just said and advance to something NEW.\n" +
      "6. Vary your openings and wording every reply; never open with the same sentence twice.";
  }
  
  const payload = {
    contents: geminiHistory,
    systemInstruction: systemInstruction
  };
  
  fetch('/api/chat', {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  })
  .then(res => {
    if (!res.ok) return res.json().then(errData => { throw new Error(errData.error?.error?.message || errData.error?.message || errData.error || "HTTP error " + res.status); });
    return res.json();
  })
  .then(data => {
    // Replace the "Thinking..." loader capsule in place instead of removing it and
    // inserting a fresh bubble — avoids the visible flash/reflow that causes flicker.
    const loader = document.getElementById(loaderId);
    const loaderCapsule = window._tutLoaderEl && window._tutLoaderEl.contains(loader) ? window._tutLoaderEl : null;
    window._tutLoaderEl = null;
    
    let reply = data.candidates[0].content.parts[0].text.trim();

    // Strip internal control markers before display/speech/history
    const lvlMarkerM = reply.match(/\[LEVEL:\s*(never|beginner|intermediate|advanced)\s*\]/i);
    const upMarkerM = reply.match(/\[LEVELUP:\s*(beginner|intermediate|advanced)\s*\]/i);
    if (lvlMarkerM) reply = reply.replace(lvlMarkerM[0], '').trim();
    if (upMarkerM) reply = reply.replace(upMarkerM[0], '').trim();

    // Parse Chinese and English from the response into separate display text
    let cleanReply = reply;
    let englishTranslation = "";
    
    // Clean the reply: strip stray markdown bold, empty placeholders, empty quotes
    const pre = reply
      .replace(/\*\*\s*\*\*/g, ' ')
      .replace(/\*\*/g, '')
      .replace(/^\s*-\s*/, '')
      .replace(/“\s*”/g, ' ')
      .replace(/""/g, ' ')
      .trim();
    
    // Remove parenthetical pinyin annotations like (nǐ hǎo) from the whole reply
    const pinyinRe = /[A-Za-zāáǎàēéěèīíǐìōóǒòūúǔùǖǘǚǜü\s,，.。'’?？！!-]{2,}/;
    const stripPinyin = (s) => s.replace(new RegExp('\\(' + pinyinRe.source + '\\)','g'), '')
                                .replace(new RegExp('（' + pinyinRe.source + '）','g'), '')
                                .replace(/[，。！？、；：,.!?;:\s\-—]+$/,'')
                                .replace(/\s{2,}/g, ' ')
                                .trim();
    
    // The model is instructed to output Chinese segments, each followed by its
    // translation under a label line (e.g. "English: <translation>"). Replies may
    // contain MULTIPLE Chinese sentences each with its own English block, so we
    // must collect EVERY Chinese run — splitting at the first label would silently
    // drop all later Chinese (the reported bug: spoken/displayed Chinese truncated
    // while the English translation stayed complete). Recognise the tutor language
    // name plus common translation tags.
    const tutorLabel = langName === 'Auto-detect' ? '' : langName;
    const labelCands = [tutorLabel, 'English', 'Translation', '翻译', 'traduzione', 'traducción', 'traduction', 'Übersetzung', 'перевод', 'dịch', 'dịch thuật'].filter(Boolean);
    const escaped = labelCands.map(l => l.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|');
    const labelRe = new RegExp('(?:^|\\n)\\s*(?:' + escaped + ')\\s*(?:\\s*translation)?\\s*[:：]\\s*', 'gi');
    // Indexes of every CJK character so we can tell where an English block ends and
    // the next Chinese sentence begins (English never contains CJK).
    const cjkIndexes = [];
    { const cjkPosRe = /[\u4e00-\u9fa5]/g; let m2; while ((m2 = cjkPosRe.exec(pre)) !== null) cjkIndexes.push(m2.index); }
    const nextCjk = (from) => { let lo = 0, hi = cjkIndexes.length; while (lo < hi) { const mid = (lo + hi) >> 1; if (cjkIndexes[mid] < from) lo = mid + 1; else hi = mid; } return lo < cjkIndexes.length ? cjkIndexes[lo] : -1; };
    const cnParts = [], enParts = [];
    let scanPos = 0;
    labelRe.lastIndex = 0;
    let lm;
    while ((lm = labelRe.exec(pre)) !== null) {
      if (lm.index > scanPos) cnParts.push(pre.slice(scanPos, lm.index));
      const blockFrom = labelRe.lastIndex;
      labelRe.lastIndex = blockFrom;
      const nxt = labelRe.exec(pre);
      labelRe.lastIndex = blockFrom;
      const cjkIdx = nextCjk(blockFrom);
      const enEnd = (cjkIdx !== -1 && (!nxt || cjkIdx < nxt.index)) ? cjkIdx : (nxt ? nxt.index : pre.length);
      enParts.push(pre.slice(blockFrom, enEnd));
      scanPos = enEnd;
    }
    if (scanPos < pre.length) cnParts.push(pre.slice(scanPos));
    cleanReply = stripPinyin(cnParts.join(' ').trim());
    englishTranslation = enParts.map(s => stripPinyin(s)).filter(Boolean).join(' ');

    if (!cleanReply) cleanReply = pre;
    
    // Speak & pronunciation target use ONLY the Chinese characters (never pinyin or English)
    const speechText = (cleanReply.match(/[\u4e00-\u9fa5]+/g) || []).join(' ');
    
    let suggestedAnswer = speechText ? speechText.split(/[？！。.\n]/).filter(s => s.trim().length > 0)[0] || speechText : '';
    
    // Set targets for pronunciation matching
    currentLiveTarget = speechText;
    suggestedUserTarget = suggestedAnswer;
    
    // Show in side panel
    if (!_interviewActive) {
      document.getElementById('tutWd').textContent = speechText;
      document.getElementById('tutWp').textContent = suggestedAnswer;
      document.getElementById('tutWm').textContent = englishTranslation || cleanReply;
    } else {
      document.getElementById('tutWm').textContent = cleanReply;
    }

    // Show the hint button with the suggested answer so beginners always know what to say
    const hintWrapper = document.getElementById('tutHintWrapper');
    const hintText = document.getElementById('tutHintText');
    if (hintWrapper && hintText) {
      if (suggestedAnswer && suggestedAnswer.length <= 12) {
        hintText.textContent = suggestedAnswer;
        hintWrapper.style.display = 'block';
      } else {
        hintWrapper.style.display = 'none';
      }
    }
    
    // Append response to history (store the original full reply)
    geminiHistory.push({ role: "model", parts: [{ text: reply }] });
    
    // Add message to chat, then pause briefly before speaking so the user is done talking
    const hasCn = /[\u4e00-\u9fa5]/.test(cleanReply);
    const botTrId = 'botTr-' + Date.now() + '-' + Math.floor(Math.random() * 1000);
    const initialTr = (englishTranslation && englishTranslation.length >= cleanReply.length * 0.6) ? englishTranslation : '<i class="fas fa-language"></i> ' + t('Translating...');
    const botHtml = '<div class="fc font-bold" style="font-size:20px;margin-bottom:4px">' + formatChineseTextWithRuby(cleanReply) + '</div>' + (hasCn ? '<div id="' + botTrId + '" style="font-size:14px;color:var(--muted);margin-bottom:8px;line-height:1.4">' + initialTr + '</div>' : '') + (speechText ? '<span style="font-size:11px;color:var(--blue);cursor:pointer" onclick="speak(\'' + speechText.replace(/'/g, "\'") + '\')"><i class="fas fa-volume-high"></i> replay</span>' : '');
    if (loaderCapsule) {
      loaderCapsule.innerHTML = botHtml;
      loaderCapsule.style.animation = 'bi .3s ease-out';
    } else {
      addTutMsg('bot', botHtml);
    }
    // If the model's reply has Chinese but no English translation was embedded, fetch one now
    if (hasCn && (!englishTranslation || englishTranslation.length < cleanReply.length * 0.6)) {
      translateToEnglish(cleanReply).then(function(en) {
        const el = document.getElementById(botTrId);
        if (el) el.textContent = en || t('(translation unavailable)');
        const wm = document.getElementById('tutWm');
        if (wm && en) wm.textContent = en;
      }).catch(function() {
        const el = document.getElementById(botTrId);
        if (el) el.textContent = t('(translation unavailable)');
      });
    }
    const isIntroReply = _introTurnForSpeech;
    _introTurnForSpeech = false;

    // Always speak the reply (so the AI tutor is never silently "typing only").
    // For auto-generated intro/greeting turns we still speak, but we do NOT
    // auto-open the mic afterwards — that waiting-for-speech was the echo source,
    // and the mic should only open on explicit user interaction.
    if (speechText) setTimeout(() => speak(speechText), 1100);
    else if (_interviewActive && cleanReply) setTimeout(() => speakViaAPI(cleanReply, getInterviewLangCode(), 1.0), 1100);

    // Auto-listen in Voice Mode or Live AI Mode — but never for an auto-intro
    // turn (the greeting), so the mic doesn't open into the tutor's reply (echo).
    if (!isIntroReply && (voiceModeActive || localStorage.getItem('tutor_mode') === 'live')) {
      setTimeout(() => {
        const waitAndListen = () => {
          if ((voiceModeActive || localStorage.getItem('tutor_mode') === 'live') && !srOn) {
            if (isTtsPlaying()) {
              setTimeout(waitAndListen, 500);
            } else {
              // Ensure the speaker is fully silent before the mic opens — stop any
              // residual/browser TTS and wait a little longer (especially for the
              // very first greeting audio) so it can't ring into the recording.
              try { if (window.speechSynthesis) window.speechSynthesis.cancel(); } catch(e) {}
              // Longer settle after the speaker actually stops: with v69 the boosted
              // TTS now keeps isTtsPlaying() true for its full duration (incl. the
              // async WebAudio decode/schedule window), so this extra delay just lets
              // any residual ring-out decay before the mic opens — prevents self-echo.
              setTimeout(() => { if (!srOn) { stopApiTts(); tutSpeak(); } }, 900);
            }
          }
        };
        waitAndListen();
      }, 2500);
    }

    // Placement interview bookkeeping + level-up offers
    if (_interviewActive) {
      _interviewTurns++;
      if (lvlMarkerM) {
        completePlacement(lvlMarkerM[1].toLowerCase());
      } else if (_interviewTurns >= 7 && !_interviewNudged) {
        _interviewNudged = true;
        geminiHistory.push({ role: "user", parts: [{ text: "(Internal note: please finish the placement NOW — give your short summary in the student's language and output the [LEVEL: ...] marker on its own final line.)" }] });
      }
    }
    if (upMarkerM) offerLevelUp(upMarkerM[1].toLowerCase());

    // Status updates for Live AI Mode
    if (statusText) statusText.textContent = t("Your turn")+' — '+t("press mic");
    document.getElementById('tutHint').textContent = t("Type Chinese below or press mic");
  })
  .catch(err => {
    console.error("Gemini Error:", err);
    const loader = document.getElementById(loaderId);
    if (loader) loader.remove();
    if (!navigator.onLine) {
      addTutMsg('warn', '⚠️ <b>'+t('Internet connection lost')+'</b> — '+t('Live AI Mode requires an internet connection. Please reconnect and try again.'));
      if (statusText) statusText.textContent = t('Disconnected');
      document.getElementById('tutHint').innerHTML = '<span style="color:var(--accent2);font-weight:700"><i class="fas fa-wifi-slash"></i> '+t('No internet — Live AI unavailable')+'</span>';
    } else {
      addTutMsg('warn', '⚠️ <b>'+t('Tutor Connection Failed')+'</b> — '+t('Error generating reply. Please try again later.'));
      if (statusText) statusText.textContent = t("Error");
    }
    // Auto-retry listening in voice mode after error
    if (voiceModeActive) {
      setTimeout(() => { if (!srOn) tutSpeak(); }, 3000);
    }
  });
}

// ===== TIMED STRUCTURED CLASSES (live in-class style) =====
const TIMED_PHASE_NAMES = ['Warm-up','New Vocabulary','Guided Practice','Review & Quiz','Recap & Homework'];

function timedPhaseName(p) {
  return t(TIMED_PHASE_NAMES[p] || TIMED_PHASE_NAMES[0]);
}

function collectTimedVocab(levelIdx) {
  const lessons = getLessonsForLevel(levelIdx);
  const seen = {}, words = [];
  lessons.forEach(l => (l.words || []).forEach(w => {
    if (w && w.cn && !seen[w.cn]) { seen[w.cn] = 1; words.push(w); }
  }));
  return words.slice(0, 8);
}

function buildTimedAgenda(levelIdx, minutes) {
  const totalMin = Math.max(5, parseInt(minutes) || 15);
  const warm = Math.max(1, Math.round(totalMin * 0.15));
  const vocab = Math.max(2, Math.round(totalMin * 0.25));
  const practice = Math.max(2, Math.round(totalMin * 0.30));
  const review = Math.max(1, Math.round(totalMin * 0.15));
  const recap = Math.max(1, totalMin - warm - vocab - practice - review);
  const vocabSlice = collectTimedVocab(levelIdx);
  const vocabList = vocabSlice.map(w => w.cn + ' (' + (w.py || '') + ') — ' + (w.en || '')).join('\n') || 'Simple words from the lesson topic';
  const levelName = (LV[levelIdx] || { n: 'HSK 1' }).n;
  const levelNum = levelIdx + 1;
  return { totalMin, warm, vocab, practice, review, recap, vocabSlice, vocabList, levelName, levelNum };
}

function buildTimedSystemInstruction(agenda) {
  const langName = getTutorLangName();
  const a = agenda;
  return "You are Li Laoshi, a professional Chinese teacher leading a LIVE structured class. The student chose a " + a.levelName + " class of " + a.totalMin + " minutes. Follow the class plan below exactly, like a real in-person lesson. Adjust ALL vocabulary and grammar to the " + a.levelName + " level (HSK " + a.levelNum + " range).\n" +
    "CLASS PLAN (total " + a.totalMin + " minutes — pace yourself so every phase is covered, keep each phase roughly within its budget):\n" +
    "1. Warm-up (" + a.warm + " min): Greet the student warmly in Chinese, ask how they are, review 1-2 phrases they may know. Keep it SHORT (2-3 exchanges max).\n" +
    "2. New Vocabulary (" + a.vocab + " min): Teach the words below ONE at a time. For each word: Chinese with pinyin in parentheses, its " + langName + " meaning, and ONE short example sentence. After each word ask the student to repeat it aloud (give: You can say: <pinyin>). Then quickly recap all the words together.\n" +
    "3. Guided Practice (" + a.practice + " min): Hold a short conversation using the new words. Ask simple questions, always give the exact answer the student can say, correct gently, and praise effort.\n" +
    "4. Review & Quiz (" + a.review + " min): Ask 3-4 quick review questions that mix the new words (meaning, pinyin, or use-in-a-sentence).\n" +
    "5. Recap & Homework (" + a.recap + " min): Summarize what was learned (list the words with pinyin), give ONE small homework task, and say goodbye.\n\n" +
    "VOCABULARY FOR THIS CLASS:\n" + a.vocabList + "\n\n" +
    "TEACHING RULES:\n" +
    "1. Use " + langName + " for all explanations and translations; teach Chinese with pinyin in parentheses.\n" +
    "2. Always understand what the student says in ANY language; never ignore them. If they write in " + langName + ", acknowledge them first, then teach the Chinese phrase they need.\n" +
    "3. Correct gently: correct sentence first, then one short " + langName + " explanation.\n" +
    "4. Keep every message concise (2-4 sentences) and always end with a question or a clear 'your turn'.\n" +
    "5. Praise genuine effort warmly.\n" +
    "6. When you receive an internal cue that starts with （阶段提示：...）, immediately switch to that phase and continue teaching — do not mention the cue.\n" +
    "7. If the student wants to go faster or slower, respect their pace but still try to complete the class plan.\n" +
    "8. If the student writes in Chinese, respond in Chinese and give a fluent " + langName + " translation.";
}

function openTimedClassModal() {
  const modal = document.getElementById('timedClassModal');
  if (!modal) return;
  const lvSel = document.getElementById('timedLvSelect');
  if (lvSel) {
    lvSel.innerHTML = '';
    LV.forEach((l, i) => {
      const o = document.createElement('option');
      o.value = i;
      o.textContent = l.n + ' — ' + l.d;
      lvSel.appendChild(o);
    });
    if (typeof curLv === 'number' && curLv >= 0) lvSel.value = String(curLv);
  }
  const firstDur = document.querySelector('.timed-dur-btn');
  if (firstDur && !document.querySelector('.timed-dur-btn[data-selected]')) pickTimedDuration(firstDur, parseInt(firstDur.getAttribute('data-min') || '15', 10));
  modal.style.display = 'flex';
}

function closeTimedClassModal() {
  const modal = document.getElementById('timedClassModal');
  if (modal) modal.style.display = 'none';
}

function pickTimedDuration(btn, minutes) {
  document.querySelectorAll('.timed-dur-btn').forEach(b => {
    b.style.background = 'var(--card2)';
    b.style.color = 'var(--fg)';
    b.style.borderColor = 'var(--border)';
  });
  btn.style.background = 'var(--gold)';
  btn.style.color = '#000';
  btn.style.borderColor = 'var(--gold)';
  btn.setAttribute('data-selected', String(minutes));
}

function startTimedClass() {
  const lvSel = document.getElementById('timedLvSelect');
  const selectedDur = document.querySelector('.timed-dur-btn[data-selected]');
  const minutes = selectedDur ? parseInt(selectedDur.getAttribute('data-min') || '15', 10) : 15;
  const levelIdx = parseInt((lvSel && lvSel.value) || '0', 10);
  if (!hasPremiumAccess() && levelIdx >= 1) {
    closeTimedClassModal();
    showPremiumPaywall(LV[levelIdx].n);
    return;
  }
  closeTimedClassModal();
  const agenda = buildTimedAgenda(levelIdx, minutes);
  timedClassLevel = levelIdx;
  timedClassMinutes = agenda.totalMin;
  timedClassSecondsLeft = agenda.totalMin * 60;
  timedClassPhase = 0;
  timedCueSent = {};
  timedCueTimers = [];
  timedSystemInstruction = buildTimedSystemInstruction(agenda);

  // Reset the live AI session state
  tutLesson = TL[0];
  tutScores = [];
  geminiHistory = [];
  currentLiveTarget = '';
  suggestedUserTarget = '';
  const chat = document.getElementById('tutChat');
  if (chat) chat.innerHTML = '<div class="csys"><i class="fas fa-info-circle mr-1"></i> ' + t('Live AI Mode:') + ' ' + t('Timed class in progress.') + '</div>';
  resetTutorTotal();

  // Ensure Live AI mode is active
  if (localStorage.getItem('tutor_mode') !== 'live') {
    localStorage.setItem('tutor_mode', 'live');
    const modeSelect = document.getElementById('tutorModeSelect');
    if (modeSelect) modeSelect.value = 'live';
    const btn = document.getElementById('tutRoleplayBtn');
    if (btn) {
      btn.style.background = 'var(--neon-cyan)';
      btn.style.color = '#000';
      btn.innerHTML = '<i class="fas fa-robot mr-1"></i>Live AI';
    }
  }
  setBtns(true);

  timedClassActive = true;
  const bar = document.getElementById('timedClassBar');
  if (bar) bar.style.display = 'flex';
  const lvEl = document.getElementById('timedClassLv');
  if (lvEl) lvEl.textContent = agenda.levelName;
  updateTimedPhaseLabel();
  updateTimedTimerUI();
  scrollToSection('#tutor');

  startTimedTimer();
  scheduleTimedCues(agenda);
  sendToGemini('（课堂开始）老师，请开始今天的' + agenda.levelName + '课程。先打招呼，然后按照教学计划进行。');
}

function scheduleTimedCues(agenda) {
  const a = agenda;
  const minutes = a.totalMin * 60;
  const plan = [
    { phase: 1, at: a.warm * 60, cue: '（阶段提示：热身结束。现在进入第二阶段：新词汇教学。请逐个介绍本课词汇，先教发音，再给例句，让学生跟着读。）' },
    { phase: 2, at: (a.warm + a.vocab) * 60, cue: '（阶段提示：新词汇教学结束。现在进入第三阶段：口语练习。用刚学的词汇与学生进行简短对话，每个问题后给出学生可以说出的答案。）' },
    { phase: 3, at: (a.warm + a.vocab + a.practice) * 60, cue: '（阶段提示：口语练习结束。现在进入第四阶段：复习与快速测验。出3-4个简单问题复习本节课词汇。）' },
    { phase: 4, at: (a.warm + a.vocab + a.practice + a.review) * 60, cue: '（阶段提示：复习结束。现在进入最后阶段：课堂总结。列出今天学的所有词汇，布置一个小作业，然后告别。）' }
  ];
  plan.forEach(b => {
    if (b.at >= minutes) return;
    const timer = setTimeout(() => {
      if (!timedClassActive || timedCueSent[b.phase]) return;
      timedCueSent[b.phase] = true;
      timedClassPhase = b.phase;
      updateTimedPhaseLabel();
      sendToGemini(b.cue);
    }, b.at * 1000);
    timedCueTimers.push(timer);
  });
}

function updateTimedPhaseLabel() {
  const el = document.getElementById('timedClassPhase');
  if (el) el.textContent = timedPhaseName(timedClassPhase);
}

function startTimedTimer() {
  if (timedClassTimer) clearInterval(timedClassTimer);
  timedClassTimer = setInterval(() => {
    timedClassSecondsLeft--;
    updateTimedTimerUI();
    if (timedClassSecondsLeft <= 0) {
      clearInterval(timedClassTimer);
      timedClassTimer = null;
      endTimedClass();
    }
  }, 1000);
}

function updateTimedTimerUI() {
  const el = document.getElementById('timedTimer');
  if (!el) return;
  const s = Math.max(0, timedClassSecondsLeft);
  const m = Math.floor(s / 60);
  const sec = s % 60;
  el.textContent = m + ':' + (sec < 10 ? '0' : '') + sec;
  el.style.color = s <= 120 ? 'var(--accent)' : 'var(--gold)';
  const prog = document.getElementById('timedClassProgress');
  if (prog) prog.style.width = (100 * s / (timedClassMinutes * 60)).toFixed(1) + '%';
}

function endTimedClass() {
  if (!timedClassActive) return;
  const minutes = timedClassMinutes;
  const levelIdx = timedClassLevel;
  if (timedClassTimer) { clearInterval(timedClassTimer); timedClassTimer = null; }
  timedCueTimers.forEach(t => clearTimeout(t));
  timedCueTimers = [];
  timedClassPhase = 4;
  updateTimedPhaseLabel();

  // Award progress: XP + daily activity + mark class vocab as learned
  try {
    trackDaily('lessons');
    addXP(Math.max(5, Math.round(minutes * 2)), 'timed_class');
    const learned = JSON.parse(localStorage.getItem('learned_words') || '{}');
    collectTimedVocab(levelIdx).forEach(w => { learned[w.cn] = true; });
    localStorage.setItem('learned_words', JSON.stringify(learned));
    if (typeof updateProgress === 'function') updateProgress();
  } catch (e) {}

  sendToGemini('（时间到！老师，请给这节课做个简短的课堂总结：列出今天学的所有词汇，布置一个小作业，然后向学生告别。请保持简洁。）');
  timedClassActive = false;
  timedSystemInstruction = null;

  const bar = document.getElementById('timedClassBar');
  if (bar) setTimeout(() => { bar.style.display = 'none'; }, 5000);
  toast('🎓 ' + t('Class complete! +') + (Math.max(5, Math.round(minutes * 2))) + ' XP', 'var(--gold)', 4000);
}

function useHint() {
  if (!suggestedUserTarget) return;
  // 1. Speak the suggested answer so they can hear it
  speak(suggestedUserTarget);
  // 2. Fill the input text box
  const input = document.getElementById('tutTypeInput');
  if (input) {
    input.value = suggestedUserTarget;
  }
  toast(t("Hint selected! Speak now or click Submit."), "var(--gold)");
}

// ===== AI GRAMMAR CHECK =====
// ===== GRAMMAR EXERCISES =====
const GRAMMAR_EXERCISES = [
  {id:'ge1',pattern:'了 (perfective)',prompt:t('Fill in the blank with 了'),cn:'我昨天买___一本书。',answer:'了',options:['了','过','的','着'],explanation:t('了 indicates completion of an action.')},
  {id:'ge2',pattern:'把 (object-fronting)',prompt:t('Reorder using 把'),cn:'我把门关___。',answer:'上',options:['上','开','了','好'],explanation:t('把 + object + verb + complement')},
  {id:'ge3',pattern:'被 (passive)',prompt:t('Fill in the blank with 被'),cn:'他___老师批评了。',answer:'被',options:['被','把','让','给'],explanation:t('被 introduces the agent in passive sentences.')},
  {id:'ge4',pattern:'比 (comparison)',prompt:t('Fill in the blank with 比'),cn:'他___我高。',answer:'比',options:['比','跟','对','为'],explanation:t('比 is used for comparisons: A + 比 + B + Adj')},
  {id:'ge5',pattern:'是...的 (emphasis)',prompt:t('Fill in the blanks'),cn:'我___昨天来___。',answer:'是',options:['是','的','了','在'],explanation:t('是...的 emphasizes time/place/manner of a past action.')},
  {id:'ge6',pattern:'正在 (progressive)',prompt:t('Fill in the blank'),cn:'他___吃东西。',answer:'正在',options:['正在','已经','了','过'],explanation:t('正在 indicates an action in progress.')},
  {id:'ge7',pattern:'虽然...但是 (although...)',prompt:t('Fill in the blanks'),cn:'___天气不好，___他还是出去了。',answer:'虽然',options:['虽然','但是','因为','所以'],explanation:t('虽然...但是 = although...but/still...')},
  {id:'ge8',pattern:'因为...所以 (because...so)',prompt:t('Fill in the blanks'),cn:'___下雨，___我没去。',answer:'因为',options:['因为','所以','虽然','但是'],explanation:t('因为...所以 = because...therefore...')},
  {id:'ge9',pattern:'一边...一边 (simultaneous)',prompt:t('Fill in the blank'),cn:'他一边走路___唱歌。',answer:'一边',options:['一边','一起','一下','一样'],explanation:t('一边 + Verb1 + 一边 + Verb2 = doing two things simultaneously')},
  {id:'ge10',pattern:'才 (only then)',prompt:t('Fill in the blank'),cn:'他九点___起床。',answer:'才',options:['才','就','还','也'],explanation:t('才 indicates lateness or "only then"')},
  {id:'ge11',pattern:'就 (immediately)',prompt:t('Fill in the blank'),cn:'我马上___来。',answer:'就',options:['就','才','还','再'],explanation:t('就 indicates immediacy or "right away"')},
  {id:'ge12',pattern:'过 (experience)',prompt:t('Fill in the blank'),cn:'我去___中国。',answer:'过',options:['过','了','着','的'],explanation:t('过 indicates having experienced something.')},
  {id:'ge13',pattern:'着 (continuous state)',prompt:t('Fill in the blank'),cn:'门开___。',answer:'着',options:['着','了','过','的'],explanation:t('着 indicates a continuing state or action.')},
  {id:'ge14',pattern:'从...到 (from...to)',prompt:t('Fill in the blanks'),cn:'我___家___学校走路。',answer:'从',options:['从','到','在','离'],explanation:t('从...到 = from...to (place or time)')},
  {id:'ge15',pattern:'除了...以外 (except/besides)',prompt:t('Fill in the blank'),cn:'___你以外，大家都来了。',answer:'除了',options:['除了','因为','虽然','如果'],explanation:t('除了...以外 = except for / besides')},
];
let grammarExIdx = 0, grammarExScore = 0;

// ===== GRAMMAR EXERCISE =====
// Shuffle multiple-choice options and remap the correct-answer index so the
// right answer is never always the same letter/position.
function randomizeOptions(oArr, correctIndex) {
  const shuffled = [...oArr].sort(() => Math.random() - 0.5);
  return { shuffled: shuffled, a: shuffled.indexOf(oArr[correctIndex]) };
}

function startGrammarExercise() {
  grammarExIdx = 0;
  grammarExScore = 0;
  showGrammarExercise();
}

function showGrammarExercise() {
  if (grammarExIdx >= GRAMMAR_EXERCISES.length) {
    showGrammarExerciseResult();
    return;
  }
  const ex = GRAMMAR_EXERCISES[grammarExIdx];
  const content = document.getElementById('listenQuizContent');
  if (!content) return;
  document.getElementById('listenQuizOverlay').style.display = 'flex';
  content.innerHTML = '<div style="text-align:center;margin-bottom:16px">'
    + '<div style="font-size:12px;color:var(--muted);margin-bottom:4px">' + t('Grammar Exercise') + ' ' + (grammarExIdx+1) + '/' + GRAMMAR_EXERCISES.length + ' · <span style="color:var(--gold)">' + ex.pattern + '</span></div>'
    + '<div style="font-size:12px;color:var(--fg2)">' + ex.prompt + '</div></div>'
    + '<div style="font-size:22px;font-weight:bold;color:var(--fg);text-align:center;margin-bottom:16px;padding:12px;border-radius:12px;background:var(--card2)">' + ex.cn + '</div>'
    + '<div class="grid gap-2" id="geOptions"></div>'
    + '<div id="geFeedback" class="text-sm mt-4 text-center" style="min-height:24px"></div>';
  
  const optsDiv = document.getElementById('geOptions');
  [...ex.options].sort(() => Math.random() - 0.5).forEach(opt => {
    const b = document.createElement('button');
    b.className = 'bq';
    b.textContent = opt;
    b.onclick = () => {
      document.querySelectorAll('#geOptions .bq').forEach(x => x.disabled = true);
      const fb = document.getElementById('geFeedback');
      if (opt === ex.answer) {
        b.classList.add('ok');
        grammarExScore += 10;
        fb.innerHTML = '<span style="color:var(--green);font-weight:600">✓ ' + t('Correct!') + '</span><br><span style="color:var(--muted);font-size:12px">' + ex.explanation + '</span>';
      } else {
        b.classList.add('no');
        fb.innerHTML = '<span style="color:var(--accent);font-weight:600">✗ ' + t('Correct:') + ' "' + ex.answer + '"</span><br><span style="color:var(--muted);font-size:12px">' + ex.explanation + '</span>';
        // Highlight correct answer
        document.querySelectorAll('#geOptions .bq').forEach(x => { if (x.textContent === ex.answer) x.classList.add('ok'); });
      }
      setTimeout(() => { grammarExIdx++; showGrammarExercise(); }, 2000);
    };
    optsDiv.appendChild(b);
  });
}

function showGrammarExerciseResult() {
  const content = document.getElementById('listenQuizContent');
  const pct = Math.round((grammarExScore / (GRAMMAR_EXERCISES.length * 10)) * 100);
  content.innerHTML = '<div style="font-size:40px;text-align:center;margin-bottom:12px">' + (pct >= 80 ? '🎉' : pct >= 50 ? '👍' : '💪') + '</div>'
    + '<h3 style="text-align:center;margin:0 0 6px;font-size:18px;color:var(--fg)">' + t('Grammar Practice Complete') + '</h3>'
    + '<p style="text-align:center;margin:0 0 8px;font-size:14px;color:var(--muted)">' + grammarExScore + '/' + (GRAMMAR_EXERCISES.length * 10) + ' ' + t('points') + '</p>'
    + '<p style="text-align:center;margin:0 0 20px;font-size:13px;color:var(--gold)">' + Math.round(pct) + '% ' + t('accuracy') + '</p>'
    + '<div style="text-align:center"><button onclick="closeListenQuiz()" class="bp px-8 py-2.5 text-xs font-bold">' + t('Done') + '</button></div>';
  addXP(Math.round(grammarExScore / 3), 'Grammar exercise');
  checkBadges();
}

// ===== PRONUNCIATION PRACTICE =====
let pronWordList = [], pronIdx = 0, pronScore = 0, pronMediaRecorder = null, pronChunks = [];

function startPronunciationPractice() {
  const level = parseInt(localStorage.getItem('curLv') || '0');
  const allWords = [];
  getLessonsForLevel(level).forEach(lesson => {
    lesson.words.forEach(w => { if (!allWords.find(x => x.cn === w.cn)) allWords.push(w); });
  });
  if (allWords.length === 0) {
    // Fallback to basic words
    allWords.push({cn:'你好',py:'nǐ hǎo',en:'Hello'},{cn:'谢谢',py:'xiè xiè',en:'Thank you'},{cn:'再见',py:'zài jiàn',en:'Goodbye'});
  }
  pronWordList = allWords.sort(() => Math.random() - 0.5).slice(0, 5);
  pronIdx = 0;
  pronScore = 0;
  showPronWord();
}

function showPronWord() {
  if (pronIdx >= pronWordList.length) { showPronResult(); return; }
  const w = pronWordList[pronIdx];
  const overlay = document.getElementById('listenQuizOverlay');
  overlay.style.display = 'flex';
  const content = document.getElementById('listenQuizContent');
  content.innerHTML = '<div style="text-align:center;margin-bottom:12px">'
    + '<div style="font-size:12px;color:var(--muted);margin-bottom:4px">' + t('Pronunciation Practice') + ' ' + (pronIdx+1) + '/' + pronWordList.length + '</div>'
    + '<div style="font-size:32px;font-weight:900;color:var(--gold);margin-bottom:4px">' + w.cn + '</div>'
    + '<div style="font-size:14px;color:var(--fg2);margin-bottom:16px">' + w.py + ' · ' + t(w.en) + '</div>'
    + '<div style="display:flex;gap:8px;justify-content:center;margin-bottom:12px">'
    + '<button onclick="speak(\''+w.cn+'\',0.7)" style="width:48px;height:48px;border-radius:50%;border:none;background:var(--card2);color:var(--blue);cursor:pointer;outline:none"><i class="fas fa-volume-high"></i></button>'
    + '<button onclick="startPronRecording()" id="pronRecBtn" style="width:48px;height:48px;border-radius:50%;border:none;background:var(--accent);color:#fff;cursor:pointer;outline:none"><i class="fas fa-microphone"></i></button>'
    + '</div>'
    + '<div id="pronStatus" style="font-size:12px;color:var(--muted);margin-bottom:12px">' + t('Tap the mic to record your voice') + '</div>'
    + '<div id="pronResult" style="font-size:13px;min-height:30px"></div>'
    + '<div id="pronNextBtn" style="display:none;text-align:center;margin-top:12px">'
    + '<button onclick="nextPronWord()" class="bp px-8 py-2 text-xs font-bold">' + t('Next') + ' <i class="fas fa-arrow-right ml-1"></i></button></div></div>';
}

function startPronRecording() {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    document.getElementById('pronStatus').textContent = t('Recording not supported in this browser');
    return;
  }
  const btn = document.getElementById('pronRecBtn');
  if (pronMediaRecorder && pronMediaRecorder.state === 'recording') {
    pronMediaRecorder.stop();
    btn.innerHTML = '<i class="fas fa-microphone"></i>';
    document.getElementById('pronStatus').textContent = t('Processing...');
    return;
  }
  pronChunks = [];
  navigator.mediaDevices.getUserMedia(getMicAudioConstraints()).then(stream => {
    pronMediaRecorder = new MediaRecorder(stream, { mimeType: MediaRecorder.isTypeSupported('audio/webm') ? 'audio/webm' : 'audio/mp4', audioBitsPerSecond: 128000 });
    pronMediaRecorder.ondataavailable = e => { if (e.data.size > 0) pronChunks.push(e.data); };
    pronMediaRecorder.onstop = () => {
      stream.getTracks().forEach(t => t.stop());
      const blob = new Blob(pronChunks, { type: pronMediaRecorder.mimeType });
      evaluatePronWord(blob);
    };
    pronMediaRecorder.start();
    btn.innerHTML = '<i class="fas fa-stop"></i>';
    btn.style.background = 'var(--accent2)';
    document.getElementById('pronStatus').textContent = t('Recording... tap stop when done');
  }).catch(() => {
    document.getElementById('pronStatus').textContent = t('Microphone access denied');
  });
}

async function evaluatePronWord(audioBlob) {
  const w = pronWordList[pronIdx];
  document.getElementById('pronStatus').textContent = t('AI is evaluating...');
  try {
    // Convert blob to base64
    const reader = new FileReader();
    reader.readAsDataURL(audioBlob);
    reader.onload = async () => {
      const base64 = reader.result.split(',')[1];
      const mimeType = audioBlob.type;
      const payload = {
        contents: [{ role: 'user', parts: [{ inlineData: { data: base64, mimeType: mimeType } }] }],
        systemInstruction: 'You are a Chinese pronunciation checker. The text below was transcribed from audio. Compare it to the expected word "' + w.cn + '" (pinyin: ' + w.py + '). If it matches or is very close, respond: CORRECT|transcribed_text. If it is significantly different, respond: WRONG|transcribed_text|expected_word. Ignore minor differences in punctuation or spaces. Only respond in this format.',
        sourceLang: 'zh'
      };
      const r = await fetch('/api/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
      const d = await r.json();
      const reply = (d.candidates?.[0]?.content?.parts?.[0]?.text || '');
      const resultEl = document.getElementById('pronResult');
      const statusEl = document.getElementById('pronStatus');
      const nextBtn = document.getElementById('pronNextBtn');
      
      if (reply.startsWith('CORRECT')) {
        const transcribed = reply.split('|')[1] || '';
        resultEl.innerHTML = '<span style="color:var(--green);font-weight:600">✓ ' + t('Great pronunciation!') + '</span><br><span style="color:var(--muted);font-size:11px">' + t('You said:') + ' ' + escHtml(transcribed) + '</span>';
        pronScore += 10;
        statusEl.textContent = '';
      } else if (reply.startsWith('WRONG')) {
        const parts = reply.split('|');
        const transcribed = parts[1] || '';
        resultEl.innerHTML = '<span style="color:var(--accent);font-weight:600">✗ ' + t('Try again') + '</span><br><span style="color:var(--muted);font-size:11px">' + t('You said:') + ' ' + escHtml(transcribed) + '<br>' + t('Expected:') + ' ' + w.cn + ' (' + w.py + ')</span>';
        statusEl.textContent = t('Listen to the correct pronunciation and try again');
      } else {
        resultEl.innerHTML = '<span style="color:var(--gold)">' + t('Could not analyze. Try speaking clearly.') + '</span>';
        statusEl.textContent = '';
      }
      nextBtn.style.display = 'block';
      document.getElementById('pronRecBtn').style.background = 'var(--accent)';
      document.getElementById('pronRecBtn').innerHTML = '<i class="fas fa-microphone"></i>';
    };
  } catch {
    document.getElementById('pronResult').innerHTML = '<span style="color:var(--accent)">' + t('Error analyzing pronunciation') + '</span>';
    document.getElementById('pronNextBtn').style.display = 'block';
  }
}

function nextPronWord() {
  pronIdx++;
  showPronWord();
}

function showPronResult() {
  const content = document.getElementById('listenQuizContent');
  const pct = pronWordList.length > 0 ? Math.round((pronScore / (pronWordList.length * 10)) * 100) : 0;
  content.innerHTML = '<div style="font-size:40px;text-align:center;margin-bottom:12px">' + (pct >= 80 ? '🎉' : pct >= 50 ? '👍' : '💪') + '</div>'
    + '<h3 style="text-align:center;margin:0 0 6px;font-size:18px;color:var(--fg)">' + t('Pronunciation Practice Complete') + '</h3>'
    + '<p style="text-align:center;margin:0 0 4px;font-size:14px;color:var(--muted)">' + t('Score:') + ' ' + pronScore + '/' + (pronWordList.length * 10) + '</p>'
    + '<p style="text-align:center;margin:0 0 20px;font-size:13px;color:var(--gold)">' + pct + '% ' + t('accuracy') + '</p>'
    + '<div style="text-align:center"><button onclick="closeListenQuiz()" class="bp px-8 py-2.5 text-xs font-bold">' + t('Done') + '</button></div>';
  addXP(Math.round(pronScore / 2), 'Pronunciation practice');
  checkBadges();
}

// ===== GRAMMAR CHECK =====
function grammarCheck() {
  const input = document.getElementById('grammarInput');
  const text = input ? input.value.trim() : '';
  if (!text) { toast(t('Please enter Chinese text to check'), 'var(--gold)'); return; }
  
  const btn = document.getElementById('grammarCheckBtn');
  if (btn) btn.disabled = true;
  const loaderId = 'gc-' + Date.now();
  const resultDiv = document.getElementById('grammarResult');
  if (resultDiv) resultDiv.innerHTML = '<div id="' + loaderId + '" class="animate-pulse" style="padding:12px"><i class="fas fa-spinner fa-spin mr-2"></i>' + t('Analyzing grammar...') + '</div>';
  
  const langName = currentAppLang === 'es' ? 'Spanish' : currentAppLang === 'fr' ? 'French' : currentAppLang === 'ja' ? 'Japanese' : currentAppLang === 'ko' ? 'Korean' : currentAppLang === 'de' ? 'German' : currentAppLang === 'pt' ? 'Portuguese' : currentAppLang === 'it' ? 'Italian' : currentAppLang === 'ru' ? 'Russian' : currentAppLang === 'vi' ? 'Vietnamese' : 'English';
  
  const payload = {
    contents: [{ role: "user", parts: [{ text: text }] }],
    systemInstruction: "You are a professional Chinese grammar tutor. Analyze the Chinese text below and provide clear grammar feedback. Format your response in " + langName + " as:\n\n**📝 Original Text**: [the text]\n\n**✅ Issues Found**: (list each issue with the incorrect part, correction, and grammar rule in simple terms. If no issues, write: No grammar issues found! Your Chinese looks great!)\n\n**💡 Tips**: (1-2 practical grammar tips related to the text)\n\n**✨ Improved Version**: (a corrected version if needed, otherwise: None needed — it's correct!)\n\nBe concise and encouraging. Use the learner's native language (" + langName + ") for explanations."
  };
  
  fetch('/api/chat', {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload)
  })
  .then(res => {
    if (!res.ok) return res.json().then(errData => { throw new Error(errData.error?.error?.message || errData.error?.message || errData.error || "HTTP " + res.status); });
    return res.json();
  })
  .then(data => {
    const el = document.getElementById(loaderId);
    if (el) el.remove();
    const reply = data.candidates?.[0]?.content?.parts?.[0]?.text || '(No response)';
    if (resultDiv) resultDiv.innerHTML = '<div class="cd p-4 rounded-xl" style="background:var(--card2);border:1px solid var(--border);line-height:1.7">' + reply.replace(/\n/g, '<br>').replace(/\*\*(.*?)\*\*/g, '<b>$1</b>') + '</div>';
    if (btn) btn.disabled = false;
    // Save to history
    saveGrammarCheck(text, reply);
    addXP(3, 'Grammar check');
    toast(t('Grammar analysis complete! +3 XP'), 'var(--green)');
  })
  .catch(err => {
    console.error("Grammar Check Error:", err);
    const el = document.getElementById(loaderId);
    if (el) el.remove();
    if (resultDiv) resultDiv.innerHTML = '<div style="color:var(--accent);padding:8px">⚠️ ' + t('Error checking grammar: ') + err.message + '</div>';
    if (btn) btn.disabled = false;
  });
}

function saveGrammarCheck(text, result) {
  let history = JSON.parse(localStorage.getItem('grammar_history') || '[]');
  history.unshift({ text: text.substring(0, 100), result: result.substring(0, 200), time: Date.now() });
  if (history.length > 10) history = history.slice(0, 10);
  localStorage.setItem('grammar_history', JSON.stringify(history));
  showGrammarHistory();
}

function showGrammarHistory() {
  const container = document.getElementById('grammarHistory');
  const list = document.getElementById('grammarHistoryList');
  if (!container || !list) return;
  const history = JSON.parse(localStorage.getItem('grammar_history') || '[]');
  if (history.length === 0) { container.style.display = 'none'; return; }
  container.style.display = 'block';
  list.innerHTML = history.map((item, i) => {
    const date = new Date(item.time);
    const dateStr = date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    return '<div class="cd p-2.5 rounded-xl" style="background:var(--card2);border:1px solid var(--border);cursor:pointer" onclick="document.getElementById(\'grammarInput\').value=\'' + item.text.replace(/'/g, "\\'") + '\';grammarCheck()"><div class="font-medium text-sm" style="color:var(--fg2)">' + item.text + '</div><div class="text-[10px]" style="color:var(--muted)">' + dateStr + '</div></div>';
  }).join('');
}

