function subscribePremium() {
  // Web / PWA: use PayPal server API
  toast(t("Contacting PayPal..."), "var(--gold)");
  fetch('/api/paypal/create-order', { method:'POST' })
  .then(function(r) { return r.json(); })
  .then(function(data) {
    if (!data.id) throw new Error(data.error || 'Failed to create order');
    return fetch('/api/paypal/capture-order', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body:JSON.stringify({ orderId: data.id })
    });
  })
  .then(function(r) { return r.json(); })
  .then(function(details) {
    if (details.status === 'COMPLETED') {
      localStorage.setItem('is_premium', 'true');
      localStorage.removeItem('premium_expiry');
      localStorage.removeItem('mandarin30_used');
      togglePremiumModal();
      updatePremiumUI();
      if (lessonsMode === 'topics') buildTopics();
      else if (lessonsMode === 'podcast') buildPodcastTopics();
      else buildFlashcards();
      toast(t("Welcome to MandarinCourse Premium! HSK 1-9 Unlocked."), "var(--green)");
    } else {
      toast(t("Payment not completed. Please try again."), "var(--accent)");
    }
  })
  .catch(function(err) {
    toast(t("Payment error: ") + (err.message || t("Please try again.")), "var(--accent)");
  });
}

// ===== PREMIUM UNLOCK & HSK 4-9 DYNAMIC LESSON GENERATOR =====
function getLessonsForLevel(levelIdx) {
  const levelNames = ["HSK 1", "HSK 2", "HSK 3", "HSK 4", "HSK 5", "HSK 6", "HSK 7", "HSK 8", "HSK 9"];
  const levelName = levelNames[levelIdx];
  const staticLessons = TL.filter(l => l.level === levelName);
  if (staticLessons.length > 0) return staticLessons;
  var levelData = [{
    level:"HSK 4",icon:"fa-briefcase",topics:[
    {title:"Online Shopping (网购)",words:[{cn:"网购",py:"wǎng gòu",en:"online shopping",tip:"Buying goods via internet."},{cn:"快递",py:"kuài dì",en:"express delivery",tip:"Fast parcel service."},{cn:"退货",py:"tuì huò",en:"return goods",tip:"Send a purchase back."},{cn:"评价",py:"píng jià",en:"review / rating",tip:"Feedback on a product."},{cn:"质量",py:"zhì liàng",en:"quality",tip:"Standard of a product."},{cn:"价格",py:"jià gé",en:"price",tip:"Cost of an item."},{cn:"退款",py:"tuì kuǎn",en:"refund",tip:"Money returned."},{cn:"收藏",py:"shōu cáng",en:"to collect / bookmark",tip:"Save an item for later."}],dialogue:[
    {who:"bot",cn:"你喜欢网购吗？",en:"Do you like online shopping?"},{who:"you",cn:"喜欢，网购很方便，价格也便宜。",en:"Yes, online shopping is very convenient and prices are cheaper."},{who:"bot",cn:"你最近买了什么？",en:"What did you buy recently?"},{who:"you",cn:"我买了一件衣服，但是质量不太好。",en:"I bought a piece of clothing, but the quality is not very good."},{who:"bot",cn:"那你可以退货，申请退款。",en:"Then you can return it and apply for a refund."},{who:"you",cn:"我已经申请了，快递员明天来取。",en:"I already applied, the courier will pick it up tomorrow."},{who:"bot",cn:"以后买东西先看评价再下单。",en:"Next time check the reviews before ordering."},{who:"you",cn:"你说得对，谢谢你的建议！",en:"You're right, thanks for the advice!"}]},
    {title:"Environment (环境)",words:[{cn:"环境",py:"huán jìng",en:"environment",tip:"Surroundings / nature."},{cn:"污染",py:"wū rǎn",en:"pollution",tip:"Contamination of air/water."},{cn:"保护",py:"bǎo hù",en:"to protect",tip:"Keep safe."},{cn:"回收",py:"huí shōu",en:"to recycle",tip:"Process waste into reusable material."},{cn:"减少",py:"jiǎn shǎo",en:"to reduce",tip:"Make less / decrease."},{cn:"浪费",py:"làng fèi",en:"to waste",tip:"Use carelessly."},{cn:"可持续",py:"kě chí xù",en:"sustainable",tip:"Able to continue long-term."},{cn:"垃圾分类",py:"lā jī fēn lèi",en:"waste sorting",tip:"Separating trash into categories."}],dialogue:[
    {who:"bot",cn:"你觉得环境污染严重吗？",en:"Do you think environmental pollution is serious?"},{who:"you",cn:"很严重，我们应该保护环境。",en:"Very serious, we should protect the environment."},{who:"bot",cn:"怎么保护呢？",en:"How can we protect it?"},{who:"you",cn:"少用塑料袋，做好垃圾分类。",en:"Use fewer plastic bags and sort trash properly."},{who:"bot",cn:"还有回收利用也很重要。",en:"Recycling is also very important."},{who:"you",cn:"对，减少浪费，支持可持续产品。",en:"Right, reduce waste and support sustainable products."},{who:"bot",cn:"每个人都可以做出改变。",en:"Everyone can make a difference."},{who:"you",cn:"从今天开始，我会更加注意。",en:"Starting today, I'll pay more attention."}]},
    {title:"Health & Fitness (健康)",words:[{cn:"健康",py:"jiàn kāng",en:"health",tip:"Physical well-being."},{cn:"锻炼",py:"duàn liàn",en:"to exercise",tip:"Physical training."},{cn:"减肥",py:"jiǎn féi",en:"lose weight",tip:"Reduce body weight."},{cn:"饮食",py:"yǐn shí",en:"diet / food",tip:"Eating habits."},{cn:"肌肉",py:"jī ròu",en:"muscle",tip:"Body tissue."},{cn:"瑜伽",py:"yú jiā",en:"yoga",tip:"A practice of postures."},{cn:"跑步",py:"pǎo bù",en:"jogging / running",tip:"Running as exercise."},{cn:"睡眠",py:"shuì mián",en:"sleep",tip:"Rest at night."}],dialogue:[
    {who:"bot",cn:"你平时锻炼身体吗？",en:"Do you usually exercise?"},{who:"you",cn:"我每周跑步三次，也做瑜伽。",en:"I run three times a week and also do yoga."},{who:"bot",cn:"很好！饮食方面也要注意。",en:"Great! You should also watch your diet."},{who:"you",cn:"对，我少吃油腻的食物。",en:"Right, I eat less greasy food."},{who:"bot",cn:"睡眠也很重要，每天要睡够八小时。",en:"Sleep is also important, get at least eight hours a day."},{who:"you",cn:"我有时候熬夜，需要改。",en:"I sometimes stay up late, I need to change that."},{who:"bot",cn:"坚持锻炼和健康饮食，身体会更好。",en:"Keep exercising and eating healthy, you'll feel better."},{who:"you",cn:"谢谢你鼓励我！",en:"Thanks for encouraging me!"}]},
    {title:"Travel Planning (旅行计划)",words:[{cn:"旅行",py:"lǚ xíng",en:"travel / trip",tip:"Journey to another place."},{cn:"预订",py:"yù dìng",en:"to book / reserve",tip:"Arrange in advance."},{cn:"签证",py:"qiǎn zhèng",en:"visa",tip:"Entry permit."},{cn:"行李",py:"xíng li",en:"luggage",tip:"Bags for travel."},{cn:"航班",py:"háng bān",en:"flight",tip:"Airline journey."},{cn:"酒店",py:"jiǔ diàn",en:"hotel",tip:"Accommodation."},{cn:"景点",py:"jǐng diǎn",en:"scenic spot",tip:"Tourist attraction."},{cn:"护照",py:"hù zhào",en:"passport",tip:"Official travel document."}],dialogue:[
    {who:"bot",cn:"你暑假有什么旅行计划吗？",en:"Any travel plans for summer break?"},{who:"you",cn:"我想去中国旅行，正在办理签证。",en:"I want to travel to China, I'm applying for a visa."},{who:"bot",cn:"机票和酒店预订了吗？",en:"Have you booked the flight and hotel?"},{who:"you",cn:"预订了航班，酒店还没决定。",en:"Booked the flight, but haven't decided on the hotel yet."},{who:"bot",cn:"我推荐你住在市中心，离景点近。",en:"I recommend staying downtown, close to the attractions."},{who:"you",cn:"好主意！行李也要少带一些。",en:"Good idea! I shouldn't bring too much luggage."},{who:"bot",cn:"祝你旅途愉快！记得带护照。",en:"Wish you a great trip! Remember your passport."},{who:"you",cn:"谢谢你，我太期待了！",en:"Thank you, I can't wait!"}]},
    {title:"Technology & Smartphones (科技)",words:[{cn:"科技",py:"kē jì",en:"technology",tip:"Technical innovation."},{cn:"智能手机",py:"zhì néng shǒu jī",en:"smartphone",tip:"A mobile computer."},{cn:"软件",py:"ruǎn jiàn",en:"software",tip:"Computer programs."},{cn:"应用",py:"yìng yòng",en:"app / application",tip:"Mobile software."},{cn:"更新",py:"gēng xīn",en:"to update",tip:"Upgrade version."},{cn:"密码",py:"mì mǎ",en:"password",tip:"Secret code."},{cn:"网络",py:"wǎng luò",en:"network / internet",tip:"Connected systems."},{cn:"数据",py:"shù jù",en:"data",tip:"Information stored digitally."}],dialogue:[
    {who:"bot",cn:"你的智能手机用了多久了？",en:"How long have you had your smartphone?"},{who:"you",cn:"用了两年了，最近有点慢。",en:"Two years, it's been a bit slow lately."},{who:"bot",cn:"可以试试更新软件或者清理数据。",en:"Try updating the software or clearing data."},{who:"you",cn:"我更新过了，但是应用太多了。",en:"I already updated, but I have too many apps."},{who:"bot",cn:"删除不用的应用可以释放空间。",en:"Deleting unused apps can free up space."},{who:"you",cn:"好方法！另外密码也要定期换。",en:"Good idea! I should also change my password regularly."},{who:"bot",cn:"对，网络安全很重要。",en:"Yes, network security is very important."},{who:"you",cn:"谢谢，我现在就去清理手机！",en:"Thanks, I'll clean up my phone now!"}]}]},
    {level:"HSK 5",icon:"fa-newspaper",topics:[
    {title:"News & Current Events (新闻)",words:[{cn:"新闻",py:"xīn wén",en:"news",tip:"Recent information."},{cn:"报道",py:"bào dào",en:"to report / coverage",tip:"A news story."},{cn:"媒体",py:"méi tǐ",en:"media",tip:"Press and broadcasting."},{cn:"采访",py:"cǎi fǎng",en:"to interview",tip:"Journalists ask questions."},{cn:"编辑",py:"biān jí",en:"editor",tip:"Prepares content."},{cn:"直播",py:"zhí bō",en:"live broadcast",tip:"Real-time streaming."},{cn:"订阅",py:"dìng yuè",en:"to subscribe",tip:"Follow a channel."},{cn:"观点",py:"guān diǎn",en:"point of view",tip:"Personal opinion."}],dialogue:[
    {who:"bot",cn:"你平时看新闻吗？",en:"Do you usually watch the news?"},{who:"you",cn:"看，我每天看新闻。",en:"Yes, I watch the news every day."},{who:"bot",cn:"你喜欢看哪方面的报道？",en:"What kind of coverage do you like?"},{who:"you",cn:"我比较关注科技和国际新闻。",en:"I pay more attention to tech and international news."},{who:"bot",cn:"你觉得现在的媒体报道客观吗？",en:"Do you think current media coverage is objective?"},{who:"you",cn:"不一定，不同媒体有不同观点。",en:"Not always, different media have different viewpoints."},{who:"bot",cn:"所以要多看几家媒体的报道。",en:"So you should read coverage from multiple outlets."},{who:"you",cn:"对，这样才能了解全面。",en:"Right, that's how you get a complete picture."}]},
    {title:"Cultural Differences (文化差异)",words:[{cn:"文化",py:"wén huà",en:"culture",tip:"Customs and traditions."},{cn:"差异",py:"chā yì",en:"difference",tip:"How things differ."},{cn:"传统",py:"chuán tǒng",en:"tradition",tip:"Long-established custom."},{cn:"习惯",py:"xí guàn",en:"habit / custom",tip:"Regular practice."},{cn:"礼仪",py:"lǐ yí",en:"etiquette",tip:"Polite behavior."},{cn:"尊重",py:"zūn zhòng",en:"to respect",tip:"Show esteem."},{cn:"价值观",py:"jià zhí guān",en:"value system",tip:"Beliefs about right/wrong."},{cn:"交流",py:"jiāo liú",en:"to communicate",tip:"Exchange ideas."}],dialogue:[
    {who:"bot",cn:"你了解中国文化吗？",en:"Do you know about Chinese culture?"},{who:"you",cn:"了解一些，比如春节和中秋节。",en:"I know some, like Spring Festival and Mid-Autumn Festival."},{who:"bot",cn:"你觉得文化差异大吗？",en:"Do you think the cultural differences are big?"},{who:"you",cn:"有些方面差异很大，比如礼仪和价值观。",en:"Some aspects are very different, like etiquette and values."},{who:"bot",cn:"那你怎么适应这些差异？",en:"How do you adapt to these differences?"},{who:"you",cn:"尊重对方的文化习惯，多交流。",en:"Respect the other culture's customs and communicate more."},{who:"bot",cn:"说得好。学习语言也离不开了解文化。",en:"Well said. Learning a language goes hand in hand with understanding the culture."},{who:"you",cn:"是的，这也是我学习中文的动力之一。",en:"Yes, that's one of my motivations for learning Chinese."}]},
    {title:"Finance & Investment (理财)",words:[{cn:"理财",py:"lǐ cái",en:"financial management",tip:"Manage money wisely."},{cn:"投资",py:"tóu zī",en:"to invest",tip:"Put money into assets."},{cn:"股票",py:"gǔ piào",en:"stock / share",tip:"Equity in a company."},{cn:"基金",py:"jī jīn",en:"fund",tip:"Pooled investment."},{cn:"风险",py:"fēng xiǎn",en:"risk",tip:"Possibility of loss."},{cn:"收益",py:"shōu yì",en:"return / profit",tip:"Money earned."},{cn:"储蓄",py:"chǔ xù",en:"savings",tip:"Money set aside."},{cn:"预算",py:"yù suàn",en:"budget",tip:"Planned spending."}],dialogue:[
    {who:"bot",cn:"你有理财的习惯吗？",en:"Do you have the habit of managing finances?"},{who:"you",cn:"有，我每个月做预算，还会储蓄。",en:"Yes, I budget every month and also save money."},{who:"bot",cn:"有没有考虑投资？",en:"Have you considered investing?"},{who:"you",cn:"考虑过，但是股票风险太大了。",en:"I've thought about it, but stocks are too risky."},{who:"bot",cn:"可以试试基金，风险相对低一些。",en:"You could try funds, they're relatively lower risk."},{who:"bot",cn:"收益虽然不高但比较稳定。",en:"The returns aren't high but are more stable."},{who:"you",cn:"好建议，我会研究一下。",en:"Good advice, I'll look into it."},{who:"bot",cn:"记得分散投资，降低风险。",en:"Remember to diversify your investments to reduce risk."}]},
    {title:"Education Reform (教育改革)",words:[{cn:"教育",py:"jiào yù",en:"education",tip:"Teaching and learning."},{cn:"改革",py:"gǎi gé",en:"reform",tip:"Change to improve."},{cn:"课程",py:"kè chéng",en:"curriculum",tip:"Course of study."},{cn:"考试",py:"kǎo shì",en:"exam / test",tip:"Formal assessment."},{cn:"评估",py:"píng gū",en:"evaluation",tip:"Assess progress."},{cn:"创新",py:"chuàng xīn",en:"innovation",tip:"New ideas/methods."},{cn:"资源",py:"zī yuán",en:"resource",tip:"Available materials."},{cn:"公平",py:"gōng píng",en:"fairness / equity",tip:"Equal treatment."}],dialogue:[
    {who:"bot",cn:"你对教育改革有什么看法？",en:"What do you think about education reform?"},{who:"you",cn:"我觉得应该减少考试压力，注重创新。",en:"I think exam pressure should be reduced, focusing on innovation."},{who:"bot",cn:"同意。课程设置也要更灵活。",en:"Agreed. The curriculum should also be more flexible."},{who:"you",cn:"对，让学生有更多选择。",en:"Right, give students more choices."},{who:"bot",cn:"教育资源分配也要更公平。",en:"Education resources should be distributed more fairly too."},{who:"you",cn:"这是关键，城乡差距需要缩小。",en:"That's key, the urban-rural gap needs to narrow."},{who:"bot",cn:"改革需要时间，但是方向是对的。",en:"Reform takes time, but the direction is right."},{who:"you",cn:"希望未来教育越来越好。",en:"I hope education gets better and better in the future."}]},
    {title:"Art & Literature (文学艺术)",words:[{cn:"文学",py:"wén xué",en:"literature",tip:"Written works."},{cn:"艺术",py:"yì shù",en:"art",tip:"Creative expression."},{cn:"小说",py:"xiǎo shuō",en:"novel",tip:"Long fiction story."},{cn:"诗歌",py:"shī gē",en:"poetry",tip:"Poetic writing."},{cn:"画家",py:"huà jiā",en:"painter",tip:"Artist who paints."},{cn:"展览",py:"zhǎn lǎn",en:"exhibition",tip:"Public display."},{cn:"灵感",py:"líng gǎn",en:"inspiration",tip:"Creative spark."},{cn:"风格",py:"fēng gé",en:"style",tip:"Distinctive manner."}],dialogue:[
    {who:"bot",cn:"你喜欢文学还是艺术？",en:"Do you like literature or art?"},{who:"you",cn:"都喜欢，最近在看一本中国小说。",en:"I like both. I'm reading a Chinese novel recently."},{who:"bot",cn:"哪一本？中文原版吗？",en:"Which one? The original Chinese version?"},{who:"you",cn:"对，中文原版的，可以提高语言水平。",en:"Yes, the original Chinese version, it helps improve my language."},{who:"bot",cn:"太厉害了。你也去看过艺术展览吗？",en:"That's impressive. Have you been to any art exhibitions?"},{who:"you",cn:"去过，我喜欢现代艺术的风格。",en:"Yes, I like the style of modern art."},{who:"bot",cn:"艺术和文学都能给人灵感。",en:"Both art and literature can inspire people."},{who:"you",cn:"是的，它们让我从不同角度看世界。",en:"Yes, they let me see the world from different perspectives."}]}]},
    {level:"HSK 6",icon:"fa-flask",topics:[
    {title:"Scientific Discovery (科学发现)",words:[{cn:"科学",py:"kē xué",en:"science",tip:"Systematic knowledge."},{cn:"发现",py:"fā xiàn",en:"discovery",tip:"Finding something new."},{cn:"实验",py:"shí yàn",en:"experiment",tip:"Scientific test."},{cn:"研究",py:"yán jiū",en:"research",tip:"Systematic investigation."},{cn:"理论",py:"lǐ lùn",en:"theory",tip:"Explanatory framework."},{cn:"数据",py:"shù jù",en:"data",tip:"Collected information."},{cn:"分析",py:"fēn xī",en:"to analyze",tip:"Examine systematically."},{cn:"结论",py:"jié lùn",en:"conclusion",tip:"Final judgment."}],dialogue:[
    {who:"bot",cn:"你对哪个科学领域感兴趣？",en:"Which scientific field interests you?"},{who:"you",cn:"我对人工智能和天文学比较感兴趣。",en:"I'm interested in AI and astronomy."},{who:"bot",cn:"最近有什么重要的科学发现？",en:"Any important scientific discoveries lately?"},{who:"you",cn:"我看到火星上发现了有机物的证据。",en:"I saw evidence of organic matter was found on Mars."},{who:"bot",cn:"这个发现很有意义，可能证明火星曾经有生命。",en:"This discovery is significant, it may prove Mars once had life."},{who:"you",cn:"对，科学家需要更多实验和数据来分析。",en:"Right, scientists need more experiments and data to analyze."},{who:"bot",cn:"期待未来的研究结论。",en:"Looking forward to future research conclusions."},{who:"you",cn:"科学研究永无止境，这也是它迷人的地方。",en:"Scientific research is endless, that's what makes it fascinating."}]},
    {title:"Global Economy (全球经济)",words:[{cn:"经济",py:"jīng jì",en:"economy",tip:"Wealth and resources."},{cn:"全球化",py:"quán qiú huà",en:"globalization",tip:"Worldwide integration."},{cn:"贸易",py:"mào yì",en:"trade",tip:"Buying and selling."},{cn:"市场",py:"shì chǎng",en:"market",tip:"Place of exchange."},{cn:"通货膨胀",py:"tōng huò péng zhàng",en:"inflation",tip:"Rising prices."},{cn:"失业率",py:"shī yè lǜ",en:"unemployment rate",tip:"Jobless proportion."},{cn:"GDP",py:"GDP",en:"gross domestic product",tip:"Total economic output."},{cn:"供应链",py:"gōng yìng liàn",en:"supply chain",tip:"Production network."}],dialogue:[
    {who:"bot",cn:"你怎么看待全球化对经济的影响？",en:"How do you view globalization's impact on the economy?"},{who:"you",cn:"全球化促进了贸易，但也带来了竞争。",en:"Globalization boosted trade but also brought competition."},{who:"bot",cn:"通货膨胀最近很严重。",en:"Inflation has been severe lately."},{who:"you",cn:"对，物价上涨很快，生活成本高了。",en:"Yes, prices are rising fast, the cost of living is higher."},{who:"bot",cn:"失业率也让人担心。",en:"The unemployment rate is also worrying."},{who:"you",cn:"市场变化太快，需要新的技能。",en:"The market changes too fast, new skills are needed."},{who:"bot",cn:"供应链的问题也影响了很多行业。",en:"Supply chain issues have also affected many industries."},{who:"you",cn:"希望经济能尽快稳定下来。",en:"I hope the economy can stabilize soon."}]},
    {title:"Psychology & Emotions (心理学)",words:[{cn:"心理学",py:"xīn lǐ xué",en:"psychology",tip:"Study of the mind."},{cn:"情绪",py:"qíng xù",en:"emotion",tip:"Feelings and moods."},{cn:"压力",py:"yā lì",en:"stress / pressure",tip:"Mental strain."},{cn:"焦虑",py:"jiāo lǜ",en:"anxiety",tip:"Worry / unease."},{cn:"自信",py:"zì xìn",en:"self-confidence",tip:"Belief in oneself."},{cn:"沟通",py:"gōu tōng",en:"communication",tip:"Exchange of information."},{cn:"关系",py:"guān xì",en:"relationship",tip:"Connection between people."},{cn:"治疗",py:"zhì liáo",en:"therapy / treatment",tip:"Medical care."}],dialogue:[
    {who:"bot",cn:"你觉得心理学有趣吗？",en:"Do you think psychology is interesting?"},{who:"you",cn:"很有趣，了解情绪可以帮助自己。",en:"Very interesting, understanding emotions can help yourself."},{who:"bot",cn:"你平时怎么管理压力？",en:"How do you usually manage stress?"},{who:"you",cn:"我会运动或者跟朋友沟通。",en:"I exercise or communicate with friends."},{who:"bot",cn:"有效的方法。焦虑的时候呢？",en:"Effective methods. What about when you're anxious?"},{who:"you",cn:"深呼吸，告诉自己不要担心太多。",en:"Deep breathing, telling myself not to worry too much."},{who:"bot",cn:"自信也很重要。相信自己的能力。",en:"Self-confidence is also important. Believe in your abilities."},{who:"you",cn:"对，正面思考对我的帮助很大。",en:"Right, positive thinking helps me a lot."}]},
    {title:"Philosophy & Ethics (哲学)",words:[{cn:"哲学",py:"zhé xué",en:"philosophy",tip:"Study of existence/knowledge."},{cn:"道德",py:"dào dé",en:"morality / ethics",tip:"Principles of right/wrong."},{cn:"人生",py:"rén shēng",en:"life / human existence",tip:"One's lifetime."},{cn:"意义",py:"yì yì",en:"meaning / significance",tip:"Purpose."},{cn:"自由",py:"zì yóu",en:"freedom / liberty",tip:"Power to act freely."},{cn:"责任",py:"zé rèn",en:"responsibility",tip:"Duty to handle."},{cn:"平等",py:"píng děng",en:"equality",tip:"Equal rights/status."},{cn:"智慧",py:"zhì huì",en:"wisdom",tip:"Deep understanding."}],dialogue:[
    {who:"bot",cn:"你喜欢哲学吗？",en:"Do you like philosophy?"},{who:"you",cn:"喜欢，我觉得人生的意义值得思考。",en:"Yes, I think the meaning of life is worth thinking about."},{who:"bot",cn:"你认为自由和责任之间有什么关系？",en:"What relationship do you see between freedom and responsibility?"},{who:"you",cn:"自由不是绝对的，人需要为自己的行为负责。",en:"Freedom is not absolute, people need to be responsible for their actions."},{who:"bot",cn:"有道理。道德在不同文化中也不一样。",en:"That makes sense. Morality also differs across cultures."},{who:"you",cn:"对，但是平等和尊重是普遍的价值。",en:"Right, but equality and respect are universal values."},{who:"bot",cn:"智慧来自于不断学习和反思。",en:"Wisdom comes from continuous learning and reflection."},{who:"you",cn:"所以我会保持好奇心和开放心态。",en:"So I'll stay curious and keep an open mind."}]},
    {title:"Urban Development (城市发展)",words:[{cn:"城市",py:"chéng shì",en:"city",tip:"Large town."},{cn:"发展",py:"fā zhǎn",en:"development",tip:"Growth process."},{cn:"规划",py:"guī huà",en:"planning",tip:"Design and arrangement."},{cn:"基础设施",py:"jī chǔ shè shī",en:"infrastructure",tip:"Basic facilities."},{cn:"交通堵塞",py:"jiāo tōng dǔ sè",en:"traffic jam",tip:"Gridlock."},{cn:"可持续",py:"kě chí xù",en:"sustainable",tip:"Environmentally enduring."},{cn:"绿化",py:"lǜ huà",en:"greening",tip:"Planting greenery."},{cn:"搬迁",py:"bān qiān",en:"relocation",tip:"Move to another place."}],dialogue:[
    {who:"bot",cn:"你觉得城市发展面临的最大挑战是什么？",en:"What do you think is the biggest challenge facing urban development?"},{who:"you",cn:"交通堵塞是一个大问题。",en:"Traffic congestion is a big problem."},{who:"bot",cn:"对，还有基础设施需要不断升级。",en:"Yes, and infrastructure needs continuous upgrading."},{who:"you",cn:"城市规划要更合理，考虑可持续发展。",en:"Urban planning should be more rational, considering sustainability."},{who:"bot",cn:"绿化也很重要，改善空气质量。",en:"Greening is also important for improving air quality."},{who:"you",cn:"我赞成，多一些公园和绿地。",en:"I agree, more parks and green spaces."},{who:"bot",cn:"搬迁旧城区也很复杂。",en:"Relocating old city areas is also very complex."},{who:"you",cn:"但是为了更好的未来，这些努力是值得的。",en:"But these efforts are worthwhile for a better future."}]}]},
    {level:"HSK 7",icon:"fa-globe",topics:[
    {title:"International Relations (国际关系)",words:[{cn:"外交",py:"wài jiāo",en:"diplomacy",tip:"International negotiation."},{cn:"合作",py:"hé zuò",en:"cooperation",tip:"Working together."},{cn:"冲突",py:"chōng tū",en:"conflict",tip:"Serious disagreement."},{cn:"谈判",py:"tán pàn",en:"negotiation",tip:"Formal discussion."},{cn:"协议",py:"xié yì",en:"agreement / pact",tip:"Formal arrangement."},{cn:"制裁",py:"zhì cái",en:"sanctions",tip:"Penalties imposed."},{cn:"联盟",py:"lián méng",en:"alliance",tip:"Union for common goal."},{cn:"大使",py:"dà shǐ",en:"ambassador",tip:"Top diplomat."}],dialogue:[
    {who:"bot",cn:"你怎么看当前的国际关系？",en:"What do you think about current international relations?"},{who:"you",cn:"国际合作非常重要，尤其是气候变化领域。",en:"International cooperation is vital, especially on climate change."},{who:"bot",cn:"但是冲突和制裁也很多。",en:"But there are also many conflicts and sanctions."},{who:"you",cn:"需要通过谈判和外交途径解决分歧。",en:"Differences need to be resolved through negotiation and diplomacy."},{who:"bot",cn:"协议签署只是第一步，执行更难。",en:"Signing an agreement is just the first step, implementation is harder."},{who:"you",cn:"对，国家之间建立信任很重要。",en:"Right, building trust between countries is important."},{who:"bot",cn:"大使在其中起了关键作用。",en:"Ambassadors play a key role in this."},{who:"you",cn:"希望未来合作多于冲突。",en:"I hope there will be more cooperation than conflict in the future."}]},
    {title:"Biotechnology (生物技术)",words:[{cn:"生物",py:"shēng wù",en:"biology / living things",tip:"Living organisms."},{cn:"基因",py:"jī yīn",en:"gene",tip:"DNA unit."},{cn:"克隆",py:"kè lóng",en:"cloning",tip:"Genetic copy."},{cn:"疫苗",py:"yì miáo",en:"vaccine",tip:"Immunization agent."},{cn:"细胞",py:"xì bāo",en:"cell",tip:"Basic unit of life."},{cn:"进化",py:"jìn huà",en:"evolution",tip:"Gradual development."},{cn:"DNA",py:"DNA",en:"DNA",tip:"Genetic material."},{cn:"伦理",py:"lún lǐ",en:"ethics",tip:"Moral principles."}],dialogue:[
    {who:"bot",cn:"你对生物技术的发展有什么看法？",en:"What do you think about biotech development?"},{who:"you",cn:"基因编辑技术很有前景，但伦理问题值得关注。",en:"Gene editing technology is promising, but ethical issues deserve attention."},{who:"bot",cn:"克隆技术也引起了很大争议。",en:"Cloning technology has also sparked great controversy."},{who:"you",cn:"对，科学进步需要考虑伦理边界。",en:"Right, scientific progress needs to consider ethical boundaries."},{who:"bot",cn:"疫苗的研发拯救了无数生命。",en:"Vaccine research has saved countless lives."},{who:"you",cn:"是的，生物学对人类健康的贡献巨大。",en:"Yes, biology's contribution to human health is enormous."},{who:"bot",cn:"未来个性化医疗会越来越普及。",en:"Personalized medicine will become more common in the future."},{who:"you",cn:"期待生物技术带给人类的福祉。",en:"Looking forward to the benefits biotechnology will bring to humanity."}]},
    {title:"Artificial Intelligence (人工智能)",words:[{cn:"人工智能",py:"rén gōng zhì néng",en:"artificial intelligence",tip:"Machine intelligence."},{cn:"算法",py:"suàn fǎ",en:"algorithm",tip:"Step-by-step procedure."},{cn:"机器学习",py:"jī qì xué xí",en:"machine learning",tip:"AI training method."},{cn:"数据",py:"shù jù",en:"data",tip:"Information for processing."},{cn:"自动驾驶",py:"zì dòng jià shǐ",en:"autonomous driving",tip:"Self-driving technology."},{cn:"机器人",py:"jī qì rén",en:"robot",tip:"Automated machine."},{cn:"隐私",py:"yǐn sī",en:"privacy",tip:"Personal data protection."},{cn:"自动化",py:"zì dòng huà",en:"automation",tip:"Automatic operation."}],dialogue:[
    {who:"bot",cn:"人工智能正在改变世界，你怎么看？",en:"AI is changing the world, what do you think?"},{who:"you",cn:"AI在很多领域都很有用，比如医疗和教育。",en:"AI is very useful in many fields, like healthcare and education."},{who:"bot",cn:"自动驾驶汽车也越来越成熟了。",en:"Self-driving cars are becoming more mature too."},{who:"you",cn:"对，但是安全性和隐私问题需要解决。",en:"Yes, but safety and privacy issues need to be resolved."},{who:"bot",cn:"机器学习和算法在不断进步。",en:"Machine learning and algorithms keep improving."},{who:"you",cn:"自动化会导致一些工作消失，但也会创造新的。",en:"Automation will eliminate some jobs but also create new ones."},{who:"bot",cn:"人类需要不断学习新技能。",en:"Humans need to keep learning new skills."},{who:"you",cn:"没错，适应变化是关键。",en:"Exactly, adapting to change is key."}]},
    {title:"Space Exploration (太空探索)",words:[{cn:"太空",py:"tài kōng",en:"outer space",tip:"Beyond Earth."},{cn:"探索",py:"tàn suǒ",en:"exploration",tip:"Discovery journey."},{cn:"宇航员",py:"yǔ háng yuán",en:"astronaut",tip:"Space traveler."},{cn:"卫星",py:"wèi xīng",en:"satellite",tip:"Orbiting device."},{cn:"火箭",py:"huǒ jiàn",en:"rocket",tip:"Space launch vehicle."},{cn:"轨道",py:"guǐ dào",en:"orbit",tip:"Path around a body."},{cn:"空间站",py:"kōng jiān zhàn",en:"space station",tip:"Habitat in space."},{cn:"宇宙",py:"yǔ zhòu",en:"universe / cosmos",tip:"All existing matter."}],dialogue:[
    {who:"bot",cn:"你对太空探索有兴趣吗？",en:"Are you interested in space exploration?"},{who:"you",cn:"非常有兴趣，人类探索宇宙的步伐越来越快。",en:"Very interested. Humanity's pace of space exploration is accelerating."},{who:"bot",cn:"你觉得人类什么时候能登陆火星？",en:"When do you think humans will land on Mars?"},{who:"you",cn:"可能在未来十年之内。技术发展很快。",en:"Possibly within the next decade. Technology is developing fast."},{who:"bot",cn:"空间站的国际合作很成功。",en:"The international cooperation on the space station has been very successful."},{who:"you",cn:"对，科学的进步需要全球合作。",en:"Yes, scientific progress requires global cooperation."},{who:"bot",cn:"探索宇宙让我们更加珍惜地球。",en:"Exploring the cosmos makes us cherish Earth more."},{who:"you",cn:"说得对，地球是我们唯一的家园。",en:"Well said. Earth is our only home."}]},
    {title:"Human Rights & Justice (人权与正义)",words:[{cn:"人权",py:"rén quán",en:"human rights",tip:"Fundamental rights."},{cn:"正义",py:"zhèng yì",en:"justice",tip:"Fairness / righteousness."},{cn:"法律",py:"fǎ lǜ",en:"law",tip:"Legal system."},{cn:"平等",py:"píng děng",en:"equality",tip:"Equal treatment."},{cn:"歧视",py:"qí shì",en:"discrimination",tip:"Unfair treatment."},{cn:"民主",py:"mín zhǔ",en:"democracy",tip:"Rule by the people."},{cn:"自由",py:"zì yóu",en:"freedom",tip:"Liberty of action."},{cn:"尊严",py:"zūn yán",en:"dignity",tip:"Worth as a person."}],dialogue:[
    {who:"bot",cn:"你怎么理解人权和正义？",en:"How do you understand human rights and justice?"},{who:"you",cn:"每个人都应该享有平等和尊严。",en:"Everyone should have equality and dignity."},{who:"bot",cn:"但是在很多地方歧视仍然存在。",en:"But discrimination still exists in many places."},{who:"you",cn:"我们需要法律来保护每个人的权利。",en:"We need laws to protect everyone's rights."},{who:"bot",cn:"正义不仅仅是法律上的，也是社会层面的。",en:"Justice isn't just legal, it's also social."},{who:"you",cn:"同意，教育和社会意识也很重要。",en:"Agreed. Education and social awareness are also important."},{who:"bot",cn:"自由和平等有时会有冲突。",en:"Freedom and equality can sometimes conflict."},{who:"you",cn:"需要在两者之间找到平衡。",en:"We need to find a balance between the two."}]}]},
    {level:"HSK 8",icon:"fa-brain",topics:[
    {title:"Cognitive Science (认知科学)",words:[{cn:"认知",py:"rèn zhī",en:"cognition",tip:"Mental process."},{cn:"记忆",py:"jì yì",en:"memory",tip:"Recall of information."},{cn:"注意力",py:"zhù yì lì",en:"attention",tip:"Focus of mind."},{cn:"语言",py:"yǔ yán",en:"language",tip:"System of communication."},{cn:"思维",py:"sī wéi",en:"thinking / thought",tip:"Mental activity."},{cn:"感知",py:"gǎn zhī",en:"perception",tip:"Awareness through senses."},{cn:"神经",py:"shén jīng",en:"nerve / neural",tip:"Neural network."},{cn:"意识",py:"yì shí",en:"consciousness",tip:"State of awareness."}],dialogue:[
    {who:"bot",cn:"认知科学研究人类思维的过程。",en:"Cognitive science studies the process of human thinking."},{who:"you",cn:"记忆和注意力是最基本的功能。",en:"Memory and attention are the most basic functions."},{who:"bot",cn:"语言习得也是认知科学的重要领域。",en:"Language acquisition is also an important area of cognitive science."},{who:"you",cn:"是的，了解语言习得可以帮助我学中文。",en:"Yes, understanding language acquisition can help me learn Chinese."},{who:"bot",cn:"感知和意识至今还有很多未解之谜。",en:"Perception and consciousness still have many unanswered mysteries."},{who:"you",cn:"神经科学的发展为认知研究提供了新工具。",en:"Neuroscience developments provide new tools for cognitive research."},{who:"bot",cn:"思维是大脑最神奇的功能。",en:"Thinking is the brain's most amazing function."},{who:"you",cn:"所以不断学习和思考很重要。",en:"That's why continuous learning and thinking are important."}]},
    {title:"Climate Change Policy (气候政策)",words:[{cn:"气候",py:"qì hòu",en:"climate",tip:"Weather conditions."},{cn:"排放",py:"pái fàng",en:"emission",tip:"Release of gases."},{cn:"碳",py:"tàn",en:"carbon",tip:"Chemical element."},{cn:"能源",py:"néng yuán",en:"energy",tip:"Power source."},{cn:"可再生",py:"kě zài shēng",en:"renewable",tip:"Naturally replenished."},{cn:"政策",py:"zhèng cè",en:"policy",tip:"Government plan."},{cn:"减排",py:"jiǎn pái",en:"emission reduction",tip:"Cutting emissions."},{cn:"巴黎协定",py:"bā lí xié dìng",en:"Paris Agreement",tip:"Global climate pact."}],dialogue:[
    {who:"bot",cn:"气候变化是当今最紧迫的全球议题之一。",en:"Climate change is one of the most urgent global issues today."},{who:"you",cn:"各国需要加强减排力度。",en:"Countries need to strengthen emission reduction efforts."},{who:"bot",cn:"巴黎协定提供了一个框架。",en:"The Paris Agreement provides a framework."},{who:"you",cn:"但是落实政策需要政治意愿和资金。",en:"But implementing policies requires political will and funding."},{who:"bot",cn:"可再生能源是解决方案的关键部分。",en:"Renewable energy is a key part of the solution."},{who:"you",cn:"太阳能和风能已经越来越便宜了。",en:"Solar and wind energy are already getting cheaper."},{who:"bot",cn:"每个人也可以做出改变，减少碳足迹。",en:"Everyone can also make changes to reduce their carbon footprint."},{who:"you",cn:"从节约能源开始，从小事做起。",en:"Start with saving energy, start with small things."}]},
    {title:"Media & Information Literacy (媒体素养)",words:[{cn:"媒体",py:"méi tǐ",en:"media",tip:"Mass communication."},{cn:"信息",py:"xìn xī",en:"information",tip:"Facts / data."},{cn:"虚假",py:"xū jiǎ",en:"false / fake",tip:"Not real."},{cn:"新闻",py:"xīn wén",en:"news",tip:"Recent reports."},{cn:"可信度",py:"kě xìn dù",en:"credibility",tip:"Trustworthiness."},{cn:"偏见",py:"piān jiàn",en:"bias",tip:"Partial perspective."},{cn:"核实",py:"hé shí",en:"verify / fact-check",tip:"Confirm truth."},{cn:"算法",py:"suàn fǎ",en:"algorithm",tip:"Computational process."}],dialogue:[
    {who:"bot",cn:"你觉得现在的信息环境怎么样？",en:"How do you find the current information environment?"},{who:"you",cn:"信息太多了，很难判断真假。",en:"There's too much information, it's hard to tell truth from fiction."},{who:"bot",cn:"虚假新闻和误导信息越来越多。",en:"Fake news and misinformation are increasing."},{who:"you",cn:"所以核实来源很重要。",en:"So it's important to verify sources."},{who:"bot",cn:"算法的推荐也造成了信息茧房。",en:"Algorithm recommendations also create information bubbles."},{who:"you",cn:"对，我们应该接触不同的观点。",en:"Right, we should expose ourselves to different viewpoints."},{who:"bot",cn:"媒体素养是现代人必备的技能。",en:"Media literacy is an essential skill for modern people."},{who:"you",cn:"是的，批判性思维可以帮助我们识别偏见。",en:"Yes, critical thinking can help us identify bias."}]},
    {title:"Public Health (公共卫生)",words:[{cn:"公共",py:"gōng gòng",en:"public",tip:"For the community."},{cn:"卫生",py:"wèi shēng",en:"hygiene / health",tip:"Cleanliness."},{cn:"疾病",py:"jí bìng",en:"disease",tip:"Illness condition."},{cn:"预防",py:"yù fáng",en:"prevention",tip:"Stop before onset."},{cn:"疫情",py:"yì qíng",en:"epidemic / pandemic",tip:"Widespread disease."},{cn:"医疗",py:"yī liáo",en:"medical care",tip:"Healthcare services."},{cn:"疫苗",py:"yì miáo",en:"vaccine",tip:"Immunization."},{cn:"WHO",py:"WHO",en:"World Health Organization",tip:"UN health agency."}],dialogue:[
    {who:"bot",cn:"疫情改变了世界对公共卫生的看法。",en:"The pandemic changed the world's view on public health."},{who:"you",cn:"预防比治疗更重要。",en:"Prevention is more important than treatment."},{who:"bot",cn:"疫苗的研发和分配是巨大的挑战。",en:"Vaccine development and distribution were huge challenges."},{who:"you",cn:"国际合作在疫情中发挥了关键作用。",en:"International cooperation played a key role in the pandemic."},{who:"bot",cn:"医疗系统的韧性非常重要。",en:"The resilience of healthcare systems is crucial."},{who:"you",cn:"未来应该加大对公共卫生的投资。",en:"There should be more investment in public health in the future."},{who:"bot",cn:"个人的卫生习惯也很重要。",en:"Personal hygiene habits are also very important."},{who:"you",cn:"经历了这些，大家更加重视健康了。",en:"After all this, people pay more attention to health."}]},
    {title:"Cultural Heritage Preservation (文化遗产保护)",words:[{cn:"遗产",py:"yí chǎn",en:"heritage",tip:"Inherited legacy."},{cn:"保护",py:"bǎo hù",en:"protection",tip:"Preservation effort."},{cn:"文物",py:"wén wù",en:"cultural relic",tip:"Historical object."},{cn:"修复",py:"xiū fù",en:"restoration",tip:"Repair to original."},{cn:"博物馆",py:"bó wù guǎn",en:"museum",tip:"Exhibition building."},{cn:"非物质",py:"fēi wù zhì",en:"intangible",tip:"Not physical."},{cn:"传统",py:"chuán tǒng",en:"tradition",tip:"Custom handed down."},{cn:"联合国教科文组织",py:"lián hé guó jiào kē wén zǔ zhī",en:"UNESCO",tip:"UN cultural agency."}],dialogue:[
    {who:"bot",cn:"文化遗产保护为什么重要？",en:"Why is cultural heritage preservation important?"},{who:"you",cn:"文化遗产记录了人类的历史和智慧。",en:"Cultural heritage records human history and wisdom."},{who:"bot",cn:"很多文物面临损坏和消失的风险。",en:"Many relics face the risk of damage and disappearance."},{who:"you",cn:"所以修复和保护工作非常紧迫。",en:"So restoration and protection efforts are very urgent."},{who:"bot",cn:"非物质文化遗产也需要传承。",en:"Intangible cultural heritage also needs to be passed on."},{who:"you",cn:"比如传统手工艺和表演艺术。",en:"Like traditional crafts and performing arts."},{who:"bot",cn:"博物馆是保护和展示的重要场所。",en:"Museums are important places for preservation and display."},{who:"you",cn:"我们应该支持UNESCO的这些工作。",en:"We should support UNESCO's work in this area."}]}]},
    {level:"HSK 9",icon:"fa-university",topics:[
    {title:"Quantum Computing (量子计算)",words:[{cn:"量子",py:"liàng zǐ",en:"quantum",tip:"Discrete energy unit."},{cn:"计算",py:"jì suàn",en:"computing",tip:"Mathematical operation."},{cn:"比特",py:"bǐ tè",en:"bit",tip:"Binary digit."},{cn:"量子比特",py:"liàng zǐ bǐ tè",en:"qubit",tip:"Quantum bit."},{cn:"叠加",py:"dié jiā",en:"superposition",tip:"Multiple states at once."},{cn:"纠缠",py:"jiū chán",en:"entanglement",tip:"Linked quantum states."},{cn:"密码学",py:"mì mǎ xué",en:"cryptography",tip:"Secure communication."},{cn:"突破",py:"tū pò",en:"breakthrough",tip:"Major advance."}],dialogue:[
    {who:"bot",cn:"量子计算是计算技术的下一个前沿。",en:"Quantum computing is the next frontier in computing technology."},{who:"you",cn:"与传统计算相比，它的优势在哪里？",en:"What are its advantages compared to traditional computing?"},{who:"bot",cn:"量子比特利用叠加和纠缠可以同时处理大量数据。",en:"Qubits use superposition and entanglement to process massive data simultaneously."},{who:"you",cn:"那密码学是不是会受到威胁？",en:"Then will cryptography be threatened?"},{who:"bot",cn:"是的，量子计算可能破解当前的加密方法。",en:"Yes, quantum computing could break current encryption methods."},{who:"you",cn:"但同时也会催生新的量子密码学。",en:"But it will also give rise to new quantum cryptography."},{who:"bot",cn:"这项技术还在早期阶段，但进展很快。",en:"This technology is still in early stages but progressing rapidly."},{who:"you",cn:"期待未来有更多突破。",en:"Looking forward to more breakthroughs in the future."}]},
    {title:"Neuroscience & Consciousness (神经科学)",words:[{cn:"神经科学",py:"shén jīng kē xué",en:"neuroscience",tip:"Study of the nervous system."},{cn:"大脑",py:"dà nǎo",en:"brain",tip:"Central organ."},{cn:"神经",py:"shén jīng",en:"nerve",tip:"Signal transmitter."},{cn:"突触",py:"tū chù",en:"synapse",tip:"Neural connection."},{cn:"可塑性",py:"kě sù xìng",en:"plasticity",tip:"Ability to change."},{cn:"意识",py:"yì shí",en:"consciousness",tip:"Subjective awareness."},{cn:"脑机",py:"nǎo jī",en:"brain-computer",tip:"BCI technology."},{cn:"成像",py:"chéng xiàng",en:"imaging",tip:"Visualization technique."}],dialogue:[
    {who:"bot",cn:"神经科学探索大脑的奥秘。",en:"Neuroscience explores the mysteries of the brain."},{who:"you",cn:"大脑的可塑性说明我们可以终生学习。",en:"The brain's plasticity shows we can learn throughout our lives."},{who:"bot",cn:"意识是如何产生的仍然是一个哲学问题。",en:"How consciousness arises is still a philosophical question."},{who:"you",cn:"脑机接口技术发展很快，未来可能改变人类。",en:"BCI technology is developing fast and may change humanity."},{who:"bot",cn:"成像技术让研究者可以观察大脑活动。",en:"Imaging technology lets researchers observe brain activity."},{who:"you",cn:"这对治疗神经疾病有很大帮助。",en:"This greatly helps in treating neurological diseases."},{who:"bot",cn:"神经科学和人工智能有很深的联系。",en:"Neuroscience and AI are deeply connected."},{who:"you",cn:"人类大脑仍然是最高效的计算机。",en:"The human brain is still the most efficient computer."}]},
    {title:"Global Migration & Society (全球移民)",words:[{cn:"移民",py:"yí mín",en:"migration / immigrant",tip:"Moving to another country."},{cn:"难民",py:"nàn mín",en:"refugee",tip:"Person fleeing danger."},{cn:"国籍",py:"guó jí",en:"nationality",tip:"Country membership."},{cn:"多元",py:"duō yuán",en:"diverse / pluralistic",tip:"Variety of types."},{cn:"融合",py:"róng hé",en:"integration",tip:"Blend into society."},{cn:"边境",py:"biān jìng",en:"border",tip:"National boundary."},{cn:"签证",py:"qiān zhèng",en:"visa",tip:"Entry permit."},{cn:"全球化",py:"quán qiú huà",en:"globalization",tip:"World integration."}],dialogue:[
    {who:"bot",cn:"全球移民是一个复杂的话题。",en:"Global migration is a complex topic."},{who:"you",cn:"人们移民的原因包括经济机会和逃避冲突。",en:"Reasons include economic opportunity and fleeing conflict."},{who:"bot",cn:"难民问题需要国际社会的共同努力。",en:"The refugee issue requires joint efforts from the international community."},{who:"you",cn:"多元文化社会既有挑战也有机遇。",en:"Multicultural societies have both challenges and opportunities."},{who:"bot",cn:"融合政策可以帮助移民更好地适应。",en:"Integration policies can help immigrants adapt better."},{who:"you",cn:"尊重文化差异是共处的基础。",en:"Respecting cultural differences is the foundation of coexistence."},{who:"bot",cn:"全球化让移民变得更加普遍。",en:"Globalization has made migration more common."},{who:"you",cn:"未来可能会有更多人口流动。",en:"There may be even more population movement in the future."}]},
    {title:"Ethics of Genetic Engineering (基因伦理)",words:[{cn:"基因",py:"jī yīn",en:"gene",tip:"DNA segment."},{cn:"编辑",py:"biān jí",en:"editing",tip:"Modify precisely."},{cn:"胚胎",py:"pēi tāi",en:"embryo",tip:"Early developmental stage."},{cn:"优生",py:"yōu shēng",en:"eugenics",tip:"Improving genetics."},{cn:"突变",py:"tū biàn",en:"mutation",tip:"Genetic change."},{cn:"伦理",py:"lún lǐ",en:"ethics",tip:"Moral framework."},{cn:"治疗",py:"zhì liáo",en:"therapy",tip:"Medical treatment."},{cn:"增强",py:"zēng qiáng",en:"enhancement",tip:"Improve beyond normal."}],dialogue:[
    {who:"bot",cn:"基因编辑技术带来了前所未有的伦理挑战。",en:"Gene editing technology brings unprecedented ethical challenges."},{who:"you",cn:"治疗疾病是一回事，增强能力是另一回事。",en:"Treating disease is one thing, enhancing abilities is another."},{who:"bot",cn:"优生学的历史提醒我们需要谨慎。",en:"The history of eugenics reminds us to be cautious."},{who:"you",cn:"胚胎编辑可能会影响后代。",en:"Embryo editing could affect future generations."},{who:"bot",cn:"所以很多国家严格限制这类研究。",en:"That's why many countries strictly limit such research."},{who:"you",cn:"科学需要伦理框架的指导。",en:"Science needs ethical frameworks to guide it."},{who:"bot",cn:"公众讨论和透明决策非常重要。",en:"Public discussion and transparent decision-making are crucial."},{who:"you",cn:"这是一个关系到人类未来的重要议题。",en:"This is an important issue concerning humanity's future."}]},
    {title:"Philosophy of Science (科学哲学)",words:[{cn:"科学哲学",py:"kē xué zhé xué",en:"philosophy of science",tip:"Study of scientific foundations."},{cn:"范式",py:"fàn shì",en:"paradigm",tip:"Framework of theories."},{cn:"验证",py:"yàn zhèng",en:"verification",tip:"Confirm truth."},{cn:"可证伪",py:"kě zhèng wěi",en:"falsifiability",tip:"Capable of being disproven."},{cn:"归纳",py:"guī nà",en:"induction",tip:"Generalize from specifics."},{cn:"演绎",py:"yǎn yì",en:"deduction",tip:"Reason from premises."},{cn:"范式转换",py:"fàn shì zhuǎn huàn",en:"paradigm shift",tip:"Fundamental change in approach."},{cn:"客观",py:"kè guān",en:"objective",tip:"Unbiased reality."}],dialogue:[
    {who:"bot",cn:"科学哲学探讨科学方法的本质。",en:"Philosophy of science explores the nature of the scientific method."},{who:"you",cn:"可证伪性是区分科学和非科学的重要标准。",en:"Falsifiability is an important criterion for distinguishing science from non-science."},{who:"bot",cn:"范式转换理论是库恩的重要贡献。",en:"Paradigm shift theory is Kuhn's major contribution."},{who:"you",cn:"科学进步不是线性的，而是革命性的。",en:"Scientific progress is not linear but revolutionary."},{who:"bot",cn:"客观性是科学的理想，但很难完全达到。",en:"Objectivity is science's ideal, but hard to fully achieve."},{who:"you",cn:"归纳和演绎是科学家常用的推理方法。",en:"Induction and deduction are common reasoning methods used by scientists."},{who:"bot",cn:"科学知识是不断修正和进步的。",en:"Scientific knowledge is constantly revised and advanced."},{who:"you",cn:"这也是科学之所以可靠的原因。",en:"That's also what makes science reliable."}]}]}];
  for (var l = 0; l < levelData.length; l++) {
    var ld = levelData[l];
    if (ld.level === levelName) {
      var out = [];
      for (var t = 0; t < ld.topics.length; t++) {
        var tp = ld.topics[t];
        out.push({id:levelIdx * 10 + t + 1, level:levelName, title:tp.title, icon:ld.icon, desc:"Practice " + ld.level + " with dialogues, vocabulary and exercises.", words:tp.words, dialogue:tp.dialogue});
      }
      return out;
    }
  }
  return [];
}

