// ===== PODCAST MODE =====
let podQueue = [];
let podIdx = 0;
let podLineIdx = 0;
let podPlaying = false;
let podSpeedRate = 1.0;
let podTimer = null;

function podcastTopic(topicName) {
  var lessons = getLessonsForLevel(curLv);
  if (lessons.length === 0) return toast(t('No lesson data found'), 'var(--accent2)');
  podQueue = lessons;
  podIdx = 0;
  podLineIdx = 0;
  showPodcastPlayer();
  updatePodDisplay();
  podPlay();
}

function buildPodcastTopics() {
  const g = document.getElementById('tpGrid');
  if (!g) return;
  g.innerHTML = '';
  const lv = LV[curLv];
  lv.tp.forEach(function(topicName) {
    const ls = TD[topicName] || ['L1','L2','L3'];
    const d = document.createElement('div');
    d.className = 'cd p-5 cursor-pointer';
    d.onclick = function() { podcastTopic(topicName); };
    d.innerHTML = '<div class="flex items-start justify-between mb-3"><div><h3 class="font-bold text-sm mb-1">'+t(topicName)+'</h3><p class="text-xs" style="color:var(--muted)">'+ls.length+' '+t('lessons')+'</p></div><span class="w-8 h-8 rounded-full flex items-center justify-center" style="background:var(--accent);color:#fff"><i class="fas fa-play text-xs"></i></span></div><div style="height:3px;background:var(--card2);border-radius:2px;overflow:hidden"><div style="width:0%;height:100%;background:var(--accent);border-radius:2px;transition:width .3s"></div></div><div class="text-[10px] font-semibold mt-2" style="color:var(--muted)"><i class="fas fa-headphones mr-1"></i>'+t('Tap to listen to all lessons')+'</div>';
    g.appendChild(d);
  });
}

function showPodcastPlayer() {
  const el = document.getElementById('podcastPlayer');
  if (el) el.style.transform = 'translateY(0)';
  const mn = document.querySelector('.mn');
  if (mn) mn.style.bottom = '84px';
}

function hidePodcastPlayer() {
  const el = document.getElementById('podcastPlayer');
  if (el) el.style.transform = 'translateY(100%)';
  const mn = document.querySelector('.mn');
  if (mn) mn.style.bottom = '0';
  podStop();
}

function podPlay() {
  if (podQueue.length === 0) return;
  podPlaying = true;
  var btn = document.getElementById('podPlayBtn');
  if (btn) btn.innerHTML = '<i class="fas fa-pause text-sm"></i>';
  podPlayLine();
}

function podPause() {
  podPlaying = false;
  var btn = document.getElementById('podPlayBtn');
  if (btn) btn.innerHTML = '<i class="fas fa-play text-sm"></i>';
  if (podTimer) { clearTimeout(podTimer); podTimer = null; }
  try { if (!isMobileDevice) window.speechSynthesis.cancel(); } catch(e) {}
}

function podToggle() {
  if (podPlaying) podPause();
  else podPlay();
}

function podStop() {
  podPause();
  podQueue = [];
  podIdx = 0;
  podLineIdx = 0;
}

function podNext() {
  try { window.speechSynthesis.cancel(); } catch(e) {}
  if (podTimer) { clearTimeout(podTimer); podTimer = null; }
  podIdx = Math.min(podIdx + 1, podQueue.length - 1);
  podLineIdx = 0;
  updatePodDisplay();
  if (podPlaying) setTimeout(function() { podPlayLine(); }, 300);
}

function podPrev() {
  try { window.speechSynthesis.cancel(); } catch(e) {}
  if (podTimer) { clearTimeout(podTimer); podTimer = null; }
  podIdx = Math.max(podIdx - 1, 0);
  podLineIdx = 0;
  updatePodDisplay();
  if (podPlaying) setTimeout(function() { podPlayLine(); }, 300);
}

function podSpeed() {
  var rates = [0.5, 0.7, 1.0, 1.25, 1.5, 2.0];
  var cur = rates.indexOf(podSpeedRate);
  podSpeedRate = rates[(cur + 1) % rates.length];
  var btn = document.getElementById('podSpeedBtn');
  if (btn) btn.textContent = podSpeedRate + 'x';
}

function podDownload() {
  var lesson = podQueue[podIdx];
  if (!lesson) return;
  var epId = 'ep' + (podIdx + 1);
  window.open('/api/podcast-download/' + epId, '_blank');
  toast(t('Downloading podcast episode...'), 'var(--green)', 2000);
}

function updatePodDisplay() {
  var lesson = podQueue[podIdx];
  if (!lesson) return;
  var titleEl = document.getElementById('podTitle');
  var subEl = document.getElementById('podSub');
  var progEl = document.getElementById('podProgress');
  if (titleEl) titleEl.textContent = t(lesson.title);
  if (subEl) subEl.textContent = lesson.level + ' \u00B7 ' + (podIdx + 1) + '/' + podQueue.length;
  if (progEl) progEl.style.width = ((podIdx) / Math.max(1, podQueue.length - 1) * 100) + '%';
}

var _podTrCache = {};

function podTranslate(text, lang, cb) {
  if (lang === 'en' || lang === 'en-US') { cb(text); return; }
  var key = lang + '|' + text;
  if (_podTrCache[key]) { cb(_podTrCache[key]); return; }
  var langName = ({es:'Spanish',fr:'French',ja:'Japanese',ko:'Korean',de:'German',pt:'Portuguese',it:'Italian',ru:'Russian',vi:'Vietnamese'})[lang] || 'English';
  fetch('/api/chat', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body:JSON.stringify({contents:[{role:'user',parts:[{text:text}]}],systemInstruction:'Translate to '+langName+'. Reply ONLY with the translation. No quotes, no extra text.'})
  }).then(function(r){return r.json();}).then(function(data){
    var reply = data?.candidates?.[0]?.content?.parts?.[0]?.text || text;
    reply = reply.replace(/^["']|["']$/g,'').trim();
    _podTrCache[key] = reply;
    cb(reply);
  }).catch(function(){cb(text);});
}

function getVoiceForLang(lang) {
  if (lang === 'zh-CN') return getChineseVoice();
  var allVoices = speechSynthesis.getVoices();
  var voices = allVoices.filter(function(v) { return v.lang.startsWith(lang.split('-')[0]); });
  if (voices.length === 0) {
    // Retry once after voices load
    if (typeof speechSynthesis.onvoiceschanged !== 'undefined') {
      try { speechSynthesis.onvoiceschanged = null; } catch(e) {}
    }
    return null;
  }
  var langPrefix = lang.split('-')[0];
  var preferred = {};
  preferred.vi = ['microsoft an - vietnamese','microsoft an','an vietnam','an viet','female vietnam','vietnamese','online vietnam','neural vietnam'];
  preferred.es = ['helena','sara','enrica','isabella','elena','jordi','antoni','garcia','neural','natural','premium','online','enhanced'];
  preferred.fr = ['denise','yvette','cecile','sylvie','jean','pierre','renaud','nicole','brigitte','claire','julie','nathalie','amelie','neural','natural','premium','online','enhanced'];
  preferred.ja = ['nanami','ayane','shiori','seiichi','haruka','hina','moe','yuna','tomoko','sumi','kyoko','neural','natural','premium','online','enhanced'];
  preferred.ko = ['inpyo','sunhi','seoyeon','nuri','jina','namu','neural','natural','premium','online','enhanced'];
  preferred.de = ['katja','heike','hans','claus','louise','thomas','anna','ingrid','hanna','stefan','petra','neural','natural','premium','online','enhanced'];
  preferred.pt = ['marcos','carla','leticia','joana','luciana','felipe','neural','natural','premium','online','enhanced'];
  preferred.it = ['elisa','federica','fabiola','andrea','pierpaolo','simona','barbara','neural','natural','premium','online','enhanced'];
  preferred.ru = ['iveta','katya','milena','dariya','marina','neural','natural','premium','online','enhanced'];
  // Try matching voice name or any female/localized name
  var langPrefs = preferred[langPrefix] || ['neural','natural','premium','online','enhanced','female'];
  for (var i = 0; i < langPrefs.length; i++) {
    var found = voices.find(function(v) { return v.name.toLowerCase().includes(langPrefs[i]); });
    if (found) return found;
  }
  // Try to find a voice with a proper name (Microsoft/Google voices with a space in the name)
  var nameVoice = voices.find(function(v) { return /[a-z]{3,} [a-z]{3,}/i.test(v.name); });
  if (nameVoice) return nameVoice;
  return voices.length > 0 ? voices[0] : null;
}

function podSpeakViaApi(text, lang, cb) {
  fetch('/api/tts', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({text:text, lang:lang, speed:podSpeedRate}) })
  .then(function(r) { if (!r.ok) throw new Error('TTS API error'); return r.blob(); })
  .then(function(blob) {
    var url = URL.createObjectURL(blob);
    var a = new Audio(url);
    a.onended = function() { URL.revokeObjectURL(url); if (cb) cb(); };
    a.onerror = function() { URL.revokeObjectURL(url); if (cb) cb(); };
    a.play().catch(function(){if(cb)cb();});
  })
  .catch(function(){if(cb)cb();});
}

function podSpeak(text, lang, cb) {
  if (!window.speechSynthesis) { if (cb) cb(); return; }
  // Try browser TTS for all languages first
  var u = new SpeechSynthesisUtterance(text);
  u.lang = lang || 'zh-CN';
  u.rate = podSpeedRate;
  var voice = getVoiceForLang(lang);
  if (voice) {
    u.voice = voice;
    u.onend = function() { if (cb) cb(); };
    u.onerror = function() { if (cb) cb(); };
    try { speechSynthesis.speak(u); } catch(e) { if (cb) cb(); }
    return;
  }
  // Fallback to API TTS if no browser voice found
  podSpeakViaApi(text, lang, cb);
}

function podLangCode() {
  var map = {es:'es-ES',fr:'fr-FR',ja:'ja-JP',ko:'ko-KR',de:'de-DE',pt:'pt-BR',it:'it-IT',ru:'ru-RU',vi:'vi-VN'};
  return map[currentAppLang] || 'en-US';
}

function podPlayLine() {
  if (!podPlaying) return;
  var lesson = podQueue[podIdx];
  if (!lesson) { podPause(); return; }
  var lines = lesson.dialogue;
  if (!lines || podLineIdx >= lines.length) {
    if (podIdx < podQueue.length - 1) {
      podIdx++;
      podLineIdx = 0;
      updatePodDisplay();
      podTimer = setTimeout(function() { podPlayLine(); }, 1000);
    } else {
      podPause();
      var progEl = document.getElementById('podProgress');
      if (progEl) progEl.style.width = '100%';
      toast(t('Podcast complete!') + ' \u{1F44D}', 'var(--gold)');
    }
    return;
  }
  var line = lines[podLineIdx];
  podSpeak(line.cn, 'zh-CN', function() {
    var trLang = currentAppLang === 'en' ? 'en' : currentAppLang;
    podTranslate(line.en, trLang, function(trText) {
      podSpeak(trText, trLang === 'en' ? 'en-US' : podLangCode(), function() {
        podLineIdx++;
        var totalLines = 0;
        var passedLines = 0;
        for (var i = 0; i < podQueue.length; i++) {
          var ls = podQueue[i].dialogue;
          if (!ls) continue;
          if (i < podIdx) passedLines += ls.length;
          else if (i === podIdx) passedLines += podLineIdx;
          totalLines += ls.length;
        }
        var pct = totalLines > 0 ? (passedLines / totalLines) * 100 : 0;
        var progEl = document.getElementById('podProgress');
        if (progEl) progEl.style.width = pct + '%';
        podTimer = setTimeout(function() { podPlayLine(); }, 500);
      });
    });
  });
}

function podClose() {
  podStop();
  hidePodcastPlayer();
}


