async function saveReminderSettings() {
  const interval = document.getElementById('reminderIntervalSelect').value;
  const time = document.getElementById('reminderTimeInput').value;
  localStorage.setItem('reminder_interval', interval);
  localStorage.setItem('reminder_time', time);
  
  if (interval === 'none') {
    if (typeof Capacitor !== 'undefined' && Capacitor.isNativePlatform()) {
      try {
        const { LocalNotifications } = Capacitor.Plugins;
        if (LocalNotifications) await LocalNotifications.cancel({ notifications: [{ id: 1 }] });
      } catch(e) { console.error(e); }
    }
    toast(t("Study Reminders turned off."), "var(--gold)");
    return;
  }
  
  const [hours, minutes] = time.split(':').map(Number);
  const isNative = typeof Capacitor !== 'undefined' && Capacitor.isNativePlatform();
  
  if (isNative) {
    try {
      const { LocalNotifications } = Capacitor.Plugins;
      if (LocalNotifications) {
        const permResult = await LocalNotifications.requestPermissions();
        if (permResult.display === 'granted') {
          await LocalNotifications.cancel({ notifications: [{ id: 1 }] });
          await LocalNotifications.schedule({
            notifications: [
              {
                title: "Time to study Chinese! 汉",
                body: "Keep up your streak and review your flashcards on MandarinCourse!",
                id: 1,
                schedule: {
                  every: interval === 'daily' ? 'day' : 'week',
                  on: { hour: hours, minute: minutes }
                }
              }
            ]
          });
          toast(t("Native reminders scheduled successfully!"), "var(--green)");
        } else {
          toast(t("Notification permission denied."), "var(--accent)");
        }
      }
    } catch(err) {
      console.error(err);
      toast(t("Failed scheduling native notifications."), "var(--accent)");
    }
  } else {
    if ('Notification' in window) {
      const permission = await Notification.requestPermission();
      if (permission === 'granted') {
        if ('serviceWorker' in navigator) {
          navigator.serviceWorker.ready.then(registration => {
            registration.showNotification("Study Reminders Active", {
              body: `We will remind you ${interval} at ${time}!`,
              icon: "/icon-192.png"
            });
          });
        }
        toast(t("Web reminders scheduled: ") + interval + t(" at ") + time, "var(--green)");
      } else {
        toast(t("Notification permissions denied."), "var(--accent)");
      }
    } else {
      toast(t("Browser does not support notifications."), "var(--accent)");
    }
  }
  // Save to server for email reminders if signed in
  if (typeof supabaseClient !== 'undefined' && supabaseClient) {
    supabaseClient.auth.getSession().then(function(s) {
      if (s.data.session && s.data.session.user.email) {
        fetch('/api/save-reminder', { method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({email:s.data.session.user.email, frequency:interval, time:time, timezone:Intl.DateTimeFormat().resolvedOptions().timeZone}) }).catch(function(){});
      }
    });
  }
}

function editProfile() {
  var nameInput = document.getElementById('profileNameInput');
  var saveBtn = document.getElementById('saveProfileBtn');
  var editBtn = document.getElementById('editProfileBtn');
  nameInput.style.display = 'block';
  nameInput.value = localStorage.getItem('user_display_name') || '';
  nameInput.focus();
  saveBtn.style.display = 'block';
  editBtn.style.display = 'none';
}

async function saveProfile() {
  var name = document.getElementById('profileNameInput').value.trim();
  if (!name) return toast(t('Enter a display name.'), 'var(--accent)');
  localStorage.setItem('user_display_name', name);
  updateProfileDisplay();
  if (typeof supabaseClient !== 'undefined' && supabaseClient) {
    var s = await supabaseClient.auth.getSession();
    if (s.data.session) {
      try {
        await supabaseClient.from('user_profiles').upsert({ user_id:s.data.session.user.id, display_name:name, updated_at:new Date().toISOString() }, { onConflict:'user_id' });
      } catch(e) { console.error('saveProfile sync error:', e); }
    }
  }
  document.getElementById('profileNameInput').style.display = 'none';
  document.getElementById('saveProfileBtn').style.display = 'none';
  document.getElementById('editProfileBtn').style.display = 'block';
  toast(t('Profile saved!'), 'var(--green)');
}

function updateProfileDisplay() {
  var name = localStorage.getItem('user_display_name') || '';
  var emailEl = document.getElementById('userEmailDisplay');
  var nameEl = document.getElementById('userDisplayName');
  var avatarEl = document.getElementById('userAvatar');
  if (name && nameEl && avatarEl) {
    nameEl.textContent = name;
    avatarEl.style.display = 'flex';
    avatarEl.textContent = name.charAt(0).toUpperCase();
    avatarEl.style.background = name.charCodeAt(0) % 2 ? 'rgba(212,166,79,.2)' : 'rgba(72,152,213,.2)';
    avatarEl.style.color = name.charCodeAt(0) % 2 ? 'var(--gold)' : '#4898D5';
  } else if (emailEl && nameEl) {
    nameEl.textContent = emailEl.textContent ? emailEl.textContent.split('@')[0] : '';
  }
}

function loadProfile() {
  updateProfileDisplay();
  var nameInput = document.getElementById('profileNameInput');
  var saveBtn = document.getElementById('saveProfileBtn');
  var editBtn = document.getElementById('editProfileBtn');
  if (nameInput) nameInput.style.display = 'none';
  if (saveBtn) saveBtn.style.display = 'none';
  if (editBtn) editBtn.style.display = 'block';
  // Load from Supabase if signed in
  if (typeof supabaseClient !== 'undefined' && supabaseClient) {
    supabaseClient.auth.getSession().then(function(s) {
      if (s.data && s.data.session) {
        supabaseClient.from('user_profiles').select('display_name').eq('user_id', s.data.session.user.id).single().then(function(r) {
          if (r.data && r.data.display_name) {
            localStorage.setItem('user_display_name', r.data.display_name);
            updateProfileDisplay();
          }
        }).catch(function(){});
      }
    }).catch(function(){});
  }
}

